passing_property:
// Y matches the implemented NAND of (~B1_N) and (A1 | A2).
    check_function_equivalence: assert property (
        @(posedge clk) Y == ~((~B1_N) & (A1 | A2))
    );

// With B1_N high, both A inputs low force the OR term low and Y high.
    check_a_inputs_low_force_y_high: assert property (
        @(posedge clk) (B1_N && !A1 && !A2) |-> Y
    );

// A low Y requires B1_N low or the OR term high.
    check_y_low_requires_b1n_low_or_or_high: assert property (
        @(posedge clk) !Y |-> (!B1_N || (A1 || A2))
    );

// y must match the implemented 2:1 mux equation.
    check_mux_equation: assert property (
        @(posedge clk) y == ((~sel & a) | (sel & b))
    );

// When sel is low, y must follow a.
    check_sel_low_routes_a: assert property (
        @(posedge clk) !sel |-> (y == a)
    );

// When sel is high, y must follow b.
    check_sel_high_routes_b: assert property (
        @(posedge clk) sel |-> (y == b)
    );

// When sel is 00, out must select data0.
    check_sel_00_selects_data0: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == data0)
    );

// When sel is 01, out must select data1.
    check_sel_01_selects_data1: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out == data1)
    );

// When sel is 10, out must select data2.
    check_sel_10_selects_data2: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out == data2)
    );

// When sel is 11, out must select data3.
    check_sel_11_selects_data3: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == data3)
    );

// With sel[1] high, the top-level mux selects the high pair result.
    check_sel1_high_uses_high_pair_result: assert property (
        @(posedge clk) (sel[1] == 1'b1) |-> (out == (sel[0] ? data1 : data0))
    );

// Len_int is high when both n63 and Z_B are high.
    check_len_int_high_when_both_high: assert property (
        @(posedge clk)
        (n63 & Z_B) |-> Len_int
    );

// Len_int is low when n63 is high and Z_B is low.
    check_len_int_low_when_n63_high_zb_low: assert property (
        @(posedge clk)
        (n63 & ~Z_B) |-> !Len_int
    );

// Len_int is low when n63 is low and Z_B is high.
    check_len_int_low_when_n63_low_zb_high: assert property (
        @(posedge clk)
        (~n63 & Z_B) |-> !Len_int
    );

// Reset drives q to zero on the next clock.
    reset_clears_q_next: assert property (
        @(posedge clk) reset |=> (q == 4'b0000)
    );

// When enabled, q increments by 1 on the next clock.
    increment_when_enabled: assert property (
        @(posedge clk) disable iff (reset) enable |=> (q == $past(q) + 4'd1)
    );

// When not enabled, q holds its value on the next clock.
    hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset) !enable |=> (q == $past(q))
    );

// If enabled and q is 4'hF, it wraps to 4'h0 on the next clock.
    wrap_on_max: assert property (
        @(posedge clk) disable iff (reset) (enable && (q == 4'hF)) |=> (q == 4'h0)
    );

// If reset and enable are both high, reset has priority and q becomes 0 on the next clock.
    reset_priority_over_enable: assert property (
        @(posedge clk) (reset && enable) |=> (q == 4'h0)
    );

// If reset is held high across consecutive clocks, q remains 0.
    reset_held_keeps_q_zero: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (q == 4'h0)
    );

// If enable is held high across consecutive clocks and q is 4'hF, it wraps to 4'h0.
    enable_held_wraps: assert property (
        @(posedge clk) disable iff (reset) (enable && $past(enable) && ($past(q) == 4'hF)) |-> (q == 4'h0)
    );

// If reset is high and enable is low, q remains 0 on the next clock.
    reset_high_disable_low_keeps_zero: assert property (
        @(posedge clk) (reset && !enable) |=> (q == 4'h0)
    );

// X must equal the AND of A1, A2, B1, and VPWR.
    check_x_matches_and_function: assert property (
        @(posedge clk) X == (A1 & A2 & B1 & VPWR)
    );

// X can be high only when all four AND inputs are high.
    check_x_high_requires_all_inputs_high: assert property (
        @(posedge clk) X |-> (A1 && A2 && B1 && VPWR)
    );

// All four AND inputs high must drive X high.
    check_all_inputs_high_drive_x_high: assert property (
        @(posedge clk) (A1 && A2 && B1 && VPWR) |-> X
    );

// A low A1 input must force X low.
    check_a1_low_forces_x_low: assert property (
        @(posedge clk) !A1 |-> !X
    );

// A low A2 input must force X low.
    check_a2_low_forces_x_low: assert property (
        @(posedge clk) !A2 |-> !X
    );

// A low B1 input must force X low.
    check_b1_low_forces_x_low: assert property (
        @(posedge clk) !B1 |-> !X
    );

// A low VPWR input must force X low.
    check_vpwr_low_forces_x_low: assert property (
        @(posedge clk) !VPWR |-> !X
    );

// X must match the implemented AND/NOT function.
    check_functional_equivalence: assert property (
        @(posedge clk) X == (SLEEP_B & A)
    );

// When sleep is asserted, X must be low.
    check_sleep_forces_low: assert property (
        @(posedge clk) !SLEEP_B |-> !X
    );

// When sleep is deasserted, X must follow A.
    check_awake_follows_a: assert property (
        @(posedge clk) SLEEP_B |-> (X == A)
    );

// A low forces X low regardless of sleep.
    check_a_low_forces_low: assert property (
        @(posedge clk) !A |-> !X
    );

// With sleep deasserted and A high, X must be high.
    check_awake_a_high_sets_x: assert property (
        @(posedge clk) (SLEEP_B & A) |-> X
    );

// Y matches the implemented NOR-of-ANDs function.
    check_y_matches_function: assert property (
        @(posedge clk) Y == ~((B1 & B2) | C1 | (A1 & A2))
    );

// C1 high forces the NOR output low.
    check_c1_forces_y_low: assert property (
        @(posedge clk) C1 |-> !Y
    );

// B1 and B2 high force the NOR output low.
    check_b_pair_forces_y_low: assert property (
        @(posedge clk) (B1 & B2) |-> !Y
    );

// A1 and A2 high force the NOR output low.
    check_a_pair_forces_y_low: assert property (
        @(posedge clk) (A1 & A2) |-> !Y
    );

// With no active NOR input term, Y is high.
    check_no_active_term_drives_y_high: assert property (
        @(posedge clk) (!C1 && !(B1 & B2) && !(A1 & A2)) |-> Y
    );

// A high Y means no NOR input term is active.
    check_y_high_means_no_active_term: assert property (
        @(posedge clk) Y |-> (!C1 && !(B1 & B2) && !(A1 & A2))
    );

// A low Y means at least one NOR input term is active.
    check_y_low_means_active_term: assert property (
        @(posedge clk) !Y |-> (C1 || (B1 & B2) || (A1 & A2))
    );

// Y must equal the NOR of all four inputs.
    check_nor_function: assert property (
        @(posedge clk) Y == ~(A | B | C | D)
    );

// All inputs low must drive Y high.
    check_all_inputs_low_drives_y_high: assert property (
        @(posedge clk) (!A && !B && !C && !D) |-> Y
    );

// Any high input must drive Y low.
    check_any_input_high_drives_y_low: assert property (
        @(posedge clk) (A || B || C || D) |-> !Y
    );

// A high Y means all inputs are low.
    check_y_high_implies_all_inputs_low: assert property (
        @(posedge clk) Y |-> (!A && !B && !C && !D)
    );

// A low Y means at least one input is high.
    check_y_low_implies_any_input_high: assert property (
        @(posedge clk) !Y |-> (A || B || C || D)
    );

// Y matches the implemented OR-OR-NAND function.
    check_function_equivalence: assert property (
        @(posedge clk) Y == ~((A1 | A2) & (B1 | B2) & C1)
    );

// C1 low forces the NAND output high.
    check_c1_low_forces_y_high: assert property (
        @(posedge clk) !C1 |-> Y
    );

// Both A inputs low force the NAND output high.
    check_a_inputs_low_force_y_high: assert property (
        @(posedge clk) !(A1 | A2) |-> Y
    );

// Both B inputs low force the NAND output high.
    check_b_inputs_low_force_y_high: assert property (
        @(posedge clk) !(B1 | B2) |-> Y
    );

// All three active terms force the NAND output low.
    check_all_terms_active_force_y_low: assert property (
        @(posedge clk) (C1 && (A1 | A2) && (B1 | B2)) |-> !Y
    );

// A low Y requires C1 and at least one A and one B term.
    check_y_low_requires_all_terms_active: assert property (
        @(posedge clk) !Y |-> (C1 && (A1 | A2) && (B1 | B2))
    );

// Output must match the OR of all four inputs.
    check_output_matches_or: assert property (
        @(posedge clk) output1 == (input1 | input2 | input3 | input4)
    );

// If any input is high, the output must be high.
    check_any_input_high_sets_output: assert property (
        @(posedge clk) (input1 | input2 | input3 | input4) |-> output1
    );

// If all inputs are low, the output must be low.
    check_all_inputs_low_clears_output: assert property (
        @(posedge clk) !(input1 | input2 | input3 | input4) |-> !output1
    );

// A high output must come from at least one high input.
    check_output_high_has_active_input: assert property (
        @(posedge clk) output1 |-> (input1 | input2 | input3 | input4)
    );

// A low output means all inputs are low.
    check_output_low_means_all_inputs_low: assert property (
        @(posedge clk) !output1 |-> !(input1 | input2 | input3 | input4)
    );

// Reset clears both count and out on the next clock.
    check_reset_clears_outputs: assert property (
        @(posedge clk) reset |=> (count == 4'b0000 && out == 1'b0)
    );

// When not in reset, count increments by one on the next clock.
    check_count_increments: assert property (
        @(posedge clk) disable iff (reset) 1'b1 |=> (count == ($past(count) + 4'd1))
    );

// When not in reset, out toggles on the next clock.
    check_out_toggles: assert property (
        @(posedge clk) disable iff (reset) 1'b1 |=> (out == ~$past(out))
    );

// parallel_out reflects the previous cycle's load or shift result.
    check_parallel_out_update: assert property (
        @(posedge clk)
        1'b1 |=> (parallel_out == ($past(parallel_load) ? $past(data_in) :
                   ($past(shift_dir) ? { $past(parallel_out[6:0]), 1'b0 } :
                                        { 1'b0, $past(parallel_out[7:1]) })))
    );

// parallel_load causes parallel_out to capture data_in on the next cycle.
    check_parallel_load_captures_data: assert property (
        @(posedge clk)
        parallel_load |=> (parallel_out == $past(data_in))
    );

// parallel_load causes serial_out to reflect the loaded data LSB on the next cycle.
    check_serial_load_captures_data: assert property (
        @(posedge clk)
        parallel_load |=> (serial_out == $past(data_in[0]))
    );

// shift_dir=1 causes parallel_out to shift left and insert 0 on the next cycle.
    check_shift_left_updates_parallel: assert property (
        @(posedge clk)
        (!parallel_load && shift_dir) |=> (parallel_out == { $past(parallel_out[6:0]), 1'b0 })
    );

// shift_dir=0 causes parallel_out to shift right and insert 0 on the next cycle.
    check_shift_right_updates_parallel: assert property (
        @(posedge clk)
        (!parallel_load && !shift_dir) |=> (parallel_out == { 1'b0, $past(parallel_out[7:1]) })
    );

// serial_out is always the LSB of parallel_out.
    check_serial_out_matches_parallel_lsb: assert property (
        @(posedge clk)
        (serial_out == parallel_out[0])
    );

// Clock: w_clock (posedge). Reset: w_reset (synchronous, active-high). Sequential register: r_bus_addr_out <= (w_reset ? 8'h00 : w_bus_addr_in).

    // On reset, next cycle r_bus_addr_out must be 0.
    reset_clears_next: assert property (
        @(posedge w_clock) w_reset |=> (r_bus_addr_out == 8'h00)
    );

// When not in reset, next cycle r_bus_addr_out equals current w_bus_addr_in.
    capture_when_not_reset: assert property (
        @(posedge w_clock) disable iff (w_reset) 1'b1 |=> (r_bus_addr_out == $past(w_bus_addr_in))
    );

// If not in reset and w_bus_addr_in changes, r_bus_addr_out equals the prior w_bus_addr_in value.
    change_matches_prior_input: assert property (
        @(posedge w_clock) disable iff (w_reset) $changed(w_bus_addr_in) |=> (r_bus_addr_out == $past(w_bus_addr_in))
    );

// If not in reset and w_bus_addr_in is stable, r_bus_addr_out equals the prior w_bus_addr_in value.
    stable_output_matches_prior_input: assert property (
        @(posedge w_clock) disable iff (w_reset) $stable(w_bus_addr_in) |=> (r_bus_addr_out == $past(w_bus_addr_in))
    );

// If not in reset and w_bus_addr_in changes, r_bus_addr_out equals the prior w_bus_addr_in value on the next cycle.
    change_updates_next_cycle: assert property (
        @(posedge w_clock) disable iff (w_reset) $changed(w_bus_addr_in) |=> (r_bus_addr_out == $past(w_bus_addr_in))
    );

// X matches the implemented OR-then-AND function.
    check_functional_equivalence: assert property (
        @(posedge clk) X == ((A1 | A2) & B1 & C1)
    );

// B1 low forces the AND stage low and X low.
    check_b1_low_forces_x_low: assert property (
        @(posedge clk) !B1 |-> !X
    );

// C1 low forces the AND stage low and X low.
    check_c1_low_forces_x_low: assert property (
        @(posedge clk) !C1 |-> !X
    );

// Both A inputs low force the OR stage low and X low.
    check_a_inputs_low_force_x_low: assert property (
        @(posedge clk) (!A1 && !A2) |-> !X
    );

// With B1 and C1 high, X reduces to the OR of A1 and A2.
    check_b1_c1_high_reduces_to_or: assert property (
        @(posedge clk) (B1 && C1) |-> (X == (A1 | A2))
    );

// With B1 and C1 high, X high requires at least one A input high.
    check_b1_c1_high_requires_a_high: assert property (
        @(posedge clk) (B1 && C1 && X) |-> (A1 || A2)
    );

// With B1 and C1 high, X low requires both A inputs low.
    check_b1_c1_high_requires_a_low: assert property (
        @(posedge clk) (B1 && C1 && !X) |-> (!A1 && !A2)
    );

// A high X requires B1 and C1 high and at least one A input high.
    check_x_high_requires_enables_and_a: assert property (
        @(posedge clk) X |-> (B1 && C1 && (A1 || A2))
    );

// Y matches the implemented NAND-AND-NOT function.
    check_y_function: assert property (
        @(posedge clk) Y == ~((~(A2 & A1)) & (~(B2 & B1)))
    );

// A high Y means at least one input pair is high.
    check_y_high_implies_some_pair_high: assert property (
        @(posedge clk) Y |-> ((A1 & A2) || (B1 & B2))
    );

// A low Y means both input pairs are not high.
    check_y_low_implies_no_pair_high: assert property (
        @(posedge clk) !Y |-> (!(A1 & A2) && !(B1 & B2))
    );

// Load clears the counter on the next cycle.
    check_load_clears_counter: assert property (
        @(posedge clk) load |=> (out == 3'b000)
    );

// Load has priority over up_down when both are asserted.
    check_load_priority_over_up_down: assert property (
        @(posedge clk) (load && up_down) |=> (out == 3'b000)
    );

// When not loading and up_down is high, the counter increments.
    check_increment_when_up_down: assert property (
        @(posedge clk) (!load && up_down) |=> (out == ($past(out) + 3'b001))
    );

// When not loading and up_down is low, the counter decrements.
    check_decrement_when_not_up_down: assert property (
        @(posedge clk) (!load && !up_down) |=> (out == ($past(out) - 3'b001))
    );

// Incrementing from 7 wraps back to 0.
    check_increment_wrap_from_max: assert property (
        @(posedge clk) (!load && up_down && (out == 3'b111)) |=> (out == 3'b000)
    );

// Decrementing from 0 wraps back to 7.
    check_decrement_wrap_from_min: assert property (
        @(posedge clk) (!load && !up_down && (out == 3'b000)) |=> (out == 3'b111)
    );

// Reset forces the counter output to zero.
    check_reset_clears_output: assert property (
        @(posedge clk) !reset |-> (out == '0)
    );

// When enabled, the counter updates with the registered next state.
    check_enabled_state_update: assert property (
        @(posedge clk) disable iff (!reset)
        ena |=> (out == $past({out[SIZE-2:0], out[SIZE-1] ^ out[SIZE-2]}))
    );

// When disabled, the counter holds its previous value.
    check_disabled_state_hold: assert property (
        @(posedge clk) disable iff (!reset)
        !ena |=> (out == $past(out))
    );

// The upper bits shift from the lower bits when enabled.
    check_shifted_upper_bits: assert property (
        @(posedge clk) disable iff (!reset)
        ena |=> (out[SIZE-1:1] == $past(out[SIZE-2:0]))
    );

// The LSB is the XOR of the previous upper bit and the previous second bit.
    check_lsb_xor_update: assert property (
        @(posedge clk) disable iff (!reset)
        ena |=> (out[0] == $past(out[SIZE-2] ^ out[SIZE-3]))
    );

// A zero state remains zero on the next cycle when enabled.
    check_zero_state_stays_zero: assert property (
        @(posedge clk) disable iff (!reset)
        (ena && (out == '0)) |=> (out == '0)
    );

// A zero state remains zero on the next cycle when disabled.
    check_zero_state_holds_when_disabled: assert property (
        @(posedge clk) disable iff (!reset)
        (!ena && (out == '0)) |=> (out == '0)
    );

// sel 0000 decodes to bit 0.
    check_sel_0000_decode: assert property (
        @(posedge clk) (sel == 4'b0000) |-> (out == 16'h0001)
    );

// sel 0001 decodes to bit 1.
    check_sel_0001_decode: assert property (
        @(posedge clk) (sel == 4'b0001) |-> (out == 16'h0002)
    );

// sel 0010 decodes to bit 2.
    check_sel_0010_decode: assert property (
        @(posedge clk) (sel == 4'b0010) |-> (out == 16'h0004)
    );

// sel 0011 decodes to bit 3.
    check_sel_0011_decode: assert property (
        @(posedge clk) (sel == 4'b0011) |-> (out == 16'h0008)
    );

// sel 0100 decodes to bit 4.
    check_sel_0100_decode: assert property (
        @(posedge clk) (sel == 4'b0100) |-> (out == 16'h0010)
    );

// sel 0101 decodes to bit 5.
    check_sel_0101_decode: assert property (
        @(posedge clk) (sel == 4'b0101) |-> (out == 16'h0020)
    );

// sel 0110 decodes to bit 6.
    check_sel_0110_decode: assert property (
        @(posedge clk) (sel == 4'b0110) |-> (out == 16'h0040)
    );

// sel 0111 decodes to bit 7.
    check_sel_0111_decode: assert property (
        @(posedge clk) (sel == 4'b0111) |-> (out == 16'h0080)
    );

// sel 1000 decodes to bit 8.
    check_sel_1000_decode: assert property (
        @(posedge clk) (sel == 4'b1000) |-> (out == 16'h0100)
    );

// sel 1001 decodes to bit 9.
    check_sel_1001_decode: assert property (
        @(posedge clk) (sel == 4'b1001) |-> (out == 16'h0200)
    );

// sel 1010 decodes to bit 10.
    check_sel_1010_decode: assert property (
        @(posedge clk) (sel == 4'b1010) |-> (out == 16'h0400)
    );

// sel 1011 decodes to bit 11.
    check_sel_1011_decode: assert property (
        @(posedge clk) (sel == 4'b1011) |-> (out == 16'h0800)
    );

// sel 1100 decodes to bit 12.
    check_sel_1100_decode: assert property (
        @(posedge clk) (sel == 4'b1100) |-> (out == 16'h1000)
    );

// sel 1101 decodes to bit 13.
    check_sel_1101_decode: assert property (
        @(posedge clk) (sel == 4'b1101) |-> (out == 16'h2000)
    );

// sel 1110 decodes to bit 14.
    check_sel_1110_decode: assert property (
        @(posedge clk) (sel == 4'b1110) |-> (out == 16'h4000)
    );

// sel 1111 decodes to bit 15.
    check_sel_1111_decode: assert property (
        @(posedge clk) (sel == 4'b1111) |-> (out == 16'h8000)
    );

// Any non-matching select value drives zero.
    check_default_decode_zero: assert property (
        @(posedge clk) (sel != 4'b0000 && sel != 4'b0001 && sel != 4'b0010 && sel != 4'b0011 &&
                        sel != 4'b0100 && sel != 4'b0101 && sel != 4'b0110 && sel != 4'b0111 &&
                        sel != 4'b1000 && sel != 4'b1001 && sel != 4'b1010 && sel != 4'b1011 &&
                        sel != 4'b1100 && sel != 4'b1101 && sel != 4'b1110 && sel != 4'b1111)
        |-> (out == 16'h0000)
    );

// Two consecutive high d values produce two consecutive high q values.
    check_q_two_highs: assert property (
        @(posedge clk) (d ##1 d) |-> (q ##1 q)
    );

// Two consecutive low d values produce two consecutive low q values.
    check_q_two_lows: assert property (
        @(posedge clk) (!d ##1 !d) |-> (!q ##1 !q)
    );

// A high d followed by a low d produces a high q followed by a low q.
    check_q_high_then_low: assert property (
        @(posedge clk) (d ##1 !d) |-> (q ##1 !q)
    );

// A low d followed by a high d produces a low q followed by a high q.
    check_q_low_then_high: assert property (
        @(posedge clk) (!d ##1 d) |-> (!q ##1 q)
    );

// X must match the implemented OR-then-AND function.
    check_functional_equivalence: assert property (
        @(posedge clk) X == ((A1 | A2) & B1)
    );

// B1 low forces X low.
    check_b1_low_forces_x_low: assert property (
        @(posedge clk) !B1 |-> !X
    );

// Both A inputs low force X low.
    check_a_inputs_low_force_x_low: assert property (
        @(posedge clk) (!A1 && !A2) |-> !X
    );

// With B1 high, either A input high drives X high.
    check_b1_high_and_any_a_high_drives_x_high: assert property (
        @(posedge clk) (B1 && (A1 || A2)) |-> X
    );

// X high requires B1 high and at least one A input high.
    check_x_high_requires_b1_and_any_a: assert property (
        @(posedge clk) X |-> (B1 && (A1 || A2))
    );

// X high implies B1 is high.
    check_x_high_implies_b1_high: assert property (
        @(posedge clk) X |-> B1
    );

// X high implies at least one A input is high.
    check_x_high_implies_any_a_high: assert property (
        @(posedge clk) X |-> (A1 || A2)
    );

// sel=00 routes in0 to out.
    check_sel_00_routes_in0: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == in0)
    );

// sel=01 routes in1 to out.
    check_sel_01_routes_in1: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out == in1)
    );

// sel=10 routes in2 to out.
    check_sel_10_routes_in2: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out == in2)
    );

// sel=11 routes in3 to out.
    check_sel_11_routes_in3: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == in3)
    );

// With sel[0] low, the upper mux selects the low-input path.
    check_sel0_low_selects_low_path: assert property (
        @(posedge clk) (sel[0] == 1'b0) |-> (out == (sel[1] ? in2 : in0))
    );

// With sel[0] high, the upper mux selects the high-input path.
    check_sel0_high_selects_high_path: assert property (
        @(posedge clk) (sel[0] == 1'b1) |-> (out == (sel[1] ? in3 : in1))
    );

// With sel[1] low, the final mux selects the low-input path.
    check_sel1_low_selects_low_path: assert property (
        @(posedge clk) (sel[1] == 1'b0) |-> (out == (sel[0] ? in1 : in0))
    );

// With sel[1] high, the final mux selects the high-input path.
    check_sel1_high_selects_high_path: assert property (
        @(posedge clk) (sel[1] == 1'b1) |-> (out == (sel[0] ? in3 : in2))
    );

// Reset forces the counter to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |-> (count == 2'b00)
    );

// When enabled, data_out captures data_in on the next clock.
    check_capture_when_enabled: assert property (
        @(posedge clk) en |=> (data_out == $past(data_in))
    );

// When disabled, data_out clears on the next clock.
    check_clear_when_disabled: assert property (
        @(posedge clk) !en |=> (data_out == 1'b0)
    );

// data_out always matches the previous cycle's enable and data_in value.
    check_registered_function: assert property (
        @(posedge clk) 1'b1 |=> (data_out == ($past(en) ? $past(data_in) : 1'b0))
    );

// COUT is the AND of A and B.
    check_cout_is_and: assert property (
        @(posedge clk) COUT == (A & B)
    );

// SUM is the XOR of A and B.
    check_sum_is_xor: assert property (
        @(posedge clk) SUM == (A ^ B)
    );

// The two outputs are never high together.
    check_outputs_mutually_exclusive: assert property (
        @(posedge clk) !(COUT & SUM)
    );

// When both inputs are low, both outputs are low.
    check_zero_inputs_zero_outputs: assert property (
        @(posedge clk) (!A && !B) |-> (!COUT && !SUM)
    );

// When the inputs differ, SUM is high and COUT is low.
    check_different_inputs_xor: assert property (
        @(posedge clk) (A ^ B) |-> (SUM && !COUT)
    );

// adc_cdcs_o is tied high.
    check_cdcs_tied_high: assert property (
        @(posedge clk) disable iff (rst_i) adc_cdcs_o == 1'b1
    );

// adc_clk_source is tied to 2'b10.
    check_clk_source_tied_value: assert property (
        @(posedge clk) disable iff (rst_i) adc_clk_source == 2'b10
    );

// Reset clears the register on the next cycle.
    check_reset_clears_register: assert property (
        @(posedge clk) reset |=> (q == 4'b0000)
    );

// Parallel load captures parallel_input when not in reset.
    check_parallel_load_captures_input: assert property (
        @(posedge clk) disable iff (reset)
        parallel_load |=> (q == $past(parallel_input))
    );

// With no active control, the register holds its value.
    check_hold_when_idle: assert property (
        @(posedge clk) disable iff (reset)
        !parallel_load && !shift_left && !shift_right |=> (q == $past(q))
    );

// Load has priority over shift_left when both are asserted.
    check_load_priority_over_shift_left: assert property (
        @(posedge clk) disable iff (reset)
        parallel_load && shift_left |=> (q == $past(parallel_input))
    );

// Load has priority over shift_right when both are asserted.
    check_load_priority_over_shift_right: assert property (
        @(posedge clk) disable iff (reset)
        parallel_load && shift_right |=> (q == $past(parallel_input))
    );

// During reset, pwm_out must be 0.
    reset_forces_low: assert property (
        @(posedge clk) !rst_n |-> (pwm_out == 1'b0)
    );

// If pwm_out is 0 at a clock edge, it must be 1 on the next clock.
    zero_implies_next_one: assert property (
        @(posedge clk) disable iff (!rst_n) (pwm_out == 1'b0) |=> (pwm_out == 1'b1)
    );

// If pwm_out is 1 at a clock edge, it must be 0 on the next clock.
    one_implies_next_zero: assert property (
        @(posedge clk) disable iff (!rst_n) (pwm_out == 1'b1) |=> (pwm_out == 1'b0)
    );

// On reset deassertion, pwm_out is 0 at that clock edge.
    deassert_reset_low: assert property (
        @(posedge clk) $rose(rst_n) |-> (pwm_out == 1'b0)
    );

// On reset deassertion, pwm_out is 1 on the next clock edge.
    deassert_reset_next_high: assert property (
        @(posedge clk) $rose(rst_n) |=> (pwm_out == 1'b1)
    );

// A=000 selects m3.
    check_case_000: assert property (
        @(posedge clk)
        ({A, B, C} == 3'b000) |-> (F == (A & ~B & ~C))
    );

// A=001 selects m2.
    check_case_001: assert property (
        @(posedge clk)
        ({A, B, C} == 3'b001) |-> (F == (A & ~B & ~C))
    );

// A=010 selects m1.
    check_case_010: assert property (
        @(posedge clk)
        ({A, B, C} == 3'b010) |-> (F == (A & ~B & ~C))
    );

// A=011 selects m0.
    check_case_011: assert property (
        @(posedge clk)
        ({A, B, C} == 3'b011) |-> (F == (A & ~B & ~C))
    );

// A=100 selects m3.
    check_case_100: assert property (
        @(posedge clk)
        ({A, B, C} == 3'b100) |-> (F == (A & ~B & ~C))
    );

// eq must reflect whether a equals b.
    check_eq_definition: assert property (
        @(posedge clk) eq == (a == b)
    );

// When a is greater than b, both gt and eq must be low.
    check_gt_excludes_eq: assert property (
        @(posedge clk) (a > b) |-> (gt && !eq)
    );

// When a is less than b, both lt and eq must be low.
    check_lt_excludes_eq: assert property (
        @(posedge clk) (a < b) |-> (lt && !eq)
    );

// Y must match the implemented OAI21 equation.
    check_oai21_equation: assert property (
        @(posedge clk) Y == ~((A | B) & C)
    );

// When C is low, Y must be high.
    check_c_low_forces_y_high: assert property (
        @(posedge clk) !C |-> Y
    );

// When both OR inputs are low, Y must be high.
    check_or_inputs_low_force_y_high: assert property (
        @(posedge clk) (!A && !B) |-> Y
    );

// When C is high and either OR input is high, Y must be low.
    check_active_c_and_active_or_input_forces_y_low: assert property (
        @(posedge clk) (C && (A || B)) |-> !Y
    );

// A low Y requires C to be high and at least one OR input to be high.
    check_y_low_requires_active_c_and_active_or_input: assert property (
        @(posedge clk) !Y |-> (C && (A || B))
    );

// A high Y requires C to be low or both OR inputs to be low.
    check_y_high_requires_inactive_c_or_inactive_or_inputs: assert property (
        @(posedge clk) Y |-> (!C || (!A && !B))
    );

// Clock: clk_IBUF_BUFG (posedge). Reset: none. Logic: sequential (registered add with clear).

    // On clear, next cycle state must be 00.
    check_clear_sets_zero: assert property (
        @(posedge clk_IBUF_BUFG) FSM_selector_C |=> (FSM_sequential_state_reg_reg == 2'b00)
    );

// On no clear, next cycle state equals prev state + prev AR (mod 4).
    check_add_when_no_clear: assert property (
        @(posedge clk_IBUF_BUFG) !FSM_selector_C |=> (FSM_sequential_state_reg_reg == $past(FSM_sequential_state_reg_reg) + $past(AR))
    );

// If no clear and AR==0, state holds its value.
    check_hold_when_ar_zero: assert property (
        @(posedge clk_IBUF_BUFG) (!FSM_selector_C && (AR == 1'b0)) |=> (FSM_sequential_state_reg_reg == $past(FSM_sequential_state_reg_reg))
    );

// If no clear and AR==1, state increments by 1 (mod 4).
    check_increment_by_one: assert property (
        @(posedge clk_IBUF_BUFG) (!FSM_selector_C && (AR == 1'b1)) |=> (FSM_sequential_state_reg_reg == $past(FSM_sequential_state_reg_reg) + 2'd1)
    );

// If no clear and AR==3, state increments by 3 (mod 4).
    check_increment_by_three: assert property (
        @(posedge clk_IBUF_BUFG) (!FSM_selector_C && (AR == 3'b11)) |=> (FSM_sequential_state_reg_reg == $past(FSM_sequential_state_reg_reg) + 2'd3)
    );

// If no clear and AR==2, state increments by 2 (mod 4).
    check_increment_by_two: assert property (
        @(posedge clk_IBUF_BUFG) (!FSM_selector_C && (AR == 2'b10)) |=> (FSM_sequential_state_reg_reg == $past(FSM_sequential_state_reg_reg) + 2'd2)
    );

// If no clear and AR==3, next state is not 00 (since prev state != 00).
    check_no_zero_after_inc_three: assert property (
        @(posedge clk_IBUF_BUFG) (!FSM_selector_C && (AR == 3'b11)) |=> (FSM_sequential_state_reg_reg != 2'b00)
    );

// If no clear and AR==2, next state is not 00 (since prev state != 00).
    check_no_zero_after_inc_two: assert property (
        @(posedge clk_IBUF_BUFG) (!FSM_selector_C && (AR == 2'b10)) |=> (FSM_sequential_state_reg_reg != 2'b00)
    );

// Y must equal the NOR of A, B, C, and D_N.
    check_nor_function: assert property (
        @(posedge clk) Y == ~(A | B | C | D_N)
    );

// All low inputs must drive Y high.
    check_all_inputs_low_drives_y_high: assert property (
        @(posedge clk) (!A && !B && !C && !D_N) |-> Y
    );

// A high must force Y low.
    check_a_high_drives_y_low: assert property (
        @(posedge clk) A |-> !Y
    );

// B high must force Y low.
    check_b_high_drives_y_low: assert property (
        @(posedge clk) B |-> !Y
    );

// C high must force Y low.
    check_c_high_drives_y_low: assert property (
        @(posedge clk) C |-> !Y
    );

// D_N high must force Y low.
    check_d_n_high_drives_y_low: assert property (
        @(posedge clk) D_N |-> !Y
    );

// Y low means at least one input is high.
    check_y_low_implies_some_input_high: assert property (
        @(posedge clk) !Y |-> (A || B || C || D_N)
    );

// Y high means all inputs are low.
    check_y_high_implies_all_inputs_low: assert property (
        @(posedge clk) Y |-> (!A && !B && !C && !D_N)
    );

// Reset clears all registered state.
    check_reset_clears_state: assert property (
        @(posedge clk) !reset_n |-> (pwm_timer == 12'd0) &&
                                 (fifo_rdreq == 1'b0) &&
                                 (audiodata_32 == 32'd0) &&
                                 (audiodata_32_p == 32'd0) &&
                                 (data_rdy == 1'b0)
    );

// fifo_rdreq is deasserted on the 0x801 sample and only when the prior request was high.
    check_fifo_rdreq_clears_on_sample: assert property (
        @(posedge clk) disable iff (!reset_n)
        (pwm_timer == 12'h801 && $past(fifo_rdreq) == 1'b1) |=> (fifo_rdreq == 1'b0)
    );

// op is forced low whenever clr is asserted.
    check_clear_forces_low: assert property (
        @(posedge clk) clr |-> (op == 1'b0)
    );

// With ce high, op captures the inverted input on the next cycle.
    check_capture_inverts_input: assert property (
        @(posedge clk) disable iff (clr) ce |=> (op == ~$past(ip))
    );

// With ce low, op holds its previous value.
    check_hold_when_ce_low: assert property (
        @(posedge clk) disable iff (clr) !ce |=> (op == $past(op))
    );

// When reset is asserted, io_out loads io_init on the next cycle.
    check_reset_loads_init: assert property (
        @(posedge clock) reset |=> (io_out == $past(io_init))
    );

// When reset is asserted, io_out is io_init on the same cycle.
    check_reset_sets_out_now: assert property (
        @(posedge clock) reset |-> (io_out == io_init)
    );

// With enable and no reset, io_out loads io_in on the next cycle.
    check_enable_loads_in: assert property (
        @(posedge clock) disable iff (reset) io_enable |=> (io_out == $past(io_in))
    );

// With enable low and no reset, io_out holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clock) disable iff (reset) !io_enable |=> (io_out == $past(io_out))
    );

// If reset and enable are both asserted, reset has priority and io_out loads io_init.
    check_reset_priority_over_enable: assert property (
        @(posedge clock) (reset && io_enable) |=> (io_out == $past(io_init))
    );

// If reset and enable are both asserted, io_out is io_init on the same cycle.
    check_reset_priority_sets_out_now: assert property (
        @(posedge clock) (reset && io_enable) |-> (io_out == io_init)
    );

// If reset is held high across cycles, io_out equals the value loaded in the previous cycle.
    check_reset_hold_stability: assert property (
        @(posedge clock) (reset && $past(reset)) |-> (io_out == $past(io_out))
    );

// If reset is held high and enable is low, io_out loads io_init on the next cycle.
    check_reset_hold_loads_init: assert property (
        @(posedge clock) (reset && !io_enable && $past(reset && !io_enable)) |=> (io_out == $past(io_init))
    );

// g_out must equal the AND of a and b.
    check_g_out_matches_and: assert property (
        @(posedge clk) g_out == (a & b)
    );

// p_out must equal the OR of a and b.
    check_p_out_matches_or: assert property (
        @(posedge clk) p_out == (a | b)
    );

// Both inputs low must drive both outputs low.
    check_both_inputs_low_drive_outputs_low: assert property (
        @(posedge clk) (!a && !b) |-> (!g_out && !p_out)
    );

// Both inputs high must drive both outputs high.
    check_both_inputs_high_drive_outputs_high: assert property (
        @(posedge clk) (a && b) |-> (g_out && p_out)
    );

// A high g_out requires both inputs high.
    check_g_out_high_requires_both_inputs_high: assert property (
        @(posedge clk) g_out |-> (a && b)
    );

// A high p_out requires at least one input high.
    check_p_out_high_requires_any_input_high: assert property (
        @(posedge clk) p_out |-> (a || b)
    );

// 0000000001 maps to 00001.
    check_map_0000000001: assert property (
        @(posedge clk) (key_input == 9'b0000000001) |-> (led_output == 5'b00001)
    );

// 0000000010 maps to 00010.
    check_map_0000000010: assert property (
        @(posedge clk) (key_input == 9'b0000000010) |-> (led_output == 5'b00010)
    );

// 0000000100 maps to 00100.
    check_map_0000000100: assert property (
        @(posedge clk) (key_input == 9'b0000000100) |-> (led_output == 5'b00100)
    );

// 0000001000 maps to 01000.
    check_map_0000001000: assert property (
        @(posedge clk) (key_input == 9'b0000001000) |-> (led_output == 5'b01000)
    );

// 0000010000 maps to 10000.
    check_map_0000010000: assert property (
        @(posedge clk) (key_input == 9'b0000010000) |-> (led_output == 5'b10000)
    );

// 0000100000 maps to 00000.
    check_map_0000100000: assert property (
        @(posedge clk) (key_input == 9'b0000100000) |-> (led_output == 5'b00000)
    );

// 0001000000 maps to 11111.
    check_map_0001000000: assert property (
        @(posedge clk) (key_input == 9'b0001000000) |-> (led_output == 5'b11111)
    );

// X must equal the AND of all four inputs.
    check_x_matches_and4: assert property (
        @(posedge clk) X == (A & B & C & D)
    );

// All inputs high must drive X high.
    check_all_inputs_high_drive_x_high: assert property (
        @(posedge clk) (A & B & C & D) |-> X
    );

// X high requires all inputs high.
    check_x_high_requires_all_inputs_high: assert property (
        @(posedge clk) X |-> (A & B & C & D)
    );

// A low forces X low.
    check_a_low_forces_x_low: assert property (
        @(posedge clk) !A |-> !X
    );

// B low forces X low.
    check_b_low_forces_x_low: assert property (
        @(posedge clk) !B |-> !X
    );

// C low forces X low.
    check_c_low_forces_x_low: assert property (
        @(posedge clk) !C |-> !X
    );

// D low forces X low.
    check_d_low_forces_x_low: assert property (
        @(posedge clk) !D |-> !X
    );

// X must equal the OR of A, B, and C.
    check_or_function: assert property (
        @(posedge clk) X == (A | B | C)
    );

// If all inputs are low, X must be low.
    check_all_inputs_low: assert property (
        @(posedge clk) (!A && !B && !C) |-> !X
    );

// If any input is high, X must be high.
    check_any_input_high: assert property (
        @(posedge clk) (A || B || C) |-> X
    );

// A high must force X high.
    check_a_high_sets_x: assert property (
        @(posedge clk) A |-> X
    );

// B high must force X high.
    check_b_high_sets_x: assert property (
        @(posedge clk) B |-> X
    );

// C high must force X high.
    check_c_high_sets_x: assert property (
        @(posedge clk) C |-> X
    );

// X low means all inputs are low.
    check_x_low_means_all_inputs_low: assert property (
        @(posedge clk) !X |-> (!A && !B && !C)
    );

// X high means at least one input is high.
    check_x_high_means_any_input_high: assert property (
        @(posedge clk) X |-> (A || B || C)
    );

// Output must match the implemented XOR function.
    check_out_matches_xor_function: assert property (
        @(posedge clk) out_comb == ((a & ~b) | (~a & b))
    );

// When both inputs are low, the output must be low.
    check_both_low_drive_low: assert property (
        @(posedge clk) (!a && !b) |-> (out_comb == 1'b0)
    );

// When only a is high, the output must be high.
    check_only_a_high_drive_high: assert property (
        @(posedge clk) (a && !b) |-> (out_comb == 1'b1)
    );

// When only b is high, the output must be high.
    check_only_b_high_drive_high: assert property (
        @(posedge clk) (!a && b) |-> (out_comb == 1'b1)
    );

// When both inputs are high, the output must be low.
    check_both_high_drive_low: assert property (
        @(posedge clk) (a && b) |-> (out_comb == 1'b0)
    );

// A high output must come from exactly one asserted input.
    check_high_output_requires_one_hot: assert property (
        @(posedge clk) out_comb |-> ((a && !b) || (!a && b))
    );

// A low output must come from both inputs being equal.
    check_low_output_requires_equal_inputs: assert property (
        @(posedge clk) !out_comb |-> ((a && b) || (!a && !b))
    );

// Y must match the implemented sum-of-products equation.
    check_output_equation: assert property (
        @(posedge clk)
        Y == ((~A1_N & ~A2_N & B2) |
              (~A1_N &  A2_N & B1) |
              ( A1_N & ~A2_N & B2) |
              ( A1_N &  A2_N & B1))
    );

// op 0000 selects addition.
    check_add_result: assert property (
        @(posedge clk) (op == 4'b0000) |-> (Y == (A + B))
    );

// op 0001 selects subtraction.
    check_sub_result: assert property (
        @(posedge clk) (op == 4'b0001) |-> (Y == (A - B))
    );

// op 0010 selects bitwise AND.
    check_and_result: assert property (
        @(posedge clk) (op == 4'b0010) |-> (Y == (A & B))
    );

// op 0011 selects bitwise OR.
    check_or_result: assert property (
        @(posedge clk) (op == 4'b0011) |-> (Y == (A | B))
    );

// op 0100 selects bitwise XOR.
    check_xor_result: assert property (
        @(posedge clk) (op == 4'b0100) |-> (Y == (A ^ B))
    );

// op 0101 selects bitwise NOT of A.
    check_not_a_result: assert property (
        @(posedge clk) (op == 4'b0101) |-> (Y == (~A))
    );

// op 0110 selects left shift by 1.
    check_shift_left_result: assert property (
        @(posedge clk) (op == 4'b0110) |-> (Y == ({A[14:0], 1'b0}))
    );

// op 0111 selects right shift by 1.
    check_shift_right_result: assert property (
        @(posedge clk) (op == 4'b0111) |-> (Y == ({1'b0, A[15:1]}))
    );

// op 1000 selects left rotate by 1.
    check_rotate_left_result: assert property (
        @(posedge clk) (op == 4'b1000) |-> (Y == ({A[14:0], A[15]}))
    );

// op 1001 selects right rotate by 1.
    check_rotate_right_result: assert property (
        @(posedge clk) (op == 4'b1001) |-> (Y == ({A[0], A[15:1]}))
    );

// Any unsupported op code drives zero.
    check_default_zero_result: assert property (
        @(posedge clk) (op inside {4'b1010, 4'b1011, 4'b1100, 4'b1101, 4'b1110, 4'b1111}) |-> (Y == 16'h0000)
    );

// out_xor is the XOR of the selected input with a.
    check_out_xor_function: assert property (
        @(posedge clk)
        out_xor == ((sel_b2 ? b : (sel_b1 ? b : a)) ^ a)
    );

// out_xor_inv is the bitwise inversion of out_xor.
    check_out_xor_inv_function: assert property (
        @(posedge clk)
        out_xor_inv == ~out_xor
    );

// out_logical_inv is the logical inversion of out_xor.
    check_out_logical_inv_function: assert property (
        @(posedge clk)
        out_logical_inv == !out_xor
    );

// When sel_out is high, out_always reflects the previous-cycle logical inverse.
    check_out_always_selects_logical_inv: assert property (
        @(posedge clk)
        sel_out |=> out_always == $past(!out_xor)
    );

// Equal XOR and logical inverse outputs imply the selected input equals a.
    check_equal_outputs_imply_selected_equals_a: assert property (
        @(posedge clk)
        (out_xor == out_logical_inv) |-> ((sel_b2 ? b : (sel_b1 ? b : a)) == a)
    );

// Equal XOR and XOR inverse outputs imply the selected input differs from a.
    check_equal_xor_outputs_imply_selected_differs_a: assert property (
        @(posedge clk)
        (out_xor == out_xor_inv) |-> ((sel_b2 ? b : (sel_b1 ? b : a)) != a)
    );

// ctrl[7:5] 000 maps to td_mode 0000.
    check_ctrl_000_maps_td_0000: assert property (
        @(posedge clk) (ctrl[7:5] == 3'b000) |-> (td_mode == 4'b0000)
    );

// ctrl[7:5] 001 maps to td_mode 1000.
    check_ctrl_001_maps_td_1000: assert property (
        @(posedge clk) (ctrl[7:5] == 3'b001) |-> (td_mode == 4'b1000)
    );

// ctrl[7:5] 010 maps to td_mode 0100.
    check_ctrl_010_maps_td_0100: assert property (
        @(posedge clk) (ctrl[7:5] == 3'b010) |-> (td_mode == 4'b0100)
    );

// ctrl[7:5] 011 maps to td_mode 1100.
    check_ctrl_011_maps_td_1100: assert property (
        @(posedge clk) (ctrl[7:5] == 3'b011) |-> (td_mode == 4'b1100)
    );

// ctrl[7:5] 100 maps to td_mode 0010.
    check_ctrl_100_maps_td_0010: assert property (
        @(posedge clk) (ctrl[7:5] == 3'b100) |-> (td_mode == 4'b0010)
    );

// ctrl[7:5] 101 maps to td_mode 1010.
    check_ctrl_101_maps_td_1010: assert property (
        @(posedge clk) (ctrl[7:5] == 3'b101) |-> (td_mode == 4'b1010)
    );

// ctrl[7:5] 110 maps to td_mode 0101.
    check_ctrl_110_maps_td_0101: assert property (
        @(posedge clk) (ctrl[7:5] == 3'b110) |-> (td_mode == 4'b0101)
    );

// ctrl[7:5] 111 maps to td_mode 1111.
    check_ctrl_111_maps_td_1111: assert property (
        @(posedge clk) (ctrl[7:5] == 3'b111) |-> (td_mode == 4'b1111)
    );

// Input 0 maps to bit 0.
    check_decode_0000: assert property (
        @(posedge clk) (in == 4'b0000) |-> (out == 16'h0001)
    );

// Input 1 maps to bit 1.
    check_decode_0001: assert property (
        @(posedge clk) (in == 4'b0001) |-> (out == 16'h0002)
    );

// Input 2 maps to bit 2.
    check_decode_0010: assert property (
        @(posedge clk) (in == 4'b0010) |-> (out == 16'h0004)
    );

// Input 3 maps to bit 3.
    check_decode_0011: assert property (
        @(posedge clk) (in == 4'b0011) |-> (out == 16'h0008)
    );

// Input 4 maps to bit 4.
    check_decode_0100: assert property (
        @(posedge clk) (in == 4'b0100) |-> (out == 16'h0010)
    );

// Input 5 maps to bit 5.
    check_decode_0101: assert property (
        @(posedge clk) (in == 4'b0101) |-> (out == 16'h0020)
    );

// Input 6 maps to bit 6.
    check_decode_0110: assert property (
        @(posedge clk) (in == 4'b0110) |-> (out == 16'h0040)
    );

// Input 7 maps to bit 7.
    check_decode_0111: assert property (
        @(posedge clk) (in == 4'b0111) |-> (out == 16'h0080)
    );

// Input 8 maps to bit 8.
    check_decode_1000: assert property (
        @(posedge clk) (in == 4'b1000) |-> (out == 16'h0100)
    );

// Input 9 maps to bit 9.
    check_decode_1001: assert property (
        @(posedge clk) (in == 4'b1001) |-> (out == 16'h0200)
    );

// Input 10 maps to bit 10.
    check_decode_1010: assert property (
        @(posedge clk) (in == 4'b1010) |-> (out == 16'h0400)
    );

// Input 11 maps to bit 11.
    check_decode_1011: assert property (
        @(posedge clk) (in == 4'b1011) |-> (out == 16'h0800)
    );

// Input 12 maps to bit 12.
    check_decode_1100: assert property (
        @(posedge clk) (in == 4'b1100) |-> (out == 16'h1000)
    );

// Input 13 maps to bit 13.
    check_decode_1101: assert property (
        @(posedge clk) (in == 4'b1101) |-> (out == 16'h2000)
    );

// Input 14 maps to bit 14.
    check_decode_1110: assert property (
        @(posedge clk) (in == 4'b1110) |-> (out == 16'h4000)
    );

// Input 15 maps to bit 15.
    check_decode_1111: assert property (
        @(posedge clk) (in == 4'b1111) |-> (out == 16'h8000)
    );

// Output is always exactly one bit set.
    check_output_onehot: assert property (
        @(posedge clk) $onehot(out)
    );

// Output must always equal the XOR of the inputs.
    check_xor_function: assert property (
        @(posedge clk) out_comb_logic == (a ^ b)
    );

// When both inputs are low, the output must be low.
    check_both_low: assert property (
        @(posedge clk) (!a && !b) |-> !out_comb_logic
    );

// When both inputs are high, the output must be low.
    check_both_high: assert property (
        @(posedge clk) (a && b) |-> !out_comb_logic
    );

// When the inputs differ, the output must be high.
    check_inputs_differ: assert property (
        @(posedge clk) (a ^ b) |-> out_comb_logic
    );

// A high output requires the inputs to differ.
    check_output_high_requires_xor: assert property (
        @(posedge clk) out_comb_logic |-> (a ^ b)
    );

// X matches the implemented OR-of-terms function.
    check_x_matches_function: assert property (
        @(posedge clk) X == (A | B | C | ~D_N)
    );

// A high forces X high.
    check_a_high_forces_x_high: assert property (
        @(posedge clk) A |-> X
    );

// B high forces X high.
    check_b_high_forces_x_high: assert property (
        @(posedge clk) B |-> X
    );

// C high forces X high.
    check_c_high_forces_x_high: assert property (
        @(posedge clk) C |-> X
    );

// D_N low forces X high.
    check_d_n_low_forces_x_high: assert property (
        @(posedge clk) !D_N |-> X
    );

// With all OR terms low, X must be low.
    check_all_terms_low_forces_x_low: assert property (
        @(posedge clk) (!A && !B && !C && D_N) |-> !X
    );

// X low implies all OR terms are low.
    check_x_low_implies_all_terms_low: assert property (
        @(posedge clk) !X |-> (!A && !B && !C && D_N)
    );

// X matches the implemented OR-of-A/B/C and inverted D_N.
    check_functional_equivalence: assert property (
        @(posedge clk) X == (A | B | C | ~D_N)
    );

// A high forces X high.
    check_a_high_sets_x: assert property (
        @(posedge clk) A |-> X
    );

// B high forces X high.
    check_b_high_sets_x: assert property (
        @(posedge clk) B |-> X
    );

// C high forces X high.
    check_c_high_sets_x: assert property (
        @(posedge clk) C |-> X
    );

// D_N low forces X high.
    check_d_n_low_sets_x: assert property (
        @(posedge clk) !D_N |-> X
    );

// All OR inputs low force X low.
    check_all_inputs_low_clear_x: assert property (
        @(posedge clk) (!A && !B && !C && D_N) |-> !X
    );

// X low requires all OR inputs to be inactive.
    check_x_low_requires_all_inputs_inactive: assert property (
        @(posedge clk) !X |-> (!A && !B && !C && D_N)
    );

// X must equal the AND of all four inputs.
    check_x_matches_and4: assert property (
        @(posedge clk) X == (A & B & C & D)
    );

// All inputs high must drive X high.
    check_all_inputs_high_drive_x_high: assert property (
        @(posedge clk) (A & B & C & D) |-> X
    );

// X high requires all inputs high.
    check_x_high_requires_all_inputs_high: assert property (
        @(posedge clk) X |-> (A & B & C & D)
    );

// A low forces X low.
    check_a_low_forces_x_low: assert property (
        @(posedge clk) !A |-> !X
    );

// B low forces X low.
    check_b_low_forces_x_low: assert property (
        @(posedge clk) !B |-> !X
    );

// C low forces X low.
    check_c_low_forces_x_low: assert property (
        @(posedge clk) !C |-> !X
    );

// D low forces X low.
    check_d_low_forces_x_low: assert property (
        @(posedge clk) !D |-> !X
    );

// Reset clears the stored output value.
    check_reset_clears_out_port: assert property (
        @(posedge clk) !reset_n |-> (out_port == 6'h00)
    );

// Reset clears the readback value.
    check_reset_clears_readdata: assert property (
        @(posedge clk) !reset_n |-> (readdata == 32'h00000000)
    );

// Address 0 reads back the stored output value.
    check_read_address_zero_returns_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address == 2'b00) |-> (readdata == {26'b0, out_port})
    );

// Nonzero addresses read back zero.
    check_read_nonzero_address_returns_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address != 2'b00) |-> (readdata == 32'h00000000)
    );

// A selected write to address 0 updates the stored output value.
    check_write_address_zero_updates_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        (chipselect && !write_n && (address == 2'b00)) |=> (out_port == $past(writedata[5:0]))
    );

// Without a selected write to address 0, the stored output value holds.
    check_out_port_holds_without_selected_write: assert property (
        @(posedge clk) disable iff (!reset_n)
        !(chipselect && !write_n && (address == 2'b00)) |=> (out_port == $past(out_port))
    );

// o_dataout follows the mux select between i_register_settings and i_datain.
    check_output_mux: assert property (
        @(posedge clock) disable iff (!resetn)
        o_dataout == (i_settings ? i_register_settings : i_datain)
    );

// o_dataout_valid mirrors i_datain_valid.
    check_output_valid_passthrough: assert property (
        @(posedge clock) disable iff (!resetn)
        o_dataout_valid == i_datain_valid
    );

// o_datain_stall mirrors i_dataout_stall.
    check_input_stall_passthrough: assert property (
        @(posedge clock) disable iff (!resetn)
        o_datain_stall == i_dataout_stall
    );

// When i_settings is high, o_dataout selects i_register_settings.
    check_select_register_settings: assert property (
        @(posedge clock) disable iff (!resetn)
        i_settings |-> (o_dataout == i_register_settings)
    );

// When i_settings is low, o_dataout selects i_datain.
    check_select_datain: assert property (
        @(posedge clock) disable iff (!resetn)
        !i_settings |-> (o_dataout == i_datain)
    );

// A valid output requires a valid input.
    check_valid_output_requires_valid_input: assert property (
        @(posedge clock) disable iff (!resetn)
        o_dataout_valid |-> i_datain_valid
    );

// A valid input must drive a valid output.
    check_valid_input_requires_valid_output: assert property (
        @(posedge clock) disable iff (!resetn)
        i_datain_valid |-> o_dataout_valid
    );

// A stall on the output must come from the input stall.
    check_output_stall_matches_input_stall: assert property (
        @(posedge clock) disable iff (!resetn)
        o_datain_stall |-> i_dataout_stall
    );

// A stall on the input must appear on the output stall.
    check_input_stall_matches_output_stall: assert property (
        @(posedge clock) disable iff (!resetn)
        i_dataout_stall |-> o_datain_stall
    );

// X is cleared on the cycle after reset is asserted.
    check_reset_clears_x: assert property (
        @(posedge clk) reset |=> (X == 1'b0)
    );

// X reflects the AND of A and B from the previous cycle.
    check_and_update: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (X == ($past(A) & $past(B)))
    );

// Y matches the implemented NOR of the AND term and the two B/C inputs.
    check_functional_equivalence: assert property (
        @(posedge clk) Y == ~((A1 & A2) | B1 | C1)
    );

// B1 high forces the NOR output low.
    check_b1_forces_low: assert property (
        @(posedge clk) B1 |-> !Y
    );

// C1 high forces the NOR output low.
    check_c1_forces_low: assert property (
        @(posedge clk) C1 |-> !Y
    );

// Both A inputs high force the AND term high and drive Y low.
    check_and_term_forces_low: assert property (
        @(posedge clk) (A1 & A2) |-> !Y
    );

// With B1 and C1 low, Y reduces to the inverted AND of A1 and A2.
    check_bc_low_reduces_to_and: assert property (
        @(posedge clk) (!B1 && !C1) |-> (Y == ~(A1 & A2))
    );

// With the AND term low, Y reduces to the inverted OR of B1 and C1.
    check_and_low_reduces_to_or: assert property (
        @(posedge clk) !(A1 & A2) |-> (Y == ~(B1 | C1))
    );

// If B1 and C1 are low and the AND term is high, Y must be low.
    check_all_active_inputs_drive_low: assert property (
        @(posedge clk) (!B1 && !C1 && (A1 & A2)) |-> !Y
    );

// If B1 and C1 are low and the AND term is low, Y must be high.
    check_all_inactive_inputs_drive_high: assert property (
        @(posedge clk) (!B1 && !C1 && !(A1 & A2)) |-> Y
    );

// Y must match the implemented OR-of-products function.
    check_y_matches_function: assert property (
        @(posedge clk) Y == ((A1 & A2) | B1)
    );

// B1 high must force Y high.
    check_b1_forces_y_high: assert property (
        @(posedge clk) B1 |-> Y
    );

// A1 and A2 high together must force Y high.
    check_a1_a2_force_y_high: assert property (
        @(posedge clk) (A1 & A2) |-> Y
    );

// With B1 low, Y reduces to the A1&A2 term.
    check_b1_low_reduces_to_and_term: assert property (
        @(posedge clk) !B1 |-> (Y == (A1 & A2))
    );

// With A1&A2 low, Y reduces to B1.
    check_and_term_low_reduces_to_b1: assert property (
        @(posedge clk) !(A1 & A2) |-> (Y == B1)
    );

// If both OR inputs are low, Y must be low.
    check_both_inputs_low_force_y_low: assert property (
        @(posedge clk) (!B1 && !(A1 & A2)) |-> !Y
    );

// Y high must come from B1 or the A1&A2 term.
    check_y_high_has_valid_source: assert property (
        @(posedge clk) Y |-> (B1 || (A1 & A2))
    );

// Clock: clk (posedge). Reset: rst (active-low, asynchronous). Sequential 3-bit counter.

    // While reset is asserted low, count must be 0.
    check_reset_forces_zero: assert property (
        @(posedge clk) (rst == 1'b0) |-> (count == 3'b000)
    );

// On reset deassertion, count becomes 1 on the next clock.
    check_reset_release_sets_one: assert property (
        @(posedge clk) $rose(rst) |-> ##1 (count == 3'b001)
    );

// When not in reset, count increments by 1 each cycle (mod 8).
    check_count_increments: assert property (
        @(posedge clk) disable iff (!rst) 1'b1 |-> ##1 (count == $past(count) + 3'd1)
    );

// When not in reset, count wraps from 7 to 0.
    check_count_wraps_from_max: assert property (
        @(posedge clk) disable iff (!rst) (count == 3'b111) |-> ##1 (count == 3'b000)
    );

// When not in reset, count changes every cycle.
    check_count_changes_each_cycle: assert property (
        @(posedge clk) disable iff (!rst) 1'b1 |-> ##1 (count != $past(count))
    );

// When not in reset, count is always within 0..7.
    check_count_range_when_active: assert property (
        @(posedge clk) disable iff (!rst) 1'b1 |-> (count inside {[3'b000:3'b111]})
    );

// When not in reset, count is never X/Z.
    check_count_known_when_active: assert property (
        @(posedge clk) disable iff (!rst) 1'b1 |-> !$isunknown(count)
    );

// On reset assertion, count is 0 on the same cycle.
    check_reset_assertion_zero_now: assert property (
        @(posedge clk) $fell(rst) |-> (count == 3'b000)
    );

// On reset deassertion, count is 0 on the same cycle.
    check_reset_release_zero_now: assert property (
        @(posedge clk) $rose(rst) |-> (count == 3'b000)
    );

// On reset deassertion, count becomes 1 on the next cycle.
    check_reset_release_one_next: assert property (
        @(posedge clk) $rose(rst) |-> ##1 (count == 3'b001)
    );

// CLR clears both registers on the next cycle.
    check_clear_sets_outputs: assert property (
        @(posedge CLK) CLR |=> (Q == 4'b0000 && Q_next == 4'b0000)
    );

// LOAD copies D into both registers on the next cycle.
    check_load_copies_d: assert property (
        @(posedge CLK) disable iff (CLR) LOAD |=> (Q == $past(D) && Q_next == $past(D))
    );

// With LOAD low, Q shifts left and captures D[3] into bit 0.
    check_shift_updates_q: assert property (
        @(posedge CLK) disable iff (CLR) !LOAD |=> (Q == {$past(Q[2:0]), $past(D[3])})
    );

// CLR overrides LOAD when both are asserted.
    check_clear_priority_over_load: assert property (
        @(posedge CLK) (CLR && LOAD) |=> (Q == 4'b0000 && Q_next == 4'b0000)
    );

// Y must match the 4-to-1 mux function.
    check_mux_function: assert property (
        @(posedge clk)
        Y == (S1 ? (S0 ? D3 : D2) : (S0 ? D1 : D0))
    );

// When S1 is low, Y selects between D0 and D1.
    check_select_low_path: assert property (
        @(posedge clk)
        !S1 |-> (Y == (S0 ? D1 : D0))
    );

// When S1 is high, Y selects between D2 and D3.
    check_select_high_path: assert property (
        @(posedge clk)
        S1 |-> (Y == (S0 ? D3 : D2))
    );

// With S1 low and S0 low, Y must equal D0.
    check_select_00: assert property (
        @(posedge clk)
        (!S1 && !S0) |-> (Y == D0)
    );

// With S1 low and S0 high, Y must equal D1.
    check_select_01: assert property (
        @(posedge clk)
        (!S1 && S0) |-> (Y == D1)
    );

// With S1 high and S0 low, Y must equal D2.
    check_select_10: assert property (
        @(posedge clk)
        (S1 && !S0) |-> (Y == D2)
    );

// With S1 high and S0 high, Y must equal D3.
    check_select_11: assert property (
        @(posedge clk)
        (S1 && S0) |-> (Y == D3)
    );

// With S1 low, a change on S0 must change Y between D0 and D1.
    check_select_low_s0_change: assert property (
        @(posedge clk)
        (!S1 && $changed(S0)) |-> (Y == (S0 ? D1 : D0))
    );

// With S1 high, a change on S0 must change Y between D2 and D3.
    check_select_high_s0_change: assert property (
        @(posedge clk)
        (S1 && $changed(S0)) |-> (Y == (S0 ? D3 : D2))
    );

// With S0 low, a change on S1 must change Y between D0 and D2.
    check_select_low_s1_change: assert property (
        @(posedge clk)
        (!S0 && $changed(S1)) |-> (Y == (S1 ? D2 : D0))
    );

// With S0 high, a change on S1 must change Y between D1 and D3.
    check_select_high_s1_change: assert property (
        @(posedge clk)
        (S0 && $changed(S1)) |-> (Y == (S1 ? D3 : D1))
    );

// out_and is the reduction-AND of all input bits.
    check_out_and_matches_reduction_and: assert property (
        @(posedge clk) out_and == (&in)
    );

// If out_and is high, at least one input bit must be high.
    check_out_and_high_requires_any_input_high: assert property (
        @(posedge clk) out_and |-> (|in)
    );

// If out_and is low, all input bits must be low.
    check_out_and_low_requires_all_inputs_low: assert property (
        @(posedge clk) !out_and |-> (~&in)
    );

// X must equal the OR of A and B.
    check_or_function: assert property (
        @(posedge clk) X == (A | B)
    );

// If both inputs are low, X must be low.
    check_both_inputs_low: assert property (
        @(posedge clk) (!A && !B) |-> !X
    );

// If A is high, X must be high.
    check_a_high_sets_x: assert property (
        @(posedge clk) A |-> X
    );

// If B is high, X must be high.
    check_b_high_sets_x: assert property (
        @(posedge clk) B |-> X
    );

// If X is low, both inputs must be low.
    check_x_low_requires_both_inputs_low: assert property (
        @(posedge clk) !X |-> (!A && !B)
    );

// If X is high, at least one input must be high.
    check_x_high_requires_some_input_high: assert property (
        @(posedge clk) X |-> (A || B)
    );

// Active-low reset forces Q low and QN high.
    check_reset_state: assert property (
        @(posedge CLK) !RST |-> (Q == 1'b0 && QN == 1'b1)
    );

// Reset has priority over D changes while reset is asserted.
    check_reset_priority_over_d: assert property (
        @(posedge CLK) (!RST && $changed(D)) |-> (Q == 1'b0 && QN == 1'b1)
    );

// With reset high, Q captures D on the next clock.
    check_q_captures_d: assert property (
        @(posedge CLK) disable iff (!RST) 1'b1 |=> (Q == $past(D))
    );

// With reset high, QN captures the inverse of D on the next clock.
    check_qn_captures_inv_d: assert property (
        @(posedge CLK) disable iff (!RST) 1'b1 |=> (QN == ~$past(D))
    );

// With reset high, Q and QN remain complementary on the next clock.
    check_outputs_complementary: assert property (
        @(posedge CLK) disable iff (!RST) 1'b1 |=> (QN == ~Q)
    );

// X must match the implemented OR-of-AND function.
    check_x_matches_function: assert property (
        @(posedge clk) X == ((A1 & A2) | B1 | C1)
    );

// B1 high must force X high.
    check_b1_forces_x_high: assert property (
        @(posedge clk) B1 |-> X
    );

// C1 high must force X high.
    check_c1_forces_x_high: assert property (
        @(posedge clk) C1 |-> X
    );

// A1 and A2 high together must force X high.
    check_a1_a2_force_x_high: assert property (
        @(posedge clk) (A1 & A2) |-> X
    );

// With B1 and C1 low, X reduces to the A1/A2 AND term.
    check_no_b1_c1_reduces_to_and: assert property (
        @(posedge clk) (!B1 && !C1) |-> (X == (A1 & A2))
    );

// With A1 and A2 low, X reduces to the OR of B1 and C1.
    check_no_a1_a2_reduces_to_or: assert property (
        @(posedge clk) (!A1 && !A2) |-> (X == (B1 | C1))
    );

// If X is low, both the AND term and both OR inputs must be low.
    check_x_low_requires_all_terms_low: assert property (
        @(posedge clk) !X |-> (!B1 && !C1 && !(A1 & A2))
    );

// Bit 0 sum is the XOR of A[0], B[0], and Cin.
    check_sum_bit0: assert property (
        @(posedge clk)
        S[0] == (A[0] ^ B[0] ^ Cin)
    );

// Bit 2 sum uses the carry generated by bits 0 and 1.
    check_sum_bit2: assert property (
        @(posedge clk)
        S[2] == (A[2] ^ B[2] ^
                 ((A[1] & B[1]) |
                  (B[1] & ((A[0] & B[0]) | (B[0] & Cin) | (A[0] & Cin))) |
                  (A[1] & ((A[0] & B[0]) | (B[0] & Cin) | (A[0] & Cin)))))
    );

// While reset is asserted low, count must be 0.
    reset_forces_zero: assert property (
        @(posedge clk) !reset |-> (count == 4'd0)
    );

// When enable is HIGH, count increments by 1 on the next cycle.
    increment_on_enable: assert property (
        @(posedge clk) disable iff (!reset) enable |=> (count == $past(count) + 4'd1)
    );

// When enable is LOW, count holds its value on the next cycle.
    hold_when_disabled: assert property (
        @(posedge clk) disable iff (!reset) !enable |=> (count == $past(count))
    );

// Any change in count (excluding reset) requires enable to be HIGH.
    change_requires_enable: assert property (
        @(posedge clk) disable iff (!reset) $changed(count) |-> enable
    );

// If count is 0 (excluding reset), the previous cycle must have been a wrap or hold.
    zero_implies_prev_zero_or_hold: assert property (
        @(posedge clk) disable iff (!reset) (count == 4'd0) |-> ($past(reset) && ($past(enable) || ($past(count) == 4'd0)))
    );

// If count is 15 (excluding reset), the next cycle must wrap to 0 when enable is HIGH.
    wrap_on_max_when_enabled: assert property (
        @(posedge clk) disable iff (!reset) (count == 4'd15 && enable) |=> (count == 4'd0)
    );

// With enable HIGH and count at 15, the next cycle must not increment further (wrap behavior).
    no_increment_past_max: assert property (
        @(posedge clk) disable iff (!reset) (count == 4'd15 && enable) |=> (count == 4'd0)
    );

// With enable HIGH and count not at 15, the next cycle increments by 1.
    increment_no_wrap_when_enabled: assert property (
        @(posedge clk) disable iff (!reset) (count != 4'd15 && enable) |=> (count == $past(count) + 4'd1)
    );

// With enable LOW and count not at 0, the next cycle holds its value.
    hold_no_wrap_when_disabled: assert property (
        @(posedge clk) disable iff (!reset) (count != 4'd0 && !enable) |=> (count == $past(count))
    );

// With enable LOW and count at 0, the next cycle holds its value (no wrap on hold).
    hold_at_zero_when_disabled: assert property (
        @(posedge clk) disable iff (!reset) (count == 4'd0 && !enable) |=> (count == 4'd0)
    );

// With clock low, q is the shifted address with zeros in bits [1:0].
    check_q_when_clock_low: assert property (
        @(posedge clock) !clock |-> (q == (address << 2))
    );

// With clock high, q is the inverted shifted address with ones in bits [1:0].
    check_q_when_clock_high: assert property (
        @(posedge clock) clock |-> (q == ~(address << 2))
    );

// The low two bits of q are always zero.
    check_q_low_bits_zero: assert property (
        @(posedge clock) q[1:0] == 2'b00
    );

// The upper eight bits of q are either the address or its inverse.
    check_q_upper_byte_matches_address: assert property (
        @(posedge clock) q[11:2] == (clock ? ~address : address)
    );

// X must match the implemented combinational function.
    check_x_matches_function: assert property (
        @(posedge clk)
        X == ((A_N == 1'b1) && (B == 1'b1) && (C == 1'b1))
    );

// All three active inputs must drive X high.
    check_all_active_inputs_drive_x_high: assert property (
        @(posedge clk)
        ((A_N == 1'b1) && (B == 1'b1) && (C == 1'b1)) |-> (X == 1'b1)
    );

// Any low input must drive X low.
    check_any_low_input_drives_x_low: assert property (
        @(posedge clk)
        ((A_N == 1'b0) || (B == 1'b0) || (C == 1'b0)) |-> (X == 1'b0)
    );

// X high requires all three active inputs.
    check_x_high_requires_all_active_inputs: assert property (
        @(posedge clk)
        (X == 1'b1) |-> ((A_N == 1'b1) && (B == 1'b1) && (C == 1'b1))
    );

// X low requires at least one low input.
    check_x_low_requires_any_low_input: assert property (
        @(posedge clk)
        (X == 1'b0) |-> ((A_N == 1'b0) || (B == 1'b0) || (C == 1'b0))
    );

// Reset forces the counter to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |-> (count == 4'b0000)
    );

// The first sampled cycle after reset release still shows zero.
    check_reset_release_starts_from_zero: assert property (
        @(posedge clk) disable iff (rst) $past(rst) |-> (count == 4'b0000)
    );

// Reset drives outputs to zero on the next cycle.
    reset_clears_outputs: assert property (
        @(posedge clk) rst |=> (control_o == 9'b0) && (pc_op == 2'b00)
    );

// When en is LOW, outputs hold their previous values.
    hold_when_en_low: assert property (
        @(posedge clk) disable iff (rst) !en |=> (control_o == $past(control_o)) && (pc_op == $past(pc_op))
    );

// When en is HIGH, control_o[0] captures en_mem.
    control0_captures_en_mem: assert property (
        @(posedge clk) disable iff (rst) en |=> (control_o[0] == $past(en_mem))
    );

// When en is HIGH, control_o[1] captures should_branch.
    control1_captures_should_branch: assert property (
        @(posedge clk) disable iff (rst) en |=> (control_o[1] == $past(should_branch))
    );

// When en is HIGH, control_o[2] captures imm.
    control2_captures_imm: assert property (
        @(posedge clk) disable iff (rst) en |=> (control_o[2] == $past(imm))
    );

// When en is HIGH and imm is HIGH, pc_op captures 2'b10.
    pc_op_captures_10_on_imm: assert property (
        @(posedge clk) disable iff (rst) (en && imm) |=> (pc_op == 2'b10)
    );

// When en is HIGH and imm is LOW, pc_op captures 2'b00.
    pc_op_captures_00_on_no_imm: assert property (
        @(posedge clk) disable iff (rst) (en && !imm) |=> (pc_op == 2'b00)
    );

// pc_op can only be 2'b00 or 2'b10 when en is HIGH.
    pc_op_legal_values_when_en: assert property (
        @(posedge clk) disable iff (rst) en |=> ((pc_op == 2'b00) || (pc_op == 2'b10))
    );

// Z must equal the AND of all four inputs.
    check_output_matches_and4: assert property (
        @(posedge clk) Z == (A & B & C & D)
    );

// All inputs high must drive Z high.
    check_all_inputs_high_drive_output_high: assert property (
        @(posedge clk) (A & B & C & D) |-> Z
    );

// A low must force Z low.
    check_a_low_forces_output_low: assert property (
        @(posedge clk) !A |-> !Z
    );

// B low must force Z low.
    check_b_low_forces_output_low: assert property (
        @(posedge clk) !B |-> !Z
    );

// C low must force Z low.
    check_c_low_forces_output_low: assert property (
        @(posedge clk) !C |-> !Z
    );

// D low must force Z low.
    check_d_low_forces_output_low: assert property (
        @(posedge clk) !D |-> !Z
    );

// Z high requires all inputs high.
    check_output_high_requires_all_inputs_high: assert property (
        @(posedge clk) Z |-> (A & B & C & D)
    );

// sum must equal the XOR of A and B.
    check_sum_xor: assert property (
        @(posedge clk) sum == (A ^ B)
    );

// carry_out must equal the AND of A and B.
    check_carry_and: assert property (
        @(posedge clk) carry_out == (A & B)
    );

// When both inputs are low, sum is low and carry_out is low.
    check_zero_inputs: assert property (
        @(posedge clk) (!A && !B) |-> (!sum && !carry_out)
    );

// When only A is high, sum is high and carry_out is low.
    check_a_only: assert property (
        @(posedge clk) (A && !B) |-> (sum && !carry_out)
    );

// When only B is high, sum is high and carry_out is low.
    check_b_only: assert property (
        @(posedge clk) (!A && B) |-> (sum && !carry_out)
    );

// When both inputs are high, sum is low and carry_out is high.
    check_both_high: assert property (
        @(posedge clk) (A && B) |-> (!sum && carry_out)
    );

// X must equal the OR of A1 through A4 gated by B1.
    check_x_matches_or_and_function: assert property (
        @(posedge clk) X == (B1 & (A1 | A2 | A3 | A4))
    );

// B1 low forces X low.
    check_b1_low_forces_x_low: assert property (
        @(posedge clk) !B1 |-> !X
    );

// All A inputs low force X low.
    check_all_a_low_forces_x_low: assert property (
        @(posedge clk) !(A1 | A2 | A3 | A4) |-> !X
    );

// With B1 high, any asserted A input forces X high.
    check_b1_high_and_any_a_high_forces_x_high: assert property (
        @(posedge clk) (B1 & (A1 | A2 | A3 | A4)) |-> X
    );

// A high X requires B1 to be high.
    check_x_high_requires_b1_high: assert property (
        @(posedge clk) X |-> B1
    );

// A high X requires at least one A input to be high.
    check_x_high_requires_any_a_high: assert property (
        @(posedge clk) X |-> (A1 | A2 | A3 | A4)
    );

// With B1 high, a low X means all A inputs are low.
    check_b1_high_and_x_low_requires_all_a_low: assert property (
        @(posedge clk) (B1 & !X) |-> !(A1 | A2 | A3 | A4)
    );

// On reset, count becomes 0 on the next cycle.
    reset_clears_next: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

// When enabled and not in reset, count increments by 1 on the next cycle.
    increment_when_enabled: assert property (
        @(posedge clk) disable iff (reset) enable |=> (count == $past(count) + 4'd1)
    );

// When not enabled and not in reset, count holds its value on the next cycle.
    hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset) !enable |=> (count == $past(count))
    );

// If reset is held for two consecutive cycles, count is 0 in the second cycle.
    reset_hold_keeps_zero: assert property (
        @(posedge clk) reset && $past(reset) |-> (count == 4'b0000)
    );

// If enable is held for two consecutive cycles and count is 0, it remains 0.
    enable_hold_zero_stays_zero: assert property (
        @(posedge clk) disable iff (reset) (enable && $past(enable) && (count == 4'b0000)) |-> (count == 4'b0000)
    );

// If reset is held for two consecutive cycles and count is not 0, it becomes 0 in the second cycle.
    reset_hold_clears_nonzero: assert property (
        @(posedge clk) reset && $past(reset) && (count != 4'b0000) |-> (count == 4'b0000)
    );

// If reset is held for two consecutive cycles and count is 0, it remains 0.
    reset_hold_zero_stays_zero: assert property (
        @(posedge clk) reset && $past(reset) && (count == 4'b0000) |-> (count == 4'b0000)
    );

// When SEL[1] is high, result comes from the barrel shifter path.
    check_result_selects_shifter: assert property (
        @(posedge clk) SEL[1] |-> (result == (SEL[0] ? (A >> B) : (A << B)))
    );

// With SEL[1] low and SEL[0] low, result is A plus B.
    check_add_mode: assert property (
        @(posedge clk) (!SEL[1] && !SEL[0]) |-> (result == (A + B))
    );

// With SEL[1] low and SEL[0] high, result is A minus B.
    check_sub_mode: assert property (
        @(posedge clk) (!SEL[1] && SEL[0]) |-> (result == (A - B))
    );

// With SEL[1] high and SEL[0] low, result is A left-shifted by B.
    check_left_shift_mode: assert property (
        @(posedge clk) (SEL[1] && !SEL[0]) |-> (result == (A << B))
    );

// With SEL[1] high and SEL[0] high, result is A right-shifted by B.
    check_right_shift_mode: assert property (
        @(posedge clk) (SEL[1] && SEL[0]) |-> (result == (A >> B))
    );

// With SEL[1] low and B equal to zero, addition passes A through.
    check_add_zero_b_passthrough: assert property (
        @(posedge clk) (!SEL[1] && (B == 16'h0000)) |-> (result == A)
    );

// With SEL[1] low and B equal to zero, subtraction passes A through.
    check_sub_zero_b_passthrough: assert property (
        @(posedge clk) (!SEL[1] && SEL[0] && (B == 16'h0000)) |-> (result == A)
    );

// With SEL[1] high and B equal to zero, left shift passes A through.
    check_left_shift_zero_b_passthrough: assert property (
        @(posedge clk) (SEL[1] && !SEL[0] && (B == 16'h0000)) |-> (result == A)
    );

// With SEL[1] high and B equal to zero, right shift passes A through.
    check_right_shift_zero_b_passthrough: assert property (
        @(posedge clk) (SEL[1] && SEL[0] && (B == 16'h0000)) |-> (result == A)
    );

// Reset clears both state registers.
    check_reset_clears_state: assert property (
        @(posedge clk) !rst_n |-> (rat == 8'h00) && (pc == 8'h00)
    );

// Reset forces the output select path to the PC register.
    check_reset_selects_pc: assert property (
        @(posedge clk) !rst_n |-> (m_at == pc)
    );

// Load low clears valid on the next cycle.
    check_load_low_clears_valid: assert property (
        @(posedge load) !load |=> (valid == 1'b0)
    );

// Load low leaves out unchanged on the next cycle.
    check_load_low_holds_out: assert property (
        @(posedge load) !load |=> (out == $past(out))
    );

// valid is low exactly one cycle after a load low.
    check_valid_low_one_cycle_after_load_low: assert property (
        @(posedge load) !load |=> ##1 !valid
    );

// valid is low exactly one cycle after a load low and high.
    check_valid_low_one_cycle_after_load_low_or_load: assert property (
        @(posedge load) !load |=> ##1 !valid
    );

// Load captures data_in into the register on the next cycle.
    check_load_captures_data: assert property (
        @(posedge clk) load |=> (data_out == $past(data_in))
    );

// When not loading, the register shifts left and inserts zero at bit 0.
    check_shift_updates_register: assert property (
        @(posedge clk) !load |=> (data_out == {$past(data_out[2:0]), 1'b0})
    );

// The upper three bits shift from the previous lower three bits.
    check_shift_moves_upper_bits: assert property (
        @(posedge clk) !load |=> (data_out[3:1] == $past(data_out[2:0]))
    );

// Y matches the implemented AND-NOR-ORI function.
    check_function_equivalence: assert property (
        @(posedge clk) Y == ~(A1 & A2 & A3 | B1 | C1)
    );

// B1 high forces the NOR output low.
    check_b1_forces_y_low: assert property (
        @(posedge clk) B1 |-> !Y
    );

// C1 high forces the NOR output low.
    check_c1_forces_y_low: assert property (
        @(posedge clk) C1 |-> !Y
    );

// All three A inputs high force the AND term high and Y low.
    check_all_a_high_forces_y_low: assert property (
        @(posedge clk) (A1 & A2 & A3) |-> !Y
    );

// With B1 and C1 low, Y reduces to the inverted 3-input AND of A1/A2/A3.
    check_bc_low_reduces_to_and3: assert property (
        @(posedge clk) (!B1 && !C1) |-> (Y == ~(A1 & A2 & A3))
    );

// With B1 and C1 low, Y high means the AND term must be low.
    check_bc_low_y_high_requires_and_term_low: assert property (
        @(posedge clk) (!B1 && !C1 && Y) |-> !(A1 & A2 & A3)
    );

// With B1 and C1 low, Y low means the AND term must be high.
    check_bc_low_y_low_requires_and_term_high: assert property (
        @(posedge clk) (!B1 && !C1 && !Y) |-> (A1 & A2 & A3)
    );

// With B1 and C1 low, a high Y implies not all A inputs are high.
    check_bc_low_y_high_implies_not_all_a_high: assert property (
        @(posedge clk) (!B1 && !C1 && Y) |-> !(A1 & A2 & A3)
    );

// With B1 and C1 low, a low Y implies all A inputs are high.
    check_bc_low_y_low_implies_all_a_high: assert property (
        @(posedge clk) (!B1 && !C1 && !Y) |-> (A1 & A2 & A3)
    );

// Reset forces count to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |-> (count == 4'd0)
    );

// On the cycle reset deasserts, count is still zero.
    check_reset_release_starts_from_zero: assert property (
        @(posedge clk) $fell(rst) |-> (count == 4'd0)
    );

// If both NOR terms are low, Y must be high.
    check_both_nor_terms_low_sets_y: assert property (
        @(posedge clk) ((~(A3 | A1 | A2)) && (~(B1 | B2))) |-> Y
    );

// Clock: clk (posedge). Reset: reset (active-high, asynchronous). Sequential 4-bit counter.

    // On reset deassertion, count becomes 0 on the next cycle.
    reset_deassert_sets_zero: assert property (
        @(posedge clk) disable iff (reset) $fell(reset) |-> (count == 4'd0)
    );

// While reset is held high across cycles, count is 0.
    hold_zero_while_reset: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (count == 4'd0)
    );

// When not in reset for two consecutive cycles, count wraps from 15 to 0.
    wrap_from_max: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset) && ($past(count) == 4'hF)) |-> (count == 4'h0)
    );

// On reset assertion, count is 0 in the same cycle.
    reset_assert_sets_zero: assert property (
        @(posedge clk) reset |-> (count == 4'd0)
    );

// On reset assertion, count remains 0 on the next cycle.
    reset_assert_next_cycle_zero: assert property (
        @(posedge clk) reset |-> ##1 (count == 4'd0)
    );

// On reset deassertion, count is 0 in the same cycle.
    reset_deassert_sets_zero_now: assert property (
        @(posedge clk) $fell(reset) |-> (count == 4'd0)
    );

// If count is 1 while not in reset, the previous value was 0.
    one_implies_prev_zero: assert property (
        @(posedge clk) disable iff (reset) (count == 4'd1) |-> ($past(count) == 4'd0)
    );

// Output must match the selected shift operation.
    check_shift_function: assert property (
        @(posedge clk) out == (dir ? (in >> shift) : (in << shift))
    );

// Zero shift must pass the input through unchanged.
    check_zero_shift_passthrough: assert property (
        @(posedge clk) (shift == 4'd0) |-> (out == in)
    );

// Left shift by one must insert a zero into the least-significant bit.
    check_left_shift_by_one: assert property (
        @(posedge clk) (dir == 1'b0 && shift == 4'd1) |-> (out == {in[14:0], 1'b0})
    );

// Right shift by one must insert a zero into the most-significant bit.
    check_right_shift_by_one: assert property (
        @(posedge clk) (dir == 1'b1 && shift == 4'd1) |-> (out == {1'b0, in[15:1]})
    );

// Left shift by eight must zero the lower eight bits.
    check_left_shift_by_eight: assert property (
        @(posedge clk) (dir == 1'b0 && shift == 4'd8) |-> (out == {in[7:0], 8'h00})
    );

// Right shift by fifteen must move the input into the lower seven bits.
    check_right_shift_by_fifteen: assert property (
        @(posedge clk) (dir == 1'b1 && shift == 4'd15) |-> (out == {7'h00, in[15]})
    );

// Full 5-bit result matches a + b + cin.
    check_full_addition: assert property (
        @(posedge clk) {cout, sum} == ({1'b0, a} + {1'b0, b} + cin)
    );

// Sum bit 0 matches the first full-adder XOR.
    check_sum_bit0: assert property (
        @(posedge clk) sum[0] == (a[0] ^ b[0] ^ cin)
    );

// Sum bit 1 uses the carry generated by bit 0.
    check_sum_bit1: assert property (
        @(posedge clk) sum[1] == (
            a[1] ^ b[1] ^
            ((a[0] & b[0]) | (a[0] & cin) | (b[0] & cin))
        )
    );

// Sum bit 2 uses the ripple carry from bits 0 and 1.
    check_sum_bit2: assert property (
        @(posedge clk) sum[2] == (
            a[2] ^ b[2] ^
            (
                (a[1] & b[1]) |
                (a[1] & ((a[0] & b[0]) | (a[0] & cin) | (b[0] & cin))) |
                (b[1] & ((a[0] & b[0]) | (a[0] & cin) | (b[0] & cin)))
            )
        )
    );

// Reset forces count to zero on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 32'd0)
    );

// Reset has priority over enable when both are asserted.
    check_reset_priority_over_enable: assert property (
        @(posedge clk) (rst && enable) |=> (count == 32'd0)
    );

// When enabled outside reset, count increments by one.
    check_count_increments_when_enabled: assert property (
        @(posedge clk) disable iff (rst) enable |=> (count == ($past(count) + 32'd1))
    );

// When not enabled outside reset, count holds its value.
    check_count_holds_when_disabled: assert property (
        @(posedge clk) disable iff (rst) !enable |=> (count == $past(count))
    );

// Reset drives reg_0x1F to 0x00 on the next cycle.
    reset_clears_next: assert property (
        @(posedge clk) reset |=> (reg_0x1F == 8'h00)
    );

// When not in reset and wenb is 0, next value equals in_data.
    write_updates_value: assert property (
        @(posedge clk) disable iff (reset) (!wenb) |=> (reg_0x1F == $past(in_data))
    );

// When not in reset and wenb is 1, next value holds its previous value.
    hold_when_wenb_high: assert property (
        @(posedge clk) disable iff (reset) (wenb) |=> (reg_0x1F == $past(reg_0x1F))
    );

// If reset is held high across cycles, reg_0x1F is 0x00 in the later cycle.
    reset_hold_keeps_zero: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (reg_0x1F == 8'h00)
    );

// If reset is held high across cycles, reg_0x1F remains stable.
    reset_hold_keeps_stable: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (reg_0x1F == $past(reg_0x1F))
    );

// If not in reset and wenb is 1, reg_0x1F does not change.
    hold_no_change: assert property (
        @(posedge clk) disable iff (reset) (wenb) |=> (reg_0x1F == $past(reg_0x1F))
    );

// If not in reset and wenb is 0, the new value equals the prior in_data.
    write_updates_to_prior_in: assert property (
        @(posedge clk) disable iff (reset) (!wenb) |=> (reg_0x1F == $past(in_data))
    );

// If not in reset and wenb is 1, the new value equals the prior reg_0x1F.
    hold_updates_to_prior_reg: assert property (
        @(posedge clk) disable iff (reset) (wenb) |=> (reg_0x1F == $past(reg_0x1F))
    );

// parity_error equals XOR reduction of data.
    check_parity_definition: assert property (
        @(posedge data[0]) parity_error == (^data)
    );

// If data is all zeros, parity_error must be 0.
    check_zero_data_implies_no_error: assert property (
        @(posedge data[0]) (data == 8'h00) |-> (parity_error == 1'b0)
    );

// If data is all ones, parity_error must be 0.
    check_all_ones_implies_no_error: assert property (
        @(posedge data[0]) (data == 8'hFF) |-> (parity_error == 1'b0)
    );

// If data is even (XOR == 0), parity_error must be 0.
    check_even_parity_implies_no_error: assert property (
        @(posedge data[0]) (^data == 1'b0) |-> (parity_error == 1'b0)
    );

// If data is odd (XOR == 1), parity_error must be 1.
    check_odd_parity_implies_error: assert property (
        @(posedge data[0]) (^data == 1'b1) |-> (parity_error == 1'b1)
    );

// Reset forces the register output to zero.
    check_reset_clears_q: assert property (
        @(posedge clk) reset |-> (Q == 4'b0000)
    );

// Reset has priority over load when both are asserted.
    check_reset_priority_over_load: assert property (
        @(posedge clk) (reset && load) |-> (Q == 4'b0000)
    );

// With load asserted, the next sampled output matches the input.
    check_load_captures_data: assert property (
        @(posedge clk) disable iff (reset) load |=> (Q == $past(data_in))
    );

// With load deasserted, the output holds its previous value.
    check_hold_when_load_deasserted: assert property (
        @(posedge clk) disable iff (reset) !load |=> (Q == $past(Q))
    );

// SUM matches the three-input XOR function.
    check_sum_function: assert property (
        @(posedge clk) SUM == (A ^ B ^ CI)
    );

// COUT matches the three-input majority function.
    check_cout_function: assert property (
        @(posedge clk) COUT == ((A & B) | (B & CI) | (CI & A))
    );

// All-zero inputs produce zero sum and zero carry.
    check_zero_inputs: assert property (
        @(posedge clk) (!A && !B && !CI) |-> (!SUM && !COUT)
    );

// Any one-hot input combination produces sum without carry.
    check_one_hot_inputs: assert property (
        @(posedge clk)
        (( A && !B && !CI) ||
         (!A &&  B && !CI) ||
         (!A && !B &&  CI)) |-> (SUM && !COUT)
    );

// Any two-hot input combination produces carry without sum.
    check_two_hot_inputs: assert property (
        @(posedge clk)
        (( A &&  B && !CI) ||
         ( A && !B &&  CI) ||
         (!A &&  B &&  CI)) |-> (!SUM && COUT)
    );

// Load captures input_data into Q on the next cycle.
    check_load_captures_input: assert property (
        @(posedge clk) load |=> (Q == $past(input_data))
    );

// With load low and up_down high, Q increments by one.
    check_increment_when_up: assert property (
        @(posedge clk) (!load && up_down) |=> (Q == ($past(Q) + 4'd1))
    );

// With load low and up_down low, Q decrements by one.
    check_decrement_when_down: assert property (
        @(posedge clk) (!load && !up_down) |=> (Q == ($past(Q) - 4'd1))
    );

// With load low and up_down high, Q must change.
    check_increment_changes_q: assert property (
        @(posedge clk) (!load && up_down) |=> (Q != $past(Q))
    );

// With load low and up_down low, Q must change.
    check_decrement_changes_q: assert property (
        @(posedge clk) (!load && !up_down) |=> (Q != $past(Q))
    );

// X matches the implemented NAND/OR/AND function.
    check_x_matches_function: assert property (
        @(posedge clk) X == ((~(A2_N & A1_N)) & (B2 | B1))
    );

// Both A inputs high force X low.
    check_a_inputs_high_force_x_low: assert property (
        @(posedge clk) (A1_N & A2_N) |-> !X
    );

// Both B inputs low force X low.
    check_b_inputs_low_force_x_low: assert property (
        @(posedge clk) (!B1 & !B2) |-> !X
    );

// With A inputs low and either B input high, X is high.
    check_active_condition_drives_x_high: assert property (
        @(posedge clk) ((!A1_N & !A2_N) & (B1 | B2)) |-> X
    );

// X can only be high when both A inputs are not both high.
    check_x_high_requires_a_not_both_high: assert property (
        @(posedge clk) X |-> !(A1_N & A2_N)
    );

// X can only be high when at least one B input is high.
    check_x_high_requires_b_or: assert property (
        @(posedge clk) X |-> (B1 | B2)
    );

// change is asserted only when coin is high and no valid selection is made.
    check_change_definition: assert property (
        @(posedge clk) change == (coin & ~((button1 | button2 | button3) & ~coin))
    );

// change and any product output are never asserted together.
    check_change_mutex: assert property (
        @(posedge clk) !(change & (product1 | product2 | product3))
    );

// With no coin and no valid selection, both change and a product must be low.
    check_no_selection_behavior: assert property (
        @(posedge clk) (~coin & ~(button1 | button2 | button3)) |-> (~change & ~product1 & ~product2 & ~product3)
    );

// With coin high and no valid selection, change must be high and no product can be high.
    check_coin_only_behavior: assert property (
        @(posedge clk) (coin & ~(button1 | button2 | button3)) |-> (change & ~product1 & ~product2 & ~product3)
    );

// With coin high and no valid selection, the product outputs must be low.
    check_coin_no_selection_product_low: assert property (
        @(posedge clk) (coin & ~(button1 | button2 | button3)) |-> (~product1 & ~product2 & ~product3)
    );

// While reset is asserted (active-low), COUNT must be 0.
    reset_forces_zero: assert property (
        @(posedge clk) (RST == 1'b0) |-> (COUNT == 4'b0000)
    );

// On reset deassertion, COUNT becomes 0 in the same cycle.
    reset_release_clears: assert property (
        @(posedge clk) $rose(RST) |-> (COUNT == 4'b0000)
    );

// With EN=1 and not in reset, COUNT increments by 1 (mod 16).
    count_increments_when_en: assert property (
        @(posedge clk) disable iff (!RST) (EN == 1'b1) |-> (COUNT == $past(COUNT) + 4'd1)
    );

// With EN=0 and not in reset, COUNT holds its value.
    count_holds_when_en0: assert property (
        @(posedge clk) disable iff (!RST) (EN == 1'b0) |-> (COUNT == $past(COUNT))
    );

// Any change in COUNT (excluding reset) requires EN=1 in the prior cycle.
    change_requires_prev_en: assert property (
        @(posedge clk) disable iff (!RST) (COUNT != $past(COUNT)) |-> ($past(EN) == 1'b1)
    );

// If EN=1 and not in reset, COUNT must change (no wrap at 15->0).
    en_implies_change_no_wrap: assert property (
        @(posedge clk) disable iff (!RST) (EN == 1'b1) |-> (COUNT != $past(COUNT))
    );

// If EN=0 and not in reset, COUNT must not change.
    en0_implies_no_change: assert property (
        @(posedge clk) disable iff (!RST) (EN == 1'b0) |-> (COUNT == $past(COUNT))
    );

// If EN=1 and COUNT is 15 (not in reset), next COUNT wraps to 0.
    wrap_on_max_when_en: assert property (
        @(posedge clk) disable iff (!RST) (EN == 1'b1 && COUNT == 4'hF) |-> ##1 (COUNT == 4'h0)
    );

// If EN=1 and COUNT is 0 (not in reset), next COUNT becomes 1.
    increment_from_zero_when_en: assert property (
        @(posedge clk) disable iff (!RST) (EN == 1'b1 && COUNT == 4'h0) |-> ##1 (COUNT == 4'h1)
    );

// If EN=0 and COUNT is 0 (not in reset), next COUNT remains 0.
    hold_zero_when_en0: assert property (
        @(posedge clk) disable iff (!RST) (EN == 1'b0 && COUNT == 4'h0) |-> ##1 (COUNT == 4'h0)
    );

// Y must equal the AND of all four inputs.
    check_y_matches_and_function: assert property (
        @(posedge clk) Y == (A1 & A2 & A3 & B1 & C1)
    );

// All inputs high must drive Y high.
    check_all_inputs_high_drive_y_high: assert property (
        @(posedge clk) (A1 & A2 & A3 & B1 & C1) |-> Y
    );

// A low A1 must force Y low.
    check_a1_low_forces_y_low: assert property (
        @(posedge clk) !A1 |-> !Y
    );

// A low A2 must force Y low.
    check_a2_low_forces_y_low: assert property (
        @(posedge clk) !A2 |-> !Y
    );

// A low A3 must force Y low.
    check_a3_low_forces_y_low: assert property (
        @(posedge clk) !A3 |-> !Y
    );

// A low B1 must force Y low.
    check_b1_low_forces_y_low: assert property (
        @(posedge clk) !B1 |-> !Y
    );

// A low C1 must force Y low.
    check_c1_low_forces_y_low: assert property (
        @(posedge clk) !C1 |-> !Y
    );

// A high Y requires all inputs to be high.
    check_y_high_requires_all_inputs_high: assert property (
        @(posedge clk) Y |-> (A1 & A2 & A3 & B1 & C1)
    );

// eff_addr must match the RTL address remap.
    check_eff_addr_map: assert property (
        @(posedge clk)
        eff_addr == ((mod == 8'h01) ? {8'h00, addr[23:0]} : {12'h000, addr[19:0]})
    );

// mod 0x01 maps to the upper 24 address bits with zero extension.
    check_mod_01_mapping: assert property (
        @(posedge clk)
        (mod == 8'h01) |-> (eff_addr == {8'h00, addr[23:0]})
    );

// All other mods map to the upper 20 address bits with zero extension.
    check_other_mod_mapping: assert property (
        @(posedge clk)
        (mod != 8'h01) |-> (eff_addr == {12'h000, addr[19:0]})
    );

// eff_addr[19:0] is always the low 20 address bits.
    check_eff_addr_low20: assert property (
        @(posedge clk)
        eff_addr[19:0] == addr[19:0]
    );

// X must match the implemented combinational equation.
    check_x_matches_logic: assert property (
        @(posedge clk) X == ((A1 & A2 & ~B1_N) | (~A1 & (A2 | B1_N)))
    );

// When A1 is low, X reduces to A2 OR B1_N.
    check_a1_low_branch: assert property (
        @(posedge clk) !A1 |-> (X == (A2 | B1_N))
    );

// When A1 is high, X reduces to A2 AND inverted B1_N.
    check_a1_high_branch: assert property (
        @(posedge clk) A1 |-> (X == (A2 & ~B1_N))
    );

// Z must always match the tri-state function.
    check_z_matches_function: assert property (
        @(posedge clk) Z == (TE_B ? 1'b0 : A)
    );

// When tri-state is enabled, Z must be forced low.
    check_z_low_when_tri_state_enabled: assert property (
        @(posedge clk) TE_B |-> (Z == 1'b0)
    );

// When tri-state is disabled, Z must follow A.
    check_z_follows_a_when_enabled: assert property (
        @(posedge clk) !TE_B |-> (Z == A)
    );

// A low must appear on Z when enabled.
    check_a_low_appears_on_z: assert property (
        @(posedge clk) (!TE_B && !A) |-> (Z == 1'b0)
    );

// A high must appear on Z when enabled.
    check_a_high_appears_on_z: assert property (
        @(posedge clk) (!TE_B && A) |-> (Z == 1'b1)
    );

// ECK equals (E & SE) | (!E & CK).
    check_function_equivalence: assert property (
        @(posedge CK) ECK == ((E & SE) | (!E & CK))
    );

// When E is 1, ECK equals SE.
    check_eck_eq_se_when_e1: assert property (
        @(posedge CK) (E == 1'b1) |-> (ECK == SE)
    );

// When E is 0, ECK equals CK.
    check_eck_eq_ck_when_e0: assert property (
        @(posedge CK) (E == 1'b0) |-> (ECK == CK)
    );

// When SE is 0, ECK equals CK.
    check_eck_eq_ck_when_se0: assert property (
        @(posedge CK) (SE == 1'b0) |-> (ECK == CK)
    );

// When SE is 1, ECK equals E | CK.
    check_eck_eq_e_or_ck_when_se1: assert property (
        @(posedge CK) (SE == 1'b1) |-> (ECK == (E | CK))
    );

// When ECK is 1, then (E & SE) or (!E & CK) must hold.
    check_one_implies_e_and_se_or_not_e_and_ck: assert property (
        @(posedge CK) (ECK == 1'b1) |-> ((E & SE) | (!E & CK))
    );

// clk_gated equals clk AND active_q at each clk edge.
    check_clk_gated_definition: assert property (
        @(posedge clk) clk_gated == (clk & $past(active))
    );

// clk_gated is LOW whenever clk is LOW.
    check_clk_gated_low_when_clk_low: assert property (
        @(posedge clk) !clk |-> !clk_gated
    );

// clk_gated can be HIGH only when clk is HIGH.
    check_clk_gated_implies_clk_high: assert property (
        @(posedge clk) clk_gated |-> clk
    );

// If active was 0 on the previous clk, clk_gated must be 0 now.
    check_prev_active_zero_forces_clk_gated_zero: assert property (
        @(posedge clk) !$past(active) |-> !clk_gated
    );

// clk_gated can only rise when previous clk and active were both 1.
    check_clk_gated_rise_requires_prev_clk_active: assert property (
        @(posedge clk) $rose(clk_gated) |-> ($past(clk) && $past(active))
    );

// If clk_gated is 1 now, previous clk and active were both 1.
    check_clk_gated_one_implies_prev_clk_active: assert property (
        @(posedge clk) clk_gated |-> ($past(clk) && $past(active))
    );

// phy0_mdc mirrors mdio_mdc.
    check_phy0_mdc_passthrough: assert property (
        @(posedge mdio_mdc) phy0_mdc == mdio_mdc
    );

// phy1_mdc mirrors mdio_mdc.
    check_phy1_mdc_passthrough: assert property (
        @(posedge mdio_mdc) phy1_mdc == mdio_mdc
    );

// phy0_mdio_t mirrors mdio_t.
    check_phy0_mdio_t_passthrough: assert property (
        @(posedge mdio_t) phy0_mdio_t == mdio_t
    );

// phy1_mdio_t mirrors mdio_t.
    check_phy1_mdio_t_passthrough: assert property (
        @(posedge mdio_t) phy1_mdio_t == mdio_t
    );

// phy0_mdio_o mirrors mdio_o.
    check_phy0_mdio_o_passthrough: assert property (
        @(posedge mdio_o) phy0_mdio_o == mdio_o
    );

// phy1_mdio_o mirrors mdio_o.
    check_phy1_mdio_o_passthrough: assert property (
        @(posedge mdio_o) phy1_mdio_o == mdio_o
    );

// mdio_i is the AND of both PHY MDIO inputs.
    check_mdio_i_and: assert property (
        @(posedge mdio_i) mdio_i == (phy0_mdio_i & phy1_mdio_i)
    );

// mdio_i low means at least one PHY MDIO input is low.
    check_mdio_i_low_when_any_input_low: assert property (
        @(posedge mdio_i) !(phy0_mdio_i & phy1_mdio_i) == 1'b1
    );

// A1_N low forces OUT low.
    check_a1n_low_forces_out_low: assert property (
        @(posedge clk) !A1_N |-> !OUT
    );

// A2_N low forces OUT low.
    check_a2n_low_forces_out_low: assert property (
        @(posedge clk) !A2_N |-> !OUT
    );

// B1 low forces OUT low.
    check_b1_low_forces_out_low: assert property (
        @(posedge clk) !B1 |-> !OUT
    );

// B2 low forces OUT low.
    check_b2_low_forces_out_low: assert property (
        @(posedge clk) !B2 |-> !OUT
    );

// OUT high requires at least one A input and one B input high.
    check_out_high_requires_active_inputs: assert property (
        @(posedge clk) OUT |-> (A1_N & A2_N & B1 & B2)
    );

// With A1_N and B1 high, OUT reduces to A2_N & B2.
    check_a1n_b1_high_reduces_to_a2n_b2: assert property (
        @(posedge clk) (A1_N & B1) |-> (OUT == (A2_N & B2))
    );

// With A2_N and B2 high, OUT reduces to A1_N & B1.
    check_a2n_b2_high_reduces_to_a1n_b1: assert property (
        @(posedge clk) (A2_N & B2) |-> (OUT == (A1_N & B1))
    );

// With A1_N and B2 high, OUT reduces to A2_N & B1.
    check_a1n_b2_high_reduces_to_a2n_b1: assert property (
        @(posedge clk) (A1_N & B2) |-> (OUT == (A2_N & B1))
    );

// With A2_N and B1 high, OUT reduces to A1_N & B2.
    check_a2n_b1_high_reduces_to_a1n_b2: assert property (
        @(posedge clk) (A2_N & B1) |-> (OUT == (A1_N & B2))
    );

// out1 matches the nested AND expression implemented in the RTL.
    check_out1_matches_nested_and: assert property (
        @(posedge clk)
        out1 == ((in1 & in2) & (in3 & in4) & (in5 & in6) & (in7 & in8) & (in9 & (in1 & in2) & (in3 & in4) & (in5 & in6) & (in7 & in8)))
    );

// out1 reduces to the simple AND of all nine inputs.
    check_out1_reduces_to_simple_and: assert property (
        @(posedge clk)
        out1 == (in1 & in2 & in3 & in4 & in5 & in6 & in7 & in8 & in9)
    );

// All nine high inputs must drive out1 high.
    check_all_inputs_high_drive_out1_high: assert property (
        @(posedge clk)
        (in1 & in2 & in3 & in4 & in5 & in6 & in7 & in8 & in9) |-> out1
    );

// A low in1 must force out1 low.
    check_in1_low_forces_out1_low: assert property (
        @(posedge clk)
        !in1 |-> !out1
    );

// A low in2 must force out1 low.
    check_in2_low_forces_out1_low: assert property (
        @(posedge clk)
        !in2 |-> !out1
    );

// A low in3 must force out1 low.
    check_in3_low_forces_out1_low: assert property (
        @(posedge clk)
        !in3 |-> !out1
    );

// A low in4 must force out1 low.
    check_in4_low_forces_out1_low: assert property (
        @(posedge clk)
        !in4 |-> !out1
    );

// A low in5 must force out1 low.
    check_in5_low_forces_out1_low: assert property (
        @(posedge clk)
        !in5 |-> !out1
    );

// A low in6 must force out1 low.
    check_in6_low_forces_out1_low: assert property (
        @(posedge clk)
        !in6 |-> !out1
    );

// A low in7 must force out1 low.
    check_in7_low_forces_out1_low: assert property (
        @(posedge clk)
        !in7 |-> !out1
    );

// A low in8 must force out1 low.
    check_in8_low_forces_out1_low: assert property (
        @(posedge clk)
        !in8 |-> !out1
    );

// A low in9 must force out1 low.
    check_in9_low_forces_out1_low: assert property (
        @(posedge clk)
        !in9 |-> !out1
    );

// Reset forces the port addresses to their reset values.
    check_reset_values: assert property (
        @(posedge clk) !reset_b |-> (address_port_0 == 8'h00) &&
                                   (address_port_1 == 8'h01) &&
                                   (address_port_2 == 8'h02) &&
                                   (address_port_3 == 8'h03)
    );

// Read address 0 returns port 0 address.
    check_read_addr0: assert property (
        @(posedge clk) disable iff (!reset_b)
        (mem_addr == 2'd0) |-> (mem_rdata == address_port_0)
    );

// Read address 1 returns port 1 address.
    check_read_addr1: assert property (
        @(posedge clk) disable iff (!reset_b)
        (mem_addr == 2'd1) |-> (mem_rdata == address_port_1)
    );

// Read address 2 returns port 2 address.
    check_read_addr2: assert property (
        @(posedge clk) disable iff (!reset_b)
        (mem_addr == 2'd2) |-> (mem_rdata == address_port_2)
    );

// Read address 3 returns port 3 address.
    check_read_addr3: assert property (
        @(posedge clk) disable iff (!reset_b)
        (mem_addr == 2'd3) |-> (mem_rdata == address_port_3)
    );

// Write address 0 updates port 0 address on the next cycle.
    check_write_addr0: assert property (
        @(posedge clk) disable iff (!reset_b)
        (mem_en && mem_rd_wr && (mem_addr == 2'd0)) |=> (address_port_0 == $past(mem_wdata))
    );

// Write address 1 updates port 1 address on the next cycle.
    check_write_addr1: assert property (
        @(posedge clk) disable iff (!reset_b)
        (mem_en && mem_rd_wr && (mem_addr == 2'd1)) |=> (address_port_1 == $past(mem_wdata))
    );

// Write address 2 updates port 2 address on the next cycle.
    check_write_addr2: assert property (
        @(posedge clk) disable iff (!reset_b)
        (mem_en && mem_rd_wr && (mem_addr == 2'd2)) |=> (address_port_2 == $past(mem_wdata))
    );

// Write address 3 updates port 3 address on the next cycle.
    check_write_addr3: assert property (
        @(posedge clk) disable iff (!reset_b)
        (mem_en && mem_rd_wr && (mem_addr == 2'd3)) |=> (address_port_3 == $past(mem_wdata))
    );

// Without a write, port 0 address holds its value.
    check_hold_addr0: assert property (
        @(posedge clk) disable iff (!reset_b)
        !(mem_en && mem_rd_wr && (mem_addr == 2'd0)) |=> (address_port_0 == $past(address_port_0))
    );

// Without a write, port 1 address holds its value.
    check_hold_addr1: assert property (
        @(posedge clk) disable iff (!reset_b)
        !(mem_en && mem_rd_wr && (mem_addr == 2'd1)) |=> (address_port_1 == $past(address_port_1))
    );

// Without a write, port 2 address holds its value.
    check_hold_addr2: assert property (
        @(posedge clk) disable iff (!reset_b)
        !(mem_en && mem_rd_wr && (mem_addr == 2'd2)) |=> (address_port_2 == $past(address_port_2))
    );

// Without a write, port 3 address holds its value.
    check_hold_addr3: assert property (
        @(posedge clk) disable iff (!reset_b)
        !(mem_en && mem_rd_wr && (mem_addr == 2'd3)) |=> (address_port_3 == $past(address_port_3))
    );

// During reset, data_out must be 0.
    reset_clears_data_out: assert property (
        @(posedge clk) reset |-> (data_out == 8'h00)
    );

// When enable is LOW, data_out equals data_in on the next cycle.
    pass_through_when_disabled: assert property (
        @(posedge clk) disable iff (reset) (!enable) |=> (data_out == $past(data_in))
    );

// Clock: clk (posedge). Reset: rst (active-low, asynchronous). Logic: sequential counter with async reset.

    // While reset is asserted, count must be 0.
    check_reset_forces_zero: assert property (
        @(posedge clk) !rst |-> (count == 4'b0000)
    );

// On reset deassertion, count becomes 1 in the same cycle.
    check_reset_release_sets_one: assert property (
        @(posedge clk) $rose(rst) |-> (count == 4'b0001)
    );

// When not in reset, count increments by 1 each cycle (mod-16).
    check_count_increments: assert property (
        @(posedge clk) disable iff (!rst) 1'b1 |=> (count == $past(count) + 4'd1)
    );

// When not in reset, count never exceeds 15.
    check_count_bounded: assert property (
        @(posedge clk) disable iff (!rst) count <= 4'hF
    );

// When not in reset, count changes every cycle.
    check_count_changes_each_cycle: assert property (
        @(posedge clk) disable iff (!rst) 1'b1 |=> (count != $past(count))
    );

// When not in reset, 0xF wraps to 0 on the next cycle.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (!rst) (count == 4'hF) |=> (count == 4'h0)
    );

// On reset assertion, count is 0 in the same cycle.
    check_reset_assertion_clears: assert property (
        @(posedge clk) $fell(rst) |-> (count == 4'b0000)
    );

// On reset deassertion, count is 1 in the same cycle.
    check_reset_release_sets_one_now: assert property (
        @(posedge clk) $rose(rst) |-> (count == 4'b0001)
    );

// On reset deassertion, count is 1 in the next cycle.
    check_reset_release_increments_next: assert property (
        @(posedge clk) $rose(rst) |=> (count == 4'b0001)
    );

// When not in reset, count changes every cycle (no hold).
    check_no_hold_when_not_reset: assert property (
        @(posedge clk) disable iff (!rst) 1'b1 |=> (count != $past(count))
    );

// Y matches the implemented OR-NAND-BUF function.
    check_function_equivalence: assert property (
        @(posedge clk) Y == ~((A1 | A2) & B1 & C1)
    );

// B1 low forces the NAND output high.
    check_b1_low_forces_y_high: assert property (
        @(posedge clk) !B1 |-> Y
    );

// C1 low forces the NAND output high.
    check_c1_low_forces_y_high: assert property (
        @(posedge clk) !C1 |-> Y
    );

// Both A inputs low force the OR term low and Y high.
    check_a_inputs_low_force_y_high: assert property (
        @(posedge clk) (!A1 && !A2) |-> Y
    );

// B1 and C1 high with either A input high force Y low.
    check_active_inputs_force_y_low: assert property (
        @(posedge clk) (B1 && C1 && (A1 || A2)) |-> !Y
    );

// A low Y requires B1 and C1 high and the OR term high.
    check_y_low_requires_active_inputs: assert property (
        @(posedge clk) !Y |-> (B1 && C1 && (A1 || A2))
    );

// A high Y requires at least one NAND input low.
    check_y_high_requires_inactive_nand_input: assert property (
        @(posedge clk) Y |-> (!B1 || !C1 || (!A1 && !A2))
    );

// Reset forces the counter and carry low.
    check_reset_clears_state: assert property (
        @(posedge clk) rst |-> (q == 4'b0000) && (carry == 1'b0)
    );

// In up mode, a terminal count wraps and raises carry.
    check_up_wrap_and_carry: assert property (
        @(posedge clk) disable iff (rst)
        (up_down == 1'b0 && q == 4'b1111) |=> (q == 4'b0000) && (carry == 1'b1)
    );

// In up mode, a non-terminal count increments and clears carry.
    check_up_increment: assert property (
        @(posedge clk) disable iff (rst)
        (up_down == 1'b0 && q != 4'b1111) |=> (q == ($past(q) + 4'b0001)) && (carry == 1'b0)
    );

// In down mode, a terminal count wraps and raises carry.
    check_down_wrap_and_carry: assert property (
        @(posedge clk) disable iff (rst)
        (up_down == 1'b1 && q == 4'b0000) |=> (q == 4'b1111) && (carry == 1'b1)
    );

// In down mode, a non-terminal count decrements and clears carry.
    check_down_decrement: assert property (
        @(posedge clk) disable iff (rst)
        (up_down == 1'b1 && q != 4'b0000) |=> (q == ($past(q) - 4'b0001)) && (carry == 1'b0)
    );

// Reset forces count to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) !rst |-> (count == 4'b0000)
    );

// Reset has priority over load.
    check_reset_priority_over_load: assert property (
        @(posedge clk) (!rst && load) |-> (count == 4'b0000)
    );

// Load captures data into count.
    check_load_captures_data: assert property (
        @(posedge clk) disable iff (!rst) load |=> (count == $past(data))
    );

// Without load, count increments by one.
    check_increment_when_not_load: assert property (
        @(posedge clk) disable iff (!rst) !load |=> (count == ($past(count) + 4'b0001))
    );

// Count wraps from 15 back to 0.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (!rst) (!load && (count == 4'hF)) |=> (count == 4'h0)
    );

// For sector 1, flash_sector must be 000.
    map_sector1: assert property (
        @(posedge sector[0]) (sector == 3'd1) |-> (flash_sector == 3'b000)
    );

// For sector 2, flash_sector must be 001.
    map_sector2: assert property (
        @(posedge sector[0]) (sector == 3'd2) |-> (flash_sector == 3'b001)
    );

// For sector 3, flash_sector must be 010.
    map_sector3: assert property (
        @(posedge sector[0]) (sector == 3'd3) |-> (flash_sector == 3'b010)
    );

// For sector 4, flash_sector must be 011.
    map_sector4: assert property (
        @(posedge sector[0]) (sector == 3'd4) |-> (flash_sector == 3'b011)
    );

// For sector 5, flash_sector must be 100.
    map_sector5: assert property (
        @(posedge sector[0]) (sector == 3'd5) |-> (flash_sector == 3'b100)
    );

// For invalid sector IDs (6..7), flash_sector must be 000.
    map_invalid_zero: assert property (
        @(posedge sector[0]) (sector >= 3'd6) |-> (flash_sector == 3'b000)
    );

// flash_sector must never be 101, 110, or 111.
    check_no_reserved_values: assert property (
        @(posedge sector[0]) (flash_sector != 3'b101) && (flash_sector != 3'b110) && (flash_sector != 3'b111)
    );

// If flash_sector is 001, sector must be 2.
    reverse_map_sector2: assert property (
        @(posedge sector[0]) (flash_sector == 3'b001) |-> (sector == 3'd2)
    );

// If flash_sector is 010, sector must be 3.
    reverse_map_sector3: assert property (
        @(posedge sector[0]) (flash_sector == 3'b010) |-> (sector == 3'd3)
    );

// If flash_sector is 011, sector must be 4.
    reverse_map_sector4: assert property (
        @(posedge sector[0]) (flash_sector == 3'b011) |-> (sector == 3'd4)
    );

// If flash_sector is 100, sector must be 5.
    reverse_map_sector5: assert property (
        @(posedge sector[0]) (flash_sector == 3'b100) |-> (sector == 3'd5)
    );

// Clock: clk (posedge). Reset: rst_n active-low, asynchronous. Sequential 16-bit up-counter.

    // When reset is asserted, count must be 0 on the next cycle.
    reset_clears_next: assert property (
        @(posedge clk) !rst_n |=> (count == 16'h0000)
    );

// While reset is held low across cycles, count remains 0.
    hold_zero_while_reset: assert property (
        @(posedge clk) (!rst_n && $past(!rst_n)) |-> (count == 16'h0000)
    );

// If reset is held low for 16 cycles, count is 0 on the 16th cycle.
    hold_low_for_16_cycles: assert property (
        @(posedge clk) (!rst_n)[*16] |-> (count == 16'h0000)
    );

// If reset is held low for 17 cycles, count is still 0 on the 17th cycle.
    hold_low_for_17_cycles: assert property (
        @(posedge clk) (!rst_n)[*17] |-> (count == 16'h0000)
    );

// If reset is held low for 18 cycles, count is still 0 on the 18th cycle.
    hold_low_for_18_cycles: assert property (
        @(posedge clk) (!rst_n)[*18] |-> (count == 16'h0000)
    );

// Y matches the implemented NOT-NOR-AND function.
    check_functional_equivalence: assert property (
        @(posedge clk) Y == ~((~B1_N) | (A1 & A2))
    );

// A low B1_N forces the NOR output low.
    check_b1n_low_forces_y_low: assert property (
        @(posedge clk) !B1_N |-> !Y
    );

// High A1 and A2 force the AND term high and drive Y low.
    check_a1_a2_high_force_y_low: assert property (
        @(posedge clk) (A1 && A2) |-> !Y
    );

// With B1_N high and either A1 or A2 low, Y is high.
    check_b1n_high_and_any_a_low_force_y_high: assert property (
        @(posedge clk) (B1_N && (!A1 || !A2)) |-> Y
    );

// A high Y requires B1_N high and the AND term low.
    check_y_high_requires_b1n_high_and_and_term_low: assert property (
        @(posedge clk) Y |-> (B1_N && !(A1 && A2))
    );

// A low Y requires B1_N low or the AND term high.
    check_y_low_requires_b1n_low_or_and_term_high: assert property (
        @(posedge clk) !Y |-> (!B1_N || (A1 && A2))
    );

// Address 00000 loads 0010 on the next clock.
    check_addr_00000_loads_0010: assert property (
        @(posedge clk) disable iff (1'b0)
        (en && (addr == 5'b00000)) |=> (data == 4'b0010)
    );

// Address 00001 loads 0010 on the next clock.
    check_addr_00001_loads_0010: assert property (
        @(posedge clk) disable iff (1'b0)
        (en && (addr == 5'b00001)) |=> (data == 4'b0010)
    );

// Address 00010 loads 1110 on the next clock.
    check_addr_00010_loads_1110: assert property (
        @(posedge clk) disable iff (1'b0)
        (en && (addr == 5'b00010)) |=> (data == 4'b1110)
    );

// Address 00011 loads 0010 on the next clock.
    check_addr_00011_loads_0010: assert property (
        @(posedge clk) disable iff (1'b0)
        (en && (addr == 5'b00011)) |=> (data == 4'b0010)
    );

// Address 00100 loads 0100 on the next clock.
    check_addr_00100_loads_0100: assert property (
        @(posedge clk) disable iff (1'b0)
        (en && (addr == 5'b00100)) |=> (data == 4'b0100)
    );

// Address 00101 loads 1010 on the next clock.
    check_addr_00101_loads_1010: assert property (
        @(posedge clk) disable iff (1'b0)
        (en && (addr == 5'b00101)) |=> (data == 4'b1010)
    );

// Address 00110 loads 1100 on the next clock.
    check_addr_00110_loads_1100: assert property (
        @(posedge clk) disable iff (1'b0)
        (en && (addr == 5'b00110)) |=> (data == 4'b1100)
    );

// Address 00111 loads 0000 on the next clock.
    check_addr_00111_loads_0000: assert property (
        @(posedge clk) disable iff (1'b0)
        (en && (addr == 5'b00111)) |=> (data == 4'b0000)
    );

// Address 01000 loads 1010 on the next clock.
    check_addr_01000_loads_1010: assert property (
        @(posedge clk) disable iff (1'b0)
        (en && (addr == 5'b01000)) |=> (data == 4'b1010)
    );

// Address 01001 loads 0010 on the next clock.
    check_addr_01001_loads_0010: assert property (
        @(posedge clk) disable iff (1'b0)
        (en && (addr == 5'b01001)) |=> (data == 4'b0010)
    );

// Address 01010 loads 1110 on the next clock.
    check_addr_01010_loads_1110: assert property (
        @(posedge clk) disable iff (1'b0)
        (en && (addr == 5'b01010)) |=> (data == 4'b1110)
    );

// Address 01011 loads 0010 on the next clock.
    check_addr_01011_loads_0010: assert property (
        @(posedge clk) disable iff (1'b0)
        (en && (addr == 5'b01011)) |=> (data == 4'b0010)
    );

// Address 01100 loads 0100 on the next clock.
    check_addr_01100_loads_0100: assert property (
        @(posedge clk) disable iff (1'b0)
        (en && (addr == 5'b01100)) |=> (data == 4'b0100)
    );

// Address 01101 loads 1010 on the next clock.
    check_addr_01101_loads_1010: assert property (
        @(posedge clk) disable iff (1'b0)
        (en && (addr == 5'b01101)) |=> (data == 4'b1010)
    );

// Address 01110 loads 1100 on the next clock.
    check_addr_01110_loads_1100: assert property (
        @(posedge clk) disable iff (1'b0)
        (en && (addr == 5'b01110)) |=> (data == 4'b1100)
    );

// Address 01111 loads 0000 on the next clock.
    check_addr_01111_loads_0000: assert property (
        @(posedge clk) disable iff (1'b0)
        (en && (addr == 5'b01111)) |=> (data == 4'b0000)
    );

// With enable low, the register holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (1'b0)
        (!en) |=> (data == $past(data))
    );

// Reset clears the counter on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 32'd0)
    );

// Reset has priority over enable when both are asserted.
    check_reset_priority_over_enable: assert property (
        @(posedge clk) (rst && en) |=> (count == 32'd0)
    );

// Enable increments the counter by one when reset is low.
    check_enable_increments_count: assert property (
        @(posedge clk) disable iff (rst) en |=> (count == ($past(count) + 32'd1))
    );

// Disable holds the counter value when reset is low.
    check_disable_holds_count: assert property (
        @(posedge clk) disable iff (rst) !en |=> (count == $past(count))
    );

// The counter wraps from 32'hFFFF_FFFF to 32'h0000_0000 when enabled.
    check_count_wraps_on_max: assert property (
        @(posedge clk) disable iff (rst) (en && (count == 32'hFFFF_FFFF)) |=> (count == 32'h0000_0000)
    );

// Output must equal the bitwise AND of the two inputs.
    check_and_function: assert property (
        @(posedge clk) o_bus == (i_bus1 & i_bus2)
    );

// A zero on i_bus1 must force a zero on o_bus.
    check_zero_mask_i_bus1: assert property (
        @(posedge clk) (i_bus1 == 8'h00) |-> (o_bus == 8'h00)
    );

// A zero on i_bus2 must force a zero on o_bus.
    check_zero_mask_i_bus2: assert property (
        @(posedge clk) (i_bus2 == 8'h00) |-> (o_bus == 8'h00)
    );

// All ones on i_bus1 must pass i_bus2 through to o_bus.
    check_pass_through_i_bus1: assert property (
        @(posedge clk) (i_bus1 == 8'hFF) |-> (o_bus == i_bus2)
    );

// All ones on i_bus2 must pass i_bus1 through to o_bus.
    check_pass_through_i_bus2: assert property (
        @(posedge clk) (i_bus2 == 8'hFF) |-> (o_bus == i_bus1)
    );

// A non-zero output implies both inputs are non-zero.
    check_nonzero_output_implies_nonzero_inputs: assert property (
        @(posedge clk) (o_bus != 8'h00) |-> ((i_bus1 != 8'h00) && (i_bus2 != 8'h00))
    );

// Load captures data into q on the next cycle.
    check_load_captures_data: assert property (
        @(posedge clk) load |=> (q == $past(data))
    );

// With ena == 2'b00, q holds its value on the next cycle.
    check_hold_when_disabled: assert property (
        @(posedge clk) (!load && (ena == 2'b00)) |=> (q == $past(q))
    );

// out_if_else is high when q differs from data.
    check_out_if_else_high_when_mismatch: assert property (
        @(posedge clk) (q != data) |-> (out_if_else == 1'b1)
    );

// out_if_else is low when q matches data.
    check_out_if_else_low_when_match: assert property (
        @(posedge clk) (q == data) |-> (out_if_else == 1'b0)
    );

// X must equal the AND of A1&A2 and the inverse of B1&B2.
    check_x_function: assert property (
        @(posedge clk) X == ((A1 & A2) & ~(B1 & B2))
    );

// If both B inputs are high, X must be low.
    check_x_low_when_b_pair_high: assert property (
        @(posedge clk) (B1 & B2) |-> !X
    );

// If X is high, both A inputs must be high.
    check_x_implies_a_pair_high: assert property (
        @(posedge clk) X |-> (A1 & A2)
    );

// If X is high, both B inputs must be low.
    check_x_implies_b_pair_low: assert property (
        @(posedge clk) X |-> !(B1 & B2)
    );

// sel=00 routes a to o.
    check_sel_00_routes_a: assert property (
        @(posedge clk) (sel == 2'b00) |-> (o == a)
    );

// sel=01 routes b to o.
    check_sel_01_routes_b: assert property (
        @(posedge clk) (sel == 2'b01) |-> (o == b)
    );

// sel=10 routes c to o.
    check_sel_10_routes_c: assert property (
        @(posedge clk) (sel == 2'b10) |-> (o == c)
    );

// sel=11 routes d to o.
    check_sel_11_routes_d: assert property (
        @(posedge clk) (sel == 2'b11) |-> (o == d)
    );

// X matches the implemented OR-then-AND function.
    check_functional_equivalence: assert property (
        @(posedge clk) X == (B1 & (A1 | A2 | A3))
    );

// B1 low forces X low.
    check_b1_low_forces_x_low: assert property (
        @(posedge clk) !B1 |-> !X
    );

// All A inputs low force X low.
    check_all_a_low_forces_x_low: assert property (
        @(posedge clk) !(A1 | A2 | A3) |-> !X
    );

// With B1 high, any A input high drives X high.
    check_b1_and_any_a_high_drives_x_high: assert property (
        @(posedge clk) (B1 & (A1 | A2 | A3)) |-> X
    );

// X high requires B1 and at least one A input high.
    check_x_high_requires_b1_and_any_a: assert property (
        @(posedge clk) X |-> (B1 & (A1 | A2 | A3))
    );

// X high implies B1 is high.
    check_x_high_requires_b1: assert property (
        @(posedge clk) X |-> B1
    );

// X high implies at least one A input is high.
    check_x_high_requires_any_a: assert property (
        @(posedge clk) X |-> (A1 | A2 | A3)
    );

// Priority 0001 maps to 00.
    check_priority_0001_maps_to_00: assert property (
        @(posedge clk) disable iff (1'b0)
        (in == 4'b0001) |-> (out == 2'b00)
    );

// Output 00 can also come from the highest-priority input pattern 1110.
    check_out_00_from_priority_1110: assert property (
        @(posedge clk) disable iff (1'b0)
        (in == 4'b1110) |-> (out == 2'b00)
    );

// X must match the implemented AND/NOT function.
    check_iso_function: assert property (
        @(posedge clk) X == (A & ~SLEEP)
    );

// When SLEEP is high, X must be low.
    check_sleep_high_forces_x_low: assert property (
        @(posedge clk) SLEEP |-> !X
    );

// A low forces X low.
    check_a_low_forces_x_low: assert property (
        @(posedge clk) !A |-> !X
    );

// With SLEEP low and A high, X must be high.
    check_awake_and_a_high_sets_x: assert property (
        @(posedge clk) (!SLEEP && A) |-> X
    );

// With SLEEP low and A low, X must be low.
    check_awake_and_a_low_clears_x: assert property (
        @(posedge clk) (!SLEEP && !A) |-> !X
    );

// With SLEEP high and A high, X must be low.
    check_sleep_and_a_high_clears_x: assert property (
        @(posedge clk) (SLEEP && A) |-> !X
    );

// With SLEEP high and A low, X must be low.
    check_sleep_and_a_low_clears_x: assert property (
        @(posedge clk) (SLEEP && !A) |-> !X
    );

// Y must always match the mux equation.
    check_mux_equation: assert property (
        @(posedge clk) Y == (EN ? A : B)
    );

// When EN is high, Y must select A.
    check_select_a_when_en_high: assert property (
        @(posedge clk) EN |-> (Y == A)
    );

// When EN is low, Y must select B.
    check_select_b_when_en_low: assert property (
        @(posedge clk) !EN |-> (Y == B)
    );

// If both inputs are equal, Y must equal that common value.
    check_equal_inputs_passthrough: assert property (
        @(posedge clk) (A == B) |-> (Y == A)
    );

// X must equal the OR of the two AND terms.
    check_functional_equivalence: assert property (
        @(posedge clk) X == ((A1 & A2) | (B1 & B2))
    );

// If the A-side AND term is true, X must be high.
    check_a_term_drives_high: assert property (
        @(posedge clk) (A1 & A2) |-> X
    );

// If the B-side AND term is true, X must be high.
    check_b_term_drives_high: assert property (
        @(posedge clk) (B1 & B2) |-> X
    );

// If both AND terms are false, X must be low.
    check_no_terms_means_low: assert property (
        @(posedge clk) (!(A1 & A2) && !(B1 & B2)) |-> !X
    );

// If X is high, at least one AND term must be true.
    check_high_output_has_active_term: assert property (
        @(posedge clk) X |-> ((A1 & A2) || (B1 & B2))
    );

// If X is low, both AND terms must be false.
    check_low_output_has_no_active_term: assert property (
        @(posedge clk) !X |-> (!(A1 & A2) && !(B1 & B2))
    );

// With B-side inputs low, X reduces to the A-side AND term.
    check_b_side_low_reduces_to_a_term: assert property (
        @(posedge clk) (!B1 && !B2) |-> (X == (A1 & A2))
    );

// With A-side inputs low, X reduces to the B-side AND term.
    check_a_side_low_reduces_to_b_term: assert property (
        @(posedge clk) (!A1 && !A2) |-> (X == (B1 & B2))
    );

// With both A-side inputs high, X must be high.
    check_a_side_high_forces_high: assert property (
        @(posedge clk) (A1 && A2) |-> X
    );

// With both B-side inputs high, X must be high.
    check_b_side_high_forces_high: assert property (
        @(posedge clk) (B1 && B2) |-> X
    );

// out[0] is a direct copy of in[0].
    check_out0_passthrough: assert property (
        @(posedge clk) out[0] == in[0]
    );

// out[1] is the XOR of in[0] and in[1].
    check_out1_xor: assert property (
        @(posedge clk) out[1] == (in[0] ^ in[1])
    );

// out[2] is the XOR of in[1], in[2], and in[0].
    check_out2_xor_chain: assert property (
        @(posedge clk) out[2] == (in[1] ^ in[2] ^ in[0])
    );

// out[3] is the XOR of in[2], in[3], and in[1].
    check_out3_xor_chain: assert property (
        @(posedge clk) out[3] == (in[2] ^ in[3] ^ in[1])
    );

// The full output vector matches the implemented binary-to-Gray mapping.
    check_full_gray_mapping: assert property (
        @(posedge clk) out == {in[2] ^ in[3] ^ in[1], in[1] ^ in[2] ^ in[0], in[0] ^ in[1], in[0]}
    );

// Output must match the mux select expression.
    check_mux_function: assert property (
        @(posedge clk) out == ((sel == 1'b0) ? a : b)
    );

// When select is low, output must follow input a.
    check_select_low_routes_a: assert property (
        @(posedge clk) (sel == 1'b0) |-> (out == a)
    );

// When select is high, output must follow input b.
    check_select_high_routes_b: assert property (
        @(posedge clk) (sel == 1'b1) |-> (out == b)
    );

// If both inputs are equal, output must match that common value.
    check_equal_inputs_passthrough: assert property (
        @(posedge clk) (a == b) |-> (out == a)
    );

// Next-cycle out equals previous-cycle in (1-cycle latency).
    check_out_follows_prev_in: assert property (
        @(posedge clk) 1'b1 |-> ##1 (out == $past(in))
    );

// X must match the XOR of A1 and A2 gated by B1.
    check_x_matches_xor_gate: assert property (
        @(posedge clk) X == ((A1 ^ A2) & B1)
    );

// B1 low forces X low.
    check_b1_low_forces_x_low: assert property (
        @(posedge clk) !B1 |-> !X
    );

// With B1 high, X reduces to A1 XOR A2.
    check_b1_high_reduces_to_xor: assert property (
        @(posedge clk) B1 |-> (X == (A1 ^ A2))
    );

// Equal A inputs force X low.
    check_equal_a_inputs_force_x_low: assert property (
        @(posedge clk) !(A1 ^ A2) |-> !X
    );

// Different A inputs make X follow B1.
    check_different_a_inputs_follow_b1: assert property (
        @(posedge clk) (A1 ^ A2) |-> (X == B1)
    );

// X high requires B1 high and A1 different from A2.
    check_x_high_requires_b1_and_mismatch: assert property (
        @(posedge clk) X |-> (B1 && (A1 ^ A2))
    );

// X must match the implemented AND/NOT function.
    check_functional_equivalence: assert property (
        @(posedge clk) X == (SLEEP_B & A)
    );

// When sleep is asserted, X must be low.
    check_sleep_forces_low: assert property (
        @(posedge clk) !SLEEP_B |-> !X
    );

// When sleep is deasserted, X must follow A.
    check_awake_follows_a: assert property (
        @(posedge clk) SLEEP_B |-> (X == A)
    );

// A low forces X low regardless of sleep.
    check_a_low_forces_low: assert property (
        @(posedge clk) !A |-> !X
    );

// With sleep deasserted and A high, X must be high.
    check_awake_a_high_sets_x: assert property (
        @(posedge clk) (SLEEP_B & A) |-> X
    );

// Reset clears the accumulator output on the next clock.
    check_reset_clears_out: assert property (
        @(posedge clk) rst |=> (out == 8'h00)
    );

// With reset low, the accumulator output increments by data_in each cycle.
    check_accumulates_each_cycle: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |=> (out == ($past(out) + $past(data_in)))
    );

// A zero input leaves the accumulator output unchanged.
    check_zero_input_holds: assert property (
        @(posedge clk) disable iff (rst) (data_in == 8'h00) |=> (out == $past(out))
    );

// X must match the OR of the three 2-input AND terms.
    check_x_matches_or_of_ands: assert property (
        @(posedge clk) X == ((A1 & A2) | (B1 & B2) | (C1 & C2))
    );

// A high X must come from at least one asserted AND term.
    check_x_high_has_active_term: assert property (
        @(posedge clk) X |-> ((A1 & A2) | (B1 & B2) | (C1 & C2))
    );

// If A1 and A2 are high, X must be high.
    check_a_term_drives_x_high: assert property (
        @(posedge clk) (A1 & A2) |-> X
    );

// If B1 and B2 are high, X must be high.
    check_b_term_drives_x_high: assert property (
        @(posedge clk) (B1 & B2) |-> X
    );

// If C1 and C2 are high, X must be high.
    check_c_term_drives_x_high: assert property (
        @(posedge clk) (C1 & C2) |-> X
    );

// If X is low, all AND terms must be low.
    check_x_low_means_no_active_term: assert property (
        @(posedge clk) !X |-> !(A1 & A2 & B1 & B2 & C1 & C2)
    );

// Output is the bitwise inverse of the input.
    check_output_inverts_input: assert property (
        @(posedge clk) o == ~x
    );

// Carry flag is tied low.
    check_cfo_tied_low: assert property (
        @(posedge clk) cfo == 1'b0
    );

// Overflow flag is tied low.
    check_ofo_tied_low: assert property (
        @(posedge clk) ofo == 1'b0
    );

// Clock: CLK (posedge). Reset: reset (synchronous, active-high). Sequential counter with enable.

    // Reset drives count to zero on the next cycle.
    reset_clears_next: assert property (
        @(posedge CLK) reset |=> (count == 4'b0000)
    );

// When enabled and not in reset, count increments by 1 on the next cycle.
    increment_when_enabled: assert property (
        @(posedge CLK) disable iff (reset) enable |=> (count == $past(count) + 4'd1)
    );

// When not enabled and not in reset, count holds its value on the next cycle.
    hold_when_disabled: assert property (
        @(posedge CLK) disable iff (reset) !enable |=> (count == $past(count))
    );

// Reset clears the stored data and deasserts the output valid flag.
    check_reset_clears_outputs: assert property (
        @(posedge clk) reset |=> (out_data == 32'h0000_0000 && out_valid == 1'b0)
    );

// With valid input, the output reflects the prior input data and valid flag.
    check_valid_input_updates_output: assert property (
        @(posedge clk) disable iff (reset)
        in_valid |=> (out_data == $past(in_data) && out_valid == 1'b1)
    );

// Without valid input, the output valid flag is deasserted on the next cycle.
    check_no_valid_input_deasserts_valid: assert property (
        @(posedge clk) disable iff (reset)
        !in_valid |=> (out_valid == 1'b0)
    );

// Reset clears the shift register and output.
    check_reset_clears_state: assert property (
        @(posedge clk) rst |-> ((shiftreg == 64'b0) && (out == 1'b0))
    );

// Reset or xclear forces xout to zero on the next cycle.
    check_reset_or_xclear_clears_output: assert property (
        @(posedge clk) disable iff (reset)
        (xclear || reset) |=> (xout == '0)
    );

// With neither reset nor xclear and xload high, xout loads xin.
    check_load_when_enabled: assert property (
        @(posedge clk) disable iff (reset)
        !(xclear || reset) && xload |=> (xout == $past(xin))
    );

// With neither reset nor xclear and xload low, xout holds its value.
    check_hold_when_load_disabled: assert property (
        @(posedge clk) disable iff (reset)
        !(xclear || reset) && !xload |=> (xout == $past(xout))
    );

// Reset clears the registered output on the next clock.
    check_reset_clears_output: assert property (
        @(posedge CLK) RST |=> (C == 8'h00)
    );

// With reset low and OP high, the next output is A minus B.
    check_subtract_operation: assert property (
        @(posedge CLK) disable iff (RST) (OP == 1'b1) |=> (C == ($past(A) - $past(B)))
    );

// With reset low and OP low, the next output is A plus B.
    check_add_operation: assert property (
        @(posedge CLK) disable iff (RST) (OP == 1'b0) |=> (C == ($past(A) + $past(B)))
    );

// If reset stays asserted across consecutive clocks, the output remains zero.
    check_reset_holds_output_zero: assert property (
        @(posedge CLK) (RST && $past(RST)) |-> (C == 8'h00)
    );

// If reset deasserts and both operands are zero, the output becomes zero on the next clock.
    check_zero_operands_after_reset: assert property (
        @(posedge CLK) ($fell(RST) && (A == 8'h00) && (B == 8'h00)) |=> (C == 8'h00)
    );

// If reset deasserts and B is zero, the output becomes A on the next clock.
    check_passthrough_a_after_reset: assert property (
        @(posedge CLK) ($fell(RST) && (B == 8'h00)) |=> (C == $past(A))
    );

// out_sum must match the muxed input plus the selected position.
    check_out_sum_function: assert property (
        @(posedge clk)
        out_sum == ((sel_b1 & sel_b2) ? b :
                    ((sel_b1 | sel_b2) ? a : 1'b0)) + pos
    );

// With both select bits high, b is used and out_sum is b plus the position.
    check_b_selected: assert property (
        @(posedge clk)
        (sel_b1 & sel_b2) |-> (out_sum == b + pos)
    );

// With no input bits set, the position is zero and out_sum is the selected input plus zero.
    check_zero_input_case: assert property (
        @(posedge clk)
        (in == 8'h00) |-> (pos == 3'd0) && (out_sum == ((sel_b1 & sel_b2) ? b : ((sel_b1 | sel_b2) ? a : 1'b0)))
    );

// With only in[0] set, the position is zero and out_sum is the selected input plus zero.
    check_only_in0_case: assert property (
        @(posedge clk)
        (in == 8'h01) |-> (pos == 3'd0) && (out_sum == ((sel_b1 & sel_b2) ? b : ((sel_b1 | sel_b2) ? a : 1'b0)))
    );

// With only in[1] set, the position is one and out_sum is the selected input plus one.
    check_only_in1_case: assert property (
        @(posedge clk)
        (in == 8'h02) |-> (pos == 3'd1) && (out_sum == ((sel_b1 & sel_b2) ? b : ((sel_b1 | sel_b2) ? a : 1'b0)) + 1'b1)
    );

// With only in[2] set, the position is two and out_sum is the selected input plus two.
    check_only_in2_case: assert property (
        @(posedge clk)
        (in == 8'h04) |-> (pos == 3'd2) && (out_sum == ((sel_b1 & sel_b2) ? b : ((sel_b1 | sel_b2) ? a : 1'b0)) + 2'b10)
    );

// With only in[3] set, the position is three and out_sum is the selected input plus three.
    check_only_in3_case: assert property (
        @(posedge clk)
        (in == 8'h08) |-> (pos == 3'd3) && (out_sum == ((sel_b1 & sel_b2) ? b : ((sel_b1 | sel_b2) ? a : 1'b0)) + 2'b11)
    );

// With only in[4] set, the position is four and out_sum is the selected input plus four.
    check_only_in4_case: assert property (
        @(posedge clk)
        (in == 8'h10) |-> (pos == 3'd4) && (out_sum == ((sel_b1 & sel_b2) ? b : ((sel_b1 | sel_b2) ? a : 1'b0)) + 3'b100)
    );

// With only in[5] set, the position is five and out_sum is the selected input plus five.
    check_only_in5_case: assert property (
        @(posedge clk)
        (in == 8'h20) |-> (pos == 3'd5) && (out_sum == ((sel_b1 & sel_b2) ? b : ((sel_b1 | sel_b2) ? a : 1'b0)) + 3'b101)
    );

// With only in[6] set, the position is six and out_sum is the selected input plus six.
    check_only_in6_case: assert property (
        @(posedge clk)
        (in == 8'h40) |-> (pos == 3'd6) && (out_sum == ((sel_b1 & sel_b2) ? b : ((sel_b1 | sel_b2) ? a : 1'b0)) + 3'b110)
    );

// With only in[7] set, the position is seven and out_sum is the selected input plus seven.
    check_only_in7_case: assert property (
        @(posedge clk)
        (in == 8'h80) |-> (pos == 3'd7) && (out_sum == ((sel_b1 & sel_b2) ? b : ((sel_b1 | sel_b2) ? a : 1'b0)) + 3'b111)
    );

// Four consecutive shift-right cycles return the register to its original value.
    check_four_shift_right_cycles_return: assert property (
        @(posedge clk) (!load && shift_right)[*4] |=> (data_out == $past(data_out, 4))
    );

// y equals d0 OR d1 every cycle.
    check_y_equals_or: assert property (
        @(posedge clk) disable iff (clr) y == (d0 | d1)
    );

// If d0 is 1, y must be 1.
    check_y_high_when_d0_high: assert property (
        @(posedge clk) disable iff (clr) d0 |-> y
    );

// If d1 is 1, y must be 1.
    check_y_high_when_d1_high: assert property (
        @(posedge clk) disable iff (clr) d1 |-> y
    );

// If both d0 and d1 are 0, y must be 0.
    check_y_low_when_both_zero: assert property (
        @(posedge clk) disable iff (clr) (!d0 && !d1) |-> !y
    );

// If y is 0, both d0 and d1 must be 0.
    check_y_zero_implies_inputs_zero: assert property (
        @(posedge clk) disable iff (clr) !y |-> (!d0 && !d1)
    );

// If y is 1, at least one of d0 or d1 must be 1.
    check_y_one_implies_some_input_one: assert property (
        @(posedge clk) disable iff (clr) y |-> (d0 || d1)
    );

// Y matches the implemented NOR-of-ANDs function.
    check_y_matches_nor_of_ands: assert property (
        @(posedge clk) Y == ~((B1 & B2) | C1 | (A1 & A2))
    );

// C1 high forces the NOR output low.
    check_c1_forces_y_low: assert property (
        @(posedge clk) C1 |-> !Y
    );

// Both B inputs high force the NOR output low.
    check_b_pair_forces_y_low: assert property (
        @(posedge clk) (B1 & B2) |-> !Y
    );

// Both A inputs high force the NOR output low.
    check_a_pair_forces_y_low: assert property (
        @(posedge clk) (A1 & A2) |-> !Y
    );

// With no active NOR input term, Y is high.
    check_no_active_term_drives_y_high: assert property (
        @(posedge clk) (!C1 && !(B1 & B2) && !(A1 & A2)) |-> Y
    );

// A high Y means no NOR input term is active.
    check_y_high_means_no_active_term: assert property (
        @(posedge clk) Y |-> (!C1 && !(B1 & B2) && !(A1 & A2))
    );

// A low Y means at least one NOR input term is active.
    check_y_low_means_some_active_term: assert property (
        @(posedge clk) !Y |-> (C1 || (B1 & B2) || (A1 & A2))
    );

// Reset drives count and overflow low on the next cycle.
    reset_clears_next: assert property (
        @(posedge clk) reset |=> (count == 4'b0000) && (overflow == 1'b0)
    );

// When enabled and not at max, count increments by 1 and overflow stays 0.
    inc_when_enabled_not_max: assert property (
        @(posedge clk) disable iff (reset)
            (enable && (count != 4'hF)) |=> (count == $past(count) + 4'd1) && (overflow == 1'b0)
    );

// When enabled and at max, count wraps to 0 and overflow sets.
    wrap_when_enabled_at_max: assert property (
        @(posedge clk) disable iff (reset)
            (enable && (count == 4'hF)) |=> (count == 4'h0) && (overflow == 1'b1)
    );

// Reset clears the counter on the next clock.
    check_reset_clears_counter: assert property (
        @(posedge clk) reset |=> (counter == 64'b0)
    );

// Reset clears the output on the next clock.
    check_reset_clears_output: assert property (
        @(posedge clk) reset |=> (output_val == 64'b0)
    );

// The output bits are either 0 or the corresponding input bit.
    check_output_subset_of_input: assert property (
        @(posedge clk) disable iff (reset)
        ((output_val & ~{64{input_val}}) == 64'b0)
    );

// A zero input forces the output low.
    check_zero_input_forces_zero_output: assert property (
        @(posedge clk) disable iff (reset)
        (input_val == 8'h00) |-> (output_val == 64'b0)
    );

// Reset clears the counter and drives the default output value.
    check_reset_clears_counter_and_value: assert property (
        @(posedge clk) rst |=> (ctr_q == '0) && (value == 8'h00)
    );

// Q_N is always the inverse of Q.
    check_qn_complement: assert property (
        @(posedge CLK) Q_N == ~Q
    );

// When SCE is high, the next-cycle output reflects SCD.
    check_select_scd: assert property (
        @(posedge CLK) SCE |=> (Q == $past(SCD)) && (Q_N == ~$past(SCD))
    );

// When SCE is low, the next-cycle output reflects D.
    check_select_d: assert property (
        @(posedge CLK) !SCE |=> (Q == $past(D)) && (Q_N == ~$past(D))
    );

// X must match the implemented OR-then-AND function.
    check_x_matches_function: assert property (
        @(posedge clk) X == (B1 & C1 & D1 & (A1 | A2))
    );

// B1 low forces X low.
    check_b1_low_forces_x_low: assert property (
        @(posedge clk) !B1 |-> !X
    );

// C1 low forces X low.
    check_c1_low_forces_x_low: assert property (
        @(posedge clk) !C1 |-> !X
    );

// D1 low forces X low.
    check_d1_low_forces_x_low: assert property (
        @(posedge clk) !D1 |-> !X
    );

// Both A inputs low force X low.
    check_a_inputs_low_force_x_low: assert property (
        @(posedge clk) !(A1 | A2) |-> !X
    );

// With all required terms high, X must be high.
    check_all_terms_high_drive_x_high: assert property (
        @(posedge clk) (B1 & C1 & D1 & (A1 | A2)) |-> X
    );

// X high requires B1, C1, and D1 high.
    check_x_high_requires_required_terms: assert property (
        @(posedge clk) X |-> (B1 & C1 & D1)
    );

// X high requires at least one A input high.
    check_x_high_requires_a_term: assert property (
        @(posedge clk) X |-> (A1 | A2)
    );

// Up mode increments from 0 to 7.
    check_up_mode_increment: assert property (
        @(posedge clk) (up_down == 1'b0 && q == 3'd0) |=> (q == 3'd1)
    );

// Up mode increments from 1 to 7.
    check_up_mode_increment_mid: assert property (
        @(posedge clk) (up_down == 1'b0 && q == 3'd1) |=> (q == 3'd2)
    );

// Up mode wraps from 7 back to 0.
    check_up_mode_wrap: assert property (
        @(posedge clk) (up_down == 1'b0 && q == 3'd7) |=> (q == 3'd0)
    );

// Down mode decrements from 7 to 0.
    check_down_mode_decrement: assert property (
        @(posedge clk) (up_down == 1'b1 && q == 3'd7) |=> (q == 3'd6)
    );

// Down mode decrements from 1 to 0.
    check_down_mode_decrement_mid: assert property (
        @(posedge clk) (up_down == 1'b1 && q == 3'd1) |=> (q == 3'd0)
    );

// Down mode wraps from 0 back to 7.
    check_down_mode_wrap: assert property (
        @(posedge clk) (up_down == 1'b1 && q == 3'd0) |=> (q == 3'd7)
    );

// Full 33-bit result matches a + b + cin.
    check_full_addition: assert property (
        @(posedge clk) {cout, sum} == ({1'b0, a} + {1'b0, b} + cin)
    );

// Bit 0 sum matches the first full-adder XOR.
    check_sum_bit0: assert property (
        @(posedge clk) sum[0] == (a[0] ^ b[0] ^ cin)
    );

// Bit 1 sum uses the carry generated by bit 0.
    check_sum_bit1: assert property (
        @(posedge clk) sum[1] == (a[1] ^ b[1] ^ ((a[0] & b[0]) | (a[0] & cin) | (b[0] & cin)))
    );

// Bit 2 sum uses the ripple carry from bits 0 and 1.
    check_sum_bit2: assert property (
        @(posedge clk) sum[2] == (a[2] ^ b[2] ^
            (
                (a[1] & b[1]) |
                (a[1] & ((a[0] & b[0]) | (a[0] & cin) | (b[0] & cin))) |
                (b[1] & ((a[0] & b[0]) | (a[0] & cin) | (b[0] & cin)))
            )
        )
    );

// Y matches the implemented NAND/OR/BUF function.
    check_function_equivalence: assert property (
        @(posedge clk) Y == (A_N | B_N | ~(C & D))
    );

// A_N high forces the OR output high.
    check_a_n_high_forces_y_high: assert property (
        @(posedge clk) A_N |-> Y
    );

// B_N high forces the OR output high.
    check_b_n_high_forces_y_high: assert property (
        @(posedge clk) B_N |-> Y
    );

// C low forces the NAND output low, so Y must be high.
    check_c_low_forces_y_high: assert property (
        @(posedge clk) !C |-> Y
    );

// D low forces the NAND output low, so Y must be high.
    check_d_low_forces_y_high: assert property (
        @(posedge clk) !D |-> Y
    );

// With all active terms low, Y must be low.
    check_all_active_terms_low_forces_y_low: assert property (
        @(posedge clk) (!A_N && !B_N && C && D) |-> !Y
    );

// A low Y requires all active terms to be low.
    check_y_low_requires_all_active_terms_low: assert property (
        @(posedge clk) !Y |-> (!A_N && !B_N && C && D)
    );

// With both active inputs low, Y reduces to the NAND of C and D.
    check_reduced_nand_behavior: assert property (
        @(posedge clk) (!A_N && !B_N) |-> (Y == ~(C & D))
    );

// Q must match the selected add or subtract operation.
    check_q_matches_selected_operation: assert property (
        @(posedge clk) Q == (C ? (A - B) : (A + B))
    );

// When C is low, Q must be the 16-bit sum of A and B.
    check_add_mode_result: assert property (
        @(posedge clk) !C |-> (Q == (A + B))
    );

// When C is high, Q must be the 16-bit difference of A and B.
    check_sub_mode_result: assert property (
        @(posedge clk) C |-> (Q == (A - B))
    );

// Y matches the implemented NOT-AND-NOR function.
    check_y_function: assert property (
        @(posedge clk) Y == ~((~B1_N) | (A1 & A2))
    );

// A low B1_N forces the NOR output low.
    check_b1n_low_forces_y_low: assert property (
        @(posedge clk) !B1_N |-> !Y
    );

// High A1 and A2 force the AND term high and drive Y low.
    check_a1_a2_high_force_y_low: assert property (
        @(posedge clk) (A1 && A2) |-> !Y
    );

// With B1_N high and either A1 or A2 low, Y is high.
    check_b1n_high_and_any_a_low_force_y_high: assert property (
        @(posedge clk) (B1_N && (!A1 || !A2)) |-> Y
    );

// A high Y requires B1_N high and the AND term low.
    check_y_high_requires_b1n_and_and_term_low: assert property (
        @(posedge clk) Y |-> (B1_N && !(A1 && A2))
    );

// A low Y requires B1_N low or the AND term high.
    check_y_low_requires_b1n_low_or_and_term_high: assert property (
        @(posedge clk) !Y |-> (!B1_N || (A1 && A2))
    );

// Y must equal the AND of all five inputs.
    check_y_matches_and_function: assert property (
        @(posedge clk) Y == (A1 & A2 & B1 & C1 & D1)
    );

// All inputs high must drive Y high.
    check_all_inputs_high_drive_y_high: assert property (
        @(posedge clk) (A1 & A2 & B1 & C1 & D1) |-> Y
    );

// A low A1 input must force Y low.
    check_a1_low_forces_y_low: assert property (
        @(posedge clk) !A1 |-> !Y
    );

// A low A2 input must force Y low.
    check_a2_low_forces_y_low: assert property (
        @(posedge clk) !A2 |-> !Y
    );

// A low B1 input must force Y low.
    check_b1_low_forces_y_low: assert property (
        @(posedge clk) !B1 |-> !Y
    );

// A low C1 input must force Y low.
    check_c1_low_forces_y_low: assert property (
        @(posedge clk) !C1 |-> !Y
    );

// A low D1 input must force Y low.
    check_d1_low_forces_y_low: assert property (
        @(posedge clk) !D1 |-> !Y
    );

// A high Y requires all inputs to be high.
    check_y_high_requires_all_inputs_high: assert property (
        @(posedge clk) Y |-> (A1 & A2 & B1 & C1 & D1)
    );

// X must match the implemented AND/OR function.
    check_x_matches_a22o_function: assert property (
        @(posedge clk) X == ((A1 & A2) | (B1 & B2))
    );

// A1 and A2 high must force X high.
    check_a_term_forces_x_high: assert property (
        @(posedge clk) (A1 & A2) |-> X
    );

// B1 and B2 high must force X high.
    check_b_term_forces_x_high: assert property (
        @(posedge clk) (B1 & B2) |-> X
    );

// If neither AND term is true, X must be low.
    check_no_active_term_forces_x_low: assert property (
        @(posedge clk) (!(A1 & A2) && !(B1 & B2)) |-> !X
    );

// X high must come from at least one active AND term.
    check_x_high_has_active_term: assert property (
        @(posedge clk) X |-> ((A1 & A2) || (B1 & B2))
    );

// X low means both AND terms are inactive.
    check_x_low_means_no_active_term: assert property (
        @(posedge clk) !X |-> (!(A1 & A2) && !(B1 & B2))
    );

// When both selects are high, out must equal d3.
    check_select_11_routes_d3: assert property (
        @(posedge clk) (sel1 && sel2) |-> (out == d3)
    );

// When select 1 is high and select 2 is low, out must equal d2.
    check_select_10_routes_d2: assert property (
        @(posedge clk) (sel1 && !sel2) |-> (out == d2)
    );

// When select 1 is low and select 2 is high, out must equal d1.
    check_select_01_routes_d1: assert property (
        @(posedge clk) (!sel1 && sel2) |-> (out == d1)
    );

// When both selects are low, out must equal d0.
    check_select_00_routes_d0: assert property (
        @(posedge clk) (!sel1 && !sel2) |-> (out == d0)
    );

// With select 1 low, out must come from the d1/d0 branch.
    check_select_0x_routes_d1_or_d0: assert property (
        @(posedge clk) !sel1 |-> (out == (sel2 ? d1 : d0))
    );

// With select 2 high, out must come from the d3/d1 branch.
    check_select_x1_routes_d3_or_d1: assert property (
        @(posedge clk) sel2 |-> (out == (sel1 ? d3 : d1))
    );

// With select 2 low, out must come from the d2/d0 branch.
    check_select_x0_routes_d2_or_d0: assert property (
        @(posedge clk) !sel2 |-> (out == (sel1 ? d2 : d0))
    );

// q reflects the d input selected on the previous falling edge.
    check_q_matches_selected_input: assert property (
        @(negedge clk) 1'b1 |=> (q == $past(sel ? d2 : d1))
    );

// A low sel selects d1 on the next falling edge.
    check_sel_low_selects_d1: assert property (
        @(negedge clk) !sel |=> (q == $past(d1))
    );

// A high sel selects d2 on the next falling edge.
    check_sel_high_selects_d2: assert property (
        @(negedge clk) sel |=> (q == $past(d2))
    );

// With stable d1 and d2, a low sel holds q at the next falling edge.
    check_stable_d1_keeps_q_when_sel_low: assert property (
        @(negedge clk) (!sel && $stable(d1) && $stable(d2)) |=> (q == $past(d1))
    );

// With stable d1 and d2, a high sel holds q at the next falling edge.
    check_stable_d2_keeps_q_when_sel_high: assert property (
        @(negedge clk) (sel && $stable(d1) && $stable(d2)) |=> (q == $past(d2))
    );

// Reset drives dout to zero on the next cycle.
    reset_clears_dout_next: assert property (
        @(posedge clk) reset |=> (dout == 32'd0)
    );

// With ce low, dout holds its value on the next cycle.
    hold_when_ce_low: assert property (
        @(posedge clk) disable iff (reset) !ce |=> (dout == $past(dout))
    );

// If reset and ce are both high, reset has priority and dout becomes zero next cycle.
    reset_overrides_ce: assert property (
        @(posedge clk) (reset && ce) |=> (dout == 32'd0)
    );

// sel=00 routes in0 to out.
    check_sel_00_routes_in0: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == in0)
    );

// sel=01 routes in1 to out.
    check_sel_01_routes_in1: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out == in1)
    );

// sel=10 routes in2 to out.
    check_sel_10_routes_in2: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out == in2)
    );

// sel=11 routes in3 to out.
    check_sel_11_routes_in3: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == in3)
    );

// and_res must equal the bitwise AND of A and B.
    check_and_result: assert property (
        @(posedge clk) and_res == (A & B)
    );

// or_res must equal the bitwise OR of A and B.
    check_or_result: assert property (
        @(posedge clk) or_res == (A | B)
    );

// xor_res must equal the bitwise XOR of A and B.
    check_xor_result: assert property (
        @(posedge clk) xor_res == (A ^ B)
    );

// not_res must equal the bitwise NOT of A.
    check_not_result: assert property (
        @(posedge clk) not_res == (~A)
    );

// Y matches the implemented NOR-AND function.
    check_function_equivalence: assert property (
        @(posedge clk) Y == (C_N & ~(A | B))
    );

// A high forces the NOR output low, so Y must be low.
    check_a_high_forces_y_low: assert property (
        @(posedge clk) A |-> !Y
    );

// B high forces the NOR output low, so Y must be low.
    check_b_high_forces_y_low: assert property (
        @(posedge clk) B |-> !Y
    );

// C_N low forces the AND output low, so Y must be low.
    check_c_n_low_forces_y_low: assert property (
        @(posedge clk) !C_N |-> !Y
    );

// With all active inputs low, Y must be high.
    check_all_inputs_inactive_drive_y_high: assert property (
        @(posedge clk) (!A && !B && C_N) |-> Y
    );

// Y high requires C_N to be high and both NOR inputs to be low.
    check_y_high_requires_active_c_n_and_inactive_nor_inputs: assert property (
        @(posedge clk) Y |-> (C_N && !A && !B)
    );

// Reset clears q when scan mode is inactive.
    check_reset_clears_q: assert property (
        @(posedge clk) disable iff (rst)
        (!se && rst) |=> (q == {SIZE{1'b0}})
    );

// Reset clears so when scan mode is inactive.
    check_reset_clears_so: assert property (
        @(posedge clk) disable iff (rst)
        (!se && rst) |=> (so == {SIZE{1'b0}})
    );

// No RTL clock or reset; clk is an external sampling clock.

    // When A is greater than B, result is A shifted left by shift_amount.
    check_a_greater_b_shifts_a: assert property (
        @(posedge clk) (A > B) |-> (result == (A << shift_amount))
    );

// When A is less than B, result is B shifted right by shift_amount.
    check_a_less_b_shifts_b: assert property (
        @(posedge clk) (A < B) |-> (result == (B >> shift_amount))
    );

// When A equals B, result passes through A.
    check_equal_inputs_pass_a: assert property (
        @(posedge clk) (A == B) |-> (result == A)
    );

// A zero shift amount leaves the selected input unchanged.
    check_zero_shift_passthrough: assert property (
        @(posedge clk) (shift_amount == 4'd0) |-> (result == (A > B ? A : B))
    );

// A zero shift amount with equal inputs passes through A.
    check_zero_shift_equal_inputs_pass_a: assert property (
        @(posedge clk) ((shift_amount == 4'd0) && (A == B)) |-> (result == A)
    );

// A zero shift amount with A greater than B passes through A.
    check_zero_shift_a_greater_b_pass_a: assert property (
        @(posedge clk) ((shift_amount == 4'd0) && (A > B)) |-> (result == A)
    );

// A zero shift amount with A less than B passes through B.
    check_zero_shift_a_less_b_pass_b: assert property (
        @(posedge clk) ((shift_amount == 4'd0) && (A < B)) |-> (result == B)
    );

// A zero shift amount with A greater than B and equal MSBs returns A.
    check_zero_shift_a_greater_b_equal_msb_pass_a: assert property (
        @(posedge clk) ((shift_amount == 4'd0) && (A > B) && (A[15] == B[15])) |-> (result == A)
    );

// A zero shift amount with A less than B and equal MSBs returns B.
    check_zero_shift_a_less_b_equal_msb_pass_b: assert property (
        @(posedge clk) ((shift_amount == 4'd0) && (A < B) && (A[15] == B[15])) |-> (result == B)
    );

// A zero shift amount with A less than B and different MSBs returns B.
    check_zero_shift_a_less_b_different_msb_pass_b: assert property (
        @(posedge clk) ((shift_amount == 4'd0) && (A < B) && (A[15] != B[15])) |-> (result == B)
    );

// If B1 is greater than B2 and greater than current Y, Y must equal B1.
    check_y_equals_b1_when_b1_gt_b2_and_gt_y: assert property (
        @(posedge B1[0]) ((B1 > B2) && (B1 > Y)) |-> (Y == B1)
    );

// If B2 is greater than current Y, Y must equal B2.
    check_y_equals_b2_when_b2_gt_y: assert property (
        @(posedge B1[0]) (B2 > Y) |-> (Y == B2)
    );

// If C1 is greater than C2 and greater than current Y, Y must equal C1.
    check_y_equals_c1_when_c1_gt_c2_and_gt_y: assert property (
        @(posedge C1[0]) ((C1 > C2) && (C1 > Y)) |-> (Y == C1)
    );

// If C2 is greater than current Y, Y must equal C2.
    check_y_equals_c2_when_c2_gt_y: assert property (
        @(posedge C1[0]) (C2 > Y) |-> (Y == C2)
    );

// If D1 is greater than D2 and greater than current Y, Y must equal D1.
    check_y_equals_d1_when_d1_gt_d2_and_gt_y: assert property (
        @(posedge D1[0]) ((D1 > D2) && (D1 > Y)) |-> (Y == D1)
    );

// If D2 is greater than current Y, Y must equal D2.
    check_y_equals_d2_when_d2_gt_y: assert property (
        @(posedge D1[0]) (D2 > Y) |-> (Y == D2)
    );

// If A1 is greater than A2 and B1/B2/C1/C2/D1/D2 are all <= A1, Y equals A1.
    check_y_equals_a1_when_a1_max_and_others_le: assert property (
        @(posedge A1[0]) ((A1 > A2) && (A1 >= B1) && (A1 >= B2) && (A1 >= C1) && (A1 >= C2) && (A1 >= D1) && (A1 >= D2)) |-> (Y == A1)
    );

// If A2 is greater than A1 and B1/B2/C1/C2/D1/D2 are all <= A2, Y equals A2.
    check_y_equals_a2_when_a2_max_and_others_le: assert property (
        @(posedge A1[0]) ((!(A1 > A2)) && (A2 >= B1) && (A2 >= B2) && (A2 >= C1) && (A2 >= C2) && (A2 >= D1) && (A2 >= D2)) |-> (Y == A2)
    );

// Y matches the implemented NOR-of-ANDs function.
    check_y_matches_nor_of_ands: assert property (
        @(posedge clk) Y == ~((B1 & B2) | C1 | (A1 & A2))
    );

// C1 high forces the NOR output low.
    check_c1_forces_y_low: assert property (
        @(posedge clk) C1 |-> !Y
    );

// Both B inputs high force the NOR output low.
    check_b_pair_forces_y_low: assert property (
        @(posedge clk) (B1 & B2) |-> !Y
    );

// Both A inputs high force the NOR output low.
    check_a_pair_forces_y_low: assert property (
        @(posedge clk) (A1 & A2) |-> !Y
    );

// With no active NOR input term, Y is high.
    check_no_active_term_drives_y_high: assert property (
        @(posedge clk) (!C1 && !(B1 & B2) && !(A1 & A2)) |-> Y
    );

// A high Y means no NOR input term is active.
    check_y_high_means_no_active_term: assert property (
        @(posedge clk) Y |-> (!C1 && !(B1 & B2) && !(A1 & A2))
    );

// A low Y means at least one NOR input term is active.
    check_y_low_means_some_active_term: assert property (
        @(posedge clk) !Y |-> (C1 || (B1 & B2) || (A1 & A2))
    );

// X must match the implemented AND-of-nots equation.
    check_x_matches_function: assert property (
        @(posedge clk) X == (A1 & ~A2 & ~A3 & ~B1 & ~B2 & ~VPWR & ~VGND & ~VPB & ~VNB)
    );

// A high X requires all active-low terms to be true.
    check_x_high_requires_all_terms: assert property (
        @(posedge clk) X |-> (A1 & ~A2 & ~A3 & ~B1 & ~B2 & ~VPWR & ~VGND & ~VPB & ~VNB)
    );

// A1 low forces X low.
    check_a1_low_forces_x_low: assert property (
        @(posedge clk) !A1 |-> !X
    );

// A2 high forces X low.
    check_a2_high_forces_x_low: assert property (
        @(posedge clk) A2 |-> !X
    );

// A3 high forces X low.
    check_a3_high_forces_x_low: assert property (
        @(posedge clk) A3 |-> !X
    );

// B1 high forces X low.
    check_b1_high_forces_x_low: assert property (
        @(posedge clk) B1 |-> !X
    );

// B2 high forces X low.
    check_b2_high_forces_x_low: assert property (
        @(posedge clk) B2 |-> !X
    );

// VPWR high forces X low.
    check_vpwr_high_forces_x_low: assert property (
        @(posedge clk) VPWR |-> !X
    );

// VGND high forces X low.
    check_vgnd_high_forces_x_low: assert property (
        @(posedge clk) VGND |-> !X
    );

// VPB high forces X low.
    check_vpb_high_forces_x_low: assert property (
        @(posedge clk) VPB |-> !X
    );

// VNB high forces X low.
    check_vnb_high_forces_x_low: assert property (
        @(posedge clk) VNB |-> !X
    );

// Output must match the mux select expression.
    check_mux_function: assert property (
        @(posedge clk) out == ((sel == 1'b0) ? a : b)
    );

// When select is low, output must follow input a.
    check_select_low_routes_a: assert property (
        @(posedge clk) (sel == 1'b0) |-> (out == a)
    );

// When select is high, output must follow input b.
    check_select_high_routes_b: assert property (
        @(posedge clk) (sel == 1'b1) |-> (out == b)
    );

// If both inputs are equal, output must equal that common value.
    check_equal_inputs_passthrough: assert property (
        @(posedge clk) (a == b) |-> (out == a)
    );

// twos_comp equals bitwise NOT of binary plus 1.
    check_twos_comp_def: assert property (
        @(posedge binary[0]) twos_comp == (~binary + 4'b0001)
    );

// twos_comp + binary equals 4'b0000 (mod 16).
    check_additive_inverse: assert property (
        @(posedge binary[0]) (twos_comp + binary) == 4'b0000
    );

// twos_comp equals ~binary + 1 (bitwise form).
    check_bitwise_form: assert property (
        @(posedge binary[0]) twos_comp == (~binary + 4'b0001)
    );

// twos_comp equals ~binary + 1 (arithmetic form).
    check_arithmetic_form: assert property (
        @(posedge binary[0]) twos_comp == (~binary + 4'b0001)
    );

// twos_comp equals ~binary + 1 (arithmetic form).
    check_arithmetic_form_2: assert property (
        @(posedge binary[0]) twos_comp == (~binary + 4'b0001)
    );

// twos_comp equals ~binary + 1 (arithmetic form).
    check_arithmetic_form_3: assert property (
        @(posedge binary[0]) twos_comp == (~binary + 4'b0001)
    );

// twos_comp equals ~binary + 1 (arithmetic form).
    check_arithmetic_form_4: assert property (
        @(posedge binary[0]) twos_comp == (~binary + 4'b0001)
    );

// twos_comp equals ~binary + 1 (arithmetic form).
    check_arithmetic_form_5: assert property (
        @(posedge binary[0]) twos_comp == (~binary + 4'b0001)
    );

// twos_comp equals ~binary + 1 (arithmetic form).
    check_arithmetic_form_6: assert property (
        @(posedge binary[0]) twos_comp == (~binary + 4'b0001)
    );

// With both nibbles at zero, the upper output byte is zero.
    check_out_hi_zero_when_upper_select_zero: assert property (
        @(posedge clk) (in[15:14] == 2'b00) |-> (out_hi == 8'h00)
    );

// With both nibbles at one, the upper output byte is zero.
    check_out_hi_zero_when_upper_select_one: assert property (
        @(posedge clk) (in[15:14] == 2'b11) |-> (out_hi == 8'h00)
    );

// X must equal the AND of all four inputs.
    check_x_matches_and: assert property (
        @(posedge clk) X == (A_N & B_N & C & D)
    );

// All inputs high must drive X high.
    check_all_inputs_high_drive_x_high: assert property (
        @(posedge clk) (A_N && B_N && C && D) |-> X
    );

// A_N low must force X low.
    check_a_n_low_forces_x_low: assert property (
        @(posedge clk) !A_N |-> !X
    );

// B_N low must force X low.
    check_b_n_low_forces_x_low: assert property (
        @(posedge clk) !B_N |-> !X
    );

// C low must force X low.
    check_c_low_forces_x_low: assert property (
        @(posedge clk) !C |-> !X
    );

// D low must force X low.
    check_d_low_forces_x_low: assert property (
        @(posedge clk) !D |-> !X
    );

// X high requires all inputs high.
    check_x_high_requires_all_inputs_high: assert property (
        @(posedge clk) X |-> (A_N && B_N && C && D)
    );

// The high 16 bits of sum must equal the high 16 bits of a plus b.
    check_upper_half_addition: assert property (
        @(posedge clk) sum[31:16] == (a[31:16] + b[31:16])
    );

// All-ones plus all-ones must produce 0xFFFF_FFFE.
    check_all_ones_plus_all_ones: assert property (
        @(posedge clk) ((a == 32'hFFFF_FFFF) && (b == 32'hFFFF_FFFF)) |-> (sum == 32'hFFFF_FFFE)
    );

// Adding 1 to 0xFFFF_FFFF must wrap to 0xFFFF_FFFE.
    check_overflow_case: assert property (
        @(posedge clk) ((a == 32'hFFFF_FFFF) && (b == 32'h0000_0001)) |-> (sum == 32'hFFFF_FFFE)
    );

// Reset forces the registered result to zero.
    check_reset_clears_result: assert property (
        @(posedge clk) !reset |-> (result == 4'b0000)
    );

// In add mode, the next result is the previous cycle's A+B.
    check_add_mode_updates_result: assert property (
        @(posedge clk) disable iff (!reset)
        (operation == 1'b0) |=> (result == (($past(A) + $past(B)) & 4'hF))
    );

// In subtract mode, the next result is the previous cycle's A-B.
    check_sub_mode_updates_result: assert property (
        @(posedge clk) disable iff (!reset)
        (operation == 1'b1) |=> (result == (($past(A) - $past(B)) & 4'hF))
    );

// With stable inputs and operation, the result holds its value.
    check_result_stable_when_inputs_stable: assert property (
        @(posedge clk) disable iff (!reset)
        ($stable(operation) && $stable(A) && $stable(B)) |=> (result == $past(result))
    );

// Reset clears the counter on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

// Load holds the current count value.
    check_load_holds_count: assert property (
        @(posedge clk) disable iff (reset)
        load |=> (count == $past(count))
    );

// Up mode increments the counter when not loading.
    check_up_mode_increments_count: assert property (
        @(posedge clk) disable iff (reset)
        (!load && up_down) |=> (count == ($past(count) + 4'b0001))
    );

// Down mode decrements the counter when not loading.
    check_down_mode_decrements_count: assert property (
        @(posedge clk) disable iff (reset)
        (!load && !up_down) |=> (count == ($past(count) - 4'b0001))
    );

// Incrementing from 4'hF wraps to 4'h0.
    check_up_wraparound: assert property (
        @(posedge clk) disable iff (reset)
        (!load && up_down && (count == 4'hF)) |=> (count == 4'h0)
    );

// Decrementing from 4'h0 wraps to 4'hF.
    check_down_wraparound: assert property (
        @(posedge clk) disable iff (reset)
        (!load && !up_down && (count == 4'h0)) |=> (count == 4'hF)
    );

// Addition mode drives result to a + b.
    check_add_result: assert property (
        @(posedge clk) disable iff (1'b0)
        (op == 1'b0) |-> (result == (a + b))
    );

// Subtraction mode drives result to a - b.
    check_sub_result: assert property (
        @(posedge clk) disable iff (1'b0)
        (op == 1'b1) |-> (result == (a - b))
    );

// Overflow can only be asserted for signed operations.
    check_overflow_signed_only: assert property (
        @(posedge clk) disable iff (1'b0)
        (overflow == 1'b1) |-> (a[7] == 1 || a[7] == 0 || b[7] == 1 || b[7] == 0)
    );

// Clock: CLK (posedge). Reset: reset (synchronous, active-high). Sequential register with 1-cycle add on non-reset.

    // On reset, out is cleared to 0 on the next cycle.
    reset_clears_out_next: assert property (
        @(posedge CLK) reset |=> (out == 4'd0)
    );

// X matches the implemented OR-then-AND function.
    check_functional_equivalence: assert property (
        @(posedge clk) X == (B1 & (A1 | A2 | A3))
    );

// B1 low forces X low.
    check_b1_low_forces_x_low: assert property (
        @(posedge clk) !B1 |-> !X
    );

// All A inputs low force X low.
    check_all_a_low_forces_x_low: assert property (
        @(posedge clk) !(A1 | A2 | A3) |-> !X
    );

// With B1 high, any A input high drives X high.
    check_b1_high_and_any_a_high_drives_x_high: assert property (
        @(posedge clk) (B1 & (A1 | A2 | A3)) |-> X
    );

// X high requires B1 high and at least one A input high.
    check_x_high_requires_b1_and_any_a: assert property (
        @(posedge clk) X |-> (B1 & (A1 | A2 | A3))
    );

// X high implies B1 is high.
    check_x_high_implies_b1_high: assert property (
        @(posedge clk) X |-> B1
    );

// X high implies at least one A input is high.
    check_x_high_implies_any_a_high: assert property (
        @(posedge clk) X |-> (A1 | A2 | A3)
    );

// Clock: clk (posedge). Reset: rst (synchronous, active-high). Logic: sequential 4-bit up-counter.

    // Reset drives count to zero on the next cycle.
    reset_clears_next: assert property (
        @(posedge clk) rst |=> (count == 4'b0000)
    );

// In normal operation, count is always within 0..15.
    count_range_when_not_reset: assert property (
        @(posedge clk) disable iff (rst) count inside {[4'd0:4'd15]}
    );

// On reset assertion, count is 0 on the next cycle.
    assert_reset_sets_zero_next: assert property (
        @(posedge clk) $rose(rst) |=> (count == 4'd0)
    );

// Reset clears the registered output by the next clock.
    check_reset_clears_sum: assert property (
        @(posedge clk) reset |=> (sum == 32'h0000_0000)
    );

// S captures the upper bits of m_payload_i_reg on the next cycle.
    check_s_captures_m_payload_bits: assert property (
        @(posedge aclk) si_rs_awvalid |=> (S == $past(m_payload_i_reg[47:44]))
    );

// S holds its value when si_rs_awvalid is low.
    check_s_holds_without_awvalid: assert property (
        @(posedge aclk) !si_rs_awvalid |=> (S == $past(S))
    );

// m_axi_awaddr increments by axaddr_incr when axaddr_incr is non-zero.
    check_awaddr_increments_on_nonzero_axaddr_incr: assert property (
        @(posedge aclk) (axaddr_incr != 12'd0) |=> (m_axi_awaddr == ($past(m_axi_awaddr) + $past(axaddr_incr)))
    );

// m_axi_awaddr holds when axaddr_incr is zero.
    check_awaddr_holds_on_zero_axaddr_incr: assert property (
        @(posedge aclk) (axaddr_incr == 12'd0) |=> (m_axi_awaddr == $past(m_axi_awaddr))
    );

// Active-low reset forces both outputs low.
    check_reset_clears_outputs: assert property (
        @(posedge clk) !reset |-> (d_out_1 == 1'b0 && d_out_2 == 1'b0)
    );

// d_out_1 captures d_in on the next clock.
    check_d_out_1_captures_d_in: assert property (
        @(posedge clk) disable iff (!reset)
        1'b1 |=> (d_out_1 == $past(d_in))
    );

// d_out_2 captures the XOR of previous d_out_1 and d_in.
    check_d_out_2_captures_toggle: assert property (
        @(posedge clk) disable iff (!reset)
        1'b1 |=> (d_out_2 == ($past(d_out_1) ^ $past(d_in)))
    );

// d_out_2 matches the XOR of d_out_1 and d_in from the prior cycle.
    check_d_out_2_matches_registered_xor: assert property (
        @(posedge clk) disable iff (!reset)
        1'b1 |=> (d_out_2 == (d_out_1 ^ $past(d_in)))
    );

// A high d_out_2 implies the prior d_out_1 was high.
    check_d_out_2_high_implies_prior_d_out_1_high: assert property (
        @(posedge clk) disable iff (!reset)
        d_out_2 |-> $past(d_out_1)
    );

// A high d_out_2 implies the prior d_in was low.
    check_d_out_2_high_implies_prior_d_in_low: assert property (
        @(posedge clk) disable iff (!reset)
        d_out_2 |-> !$past(d_in)
    );

// A low d_out_2 implies the prior d_out_1 was low.
    check_d_out_2_low_implies_prior_d_out_1_low: assert property (
        @(posedge clk) disable iff (!reset)
        !d_out_2 |-> !$past(d_out_1)
    );

// A low d_out_2 implies the prior d_in was high.
    check_d_out_2_low_implies_prior_d_in_high: assert property (
        @(posedge clk) disable iff (!reset)
        !d_out_2 |-> $past(d_in)
    );

// Reset clears both internal state and the output.
    check_reset_clears_state: assert property (
        @(posedge clk) reset |=> (prev_state == 32'h00000000 && out == 32'h00000000)
    );

// prev_state captures the input from the previous cycle.
    check_prev_state_captures_input: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (prev_state == $past(in))
    );

// out is the previous-cycle input ANDed with the inverted previous-cycle state.
    check_out_matches_registered_delta: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (out == ($past(in) & ~$past(prev_state)))
    );

// Sum matches the XOR of the three inputs.
    check_sum_function: assert property (
        @(posedge clk) S == (A ^ B ^ Ci)
    );

// Carry matches the majority function of the three inputs.
    check_carry_function: assert property (
        @(posedge clk) Co == ((A & B) | (A & Ci) | (B & Ci))
    );

// All-zero inputs produce zero sum and zero carry.
    check_zero_inputs: assert property (
        @(posedge clk) (!A && !B && !Ci) |-> (!S && !Co)
    );

// Any single high input produces sum high and carry low.
    check_single_high_input: assert property (
        @(posedge clk)
        (( A && !B && !Ci) ||
         (!A &&  B && !Ci) ||
         (!A && !B &&  Ci)) |-> ( S && !Co)
    );

// Any two high inputs produce sum low and carry high.
    check_two_high_inputs: assert property (
        @(posedge clk)
        (( A &&  B && !Ci) ||
         ( A && !B &&  Ci) ||
         (!A &&  B &&  Ci)) |-> (!S && Co)
    );

// All-high inputs produce sum high and carry high.
    check_all_high_inputs: assert property (
        @(posedge clk) (A && B && Ci) |-> (S && Co)
    );

// Reset clears the counter on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

// Reset overrides enable when both are asserted.
    check_reset_priority_over_enable: assert property (
        @(posedge clk) (reset && enable) |=> (count == 4'b0000)
    );

// When enabled outside reset, the counter increments by one.
    check_count_increments_when_enabled: assert property (
        @(posedge clk) disable iff (reset) enable |=> (count == ($past(count) + 4'd1))
    );

// When not enabled outside reset, the counter holds its value.
    check_count_holds_when_disabled: assert property (
        @(posedge clk) disable iff (reset) !enable |=> (count == $past(count))
    );

// The 4-bit counter wraps from 15 back to 0.
    check_count_wraps_from_max: assert property (
        @(posedge clk) disable iff (reset) (enable && (count == 4'hF)) |=> (count == 4'h0)
    );

// Active-low clear forces the counter output to zero.
    check_clear_forces_zero: assert property (
        @(posedge clk) !clear |-> (count_out == 4'b0000)
    );

// Load captures data_in on the next clock when clear is high.
    check_load_captures_data: assert property (
        @(posedge clk) disable iff (!clear) load |=> (count_out == $past(data_in))
    );

// With load low and up_down high, the counter increments by one.
    check_increment_when_up: assert property (
        @(posedge clk) disable iff (!clear) (!load && up_down) |=> (count_out == ($past(count_out) + 4'b0001))
    );

// With load low and up_down low, the counter decrements by one.
    check_decrement_when_down: assert property (
        @(posedge clk) disable iff (!clear) (!load && !up_down) |=> (count_out == ($past(count_out) - 4'b0001))
    );

// With load low and up_down high, the counter value changes.
    check_increment_changes_value: assert property (
        @(posedge clk) disable iff (!clear) (!load && up_down) |=> (count_out != $past(count_out))
    );

// With load low and up_down low, the counter value changes.
    check_decrement_changes_value: assert property (
        @(posedge clk) disable iff (!clear) (!load && !up_down) |=> (count_out != $past(count_out))
    );

// Active-low reset forces Q low.
    check_reset_forces_q_low: assert property (
        @(posedge C) !R |-> (Q == 1'b0)
    );

// A sampled reset cycle leaves Q low on the next clock.
    check_reset_cycle_clears_q: assert property (
        @(posedge C) !R |=> (Q == 1'b0)
    );

// With reset inactive, Q captures D on the next clock.
    check_capture_d_when_reset_inactive: assert property (
        @(posedge C) disable iff (!R) 1'b1 |=> (Q == $past(D))
    );

// With reset inactive, a high D is captured into Q.
    check_capture_high_d: assert property (
        @(posedge C) disable iff (!R) D |=> (Q == 1'b1)
    );

// With reset inactive, a low D is captured into Q.
    check_capture_low_d: assert property (
        @(posedge C) disable iff (!R) !D |=> (Q == 1'b0)
    );

// A sampled high D is reflected on Q on the next clock.
    check_high_d_sampled_on_next_cycle: assert property (
        @(posedge C) disable iff (!R) D |=> (Q == 1'b1)
    );

// A sampled low D is reflected on Q on the next clock.
    check_low_d_sampled_on_next_cycle: assert property (
        @(posedge C) disable iff (!R) !D |=> (Q == 1'b0)
    );

// Reset forces the counter output to zero.
    check_reset_clears_output: assert property (
        @(posedge clk) reset |-> (out == 3'b000)
    );

///// Reset behavior /////
    // On reset assertion, all ME registers must be zero.
    reset_clears_me_regs: assert property (
        @(posedge clk) rst |-> (me_aluresult == 32'd0) && (me_d2 == 32'd0) && (me_td == 5'd0) &&
                               (me_WREG == 1'b0) && (me_WMEM == 1'b0) && (me_LW == 1'b0) &&
                               (me_instr == 32'h00000000)
    );

// On reset assertion, me_instr must be 32'h00000000.
    reset_me_instr_zero: assert property (
        @(posedge clk) rst |-> (me_instr == 32'h00000000)
    );

///// Pipeline register behavior /////
    // me_aluresult captures ex_aluresult on the next cycle (when not in reset).
    pipe_aluresult: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |=> (me_aluresult == $past(ex_aluresult))
    );

// me_d2 captures ex_d2 on the next cycle (when not in reset).
    pipe_d2: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |=> (me_d2 == $past(ex_d2))
    );

// me_td captures ex_td on the next cycle (when not in reset).
    pipe_td: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |=> (me_td == $past(ex_td))
    );

// me_WREG captures ex_WREG on the next cycle (when not in reset).
    pipe_WREG: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |=> (me_WREG == $past(ex_WREG))
    );

// me_WMEM captures ex_WMEM on the next cycle (when not in reset).
    pipe_WMEM: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |=> (me_WMEM == $past(ex_WMEM))
    );

// me_LW captures ex_LW on the next cycle (when not in reset).
    pipe_LW: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |=> (me_LW == $past(ex_LW))
    );

// me_instr captures ex_instr on the next cycle (when not in reset).
    pipe_instr: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |=> (me_instr == $past(ex_instr))
    );

// X matches the implemented OR-of-terms function.
    check_x_matches_function: assert property (
        @(posedge clk) X == (A | B | ~(C_N & D_N))
    );

// A high forces X high.
    check_a_high_forces_x_high: assert property (
        @(posedge clk) A |-> X
    );

// B high forces X high.
    check_b_high_forces_x_high: assert property (
        @(posedge clk) B |-> X
    );

// Both C_N and D_N low force X high.
    check_c_n_low_and_d_n_low_force_x_high: assert property (
        @(posedge clk) (!C_N && !D_N) |-> X
    );

// With A and B low, X reduces to the NAND term.
    check_ab_low_reduces_to_nand_term: assert property (
        @(posedge clk) (!A && !B) |-> (X == ~(C_N & D_N))
    );

// With C_N and D_N high, X reduces to the OR of A and B.
    check_c_n_high_and_d_n_high_reduces_to_or: assert property (
        @(posedge clk) (C_N && D_N) |-> (X == (A | B))
    );

// With A and B low and C_N high, X reduces to the inverse NAND term.
    check_ab_low_c_n_high_reduces_to_inverse_nand: assert property (
        @(posedge clk) (!A && !B && C_N) |-> (X == ~D_N)
    );

// With A and B low and D_N high, X reduces to the inverse NAND term.
    check_ab_low_d_n_high_reduces_to_inverse_nand: assert property (
        @(posedge clk) (!A && !B && D_N) |-> (X == ~C_N)
    );

// With A and B low, X equals the NAND of C_N and D_N.
    check_ab_low_equals_nand_term: assert property (
        @(posedge clk) (!A && !B) |-> (X == ~(C_N & D_N))
    );

// With C_N and D_N high, X equals the OR of A and B.
    check_c_n_high_d_n_high_equals_or: assert property (
        @(posedge clk) (C_N && D_N) |-> (X == (A | B))
    );

// With A and B low, X equals the inverse NAND of C_N and D_N.
    check_ab_low_equals_inverse_nand: assert property (
        @(posedge clk) (!A && !B) |-> (X == ~D_N | ~C_N)
    );

// Clock: CLK (posedge). Reset: RST (synchronous, active-high). Sequential flop with enable/transparent load.

    // Reset drives ENCLK low on the next cycle.
    reset_clears_next: assert property (
        @(posedge CLK) RST |=> (ENCLK == 1'b0)
    );

// With TE high, ENCLK loads EN on the next cycle.
    load_on_te: assert property (
        @(posedge CLK) disable iff (RST) TE |=> (ENCLK == $past(EN))
    );

// With TE low, ENCLK holds its previous value.
    hold_when_te_low: assert property (
        @(posedge CLK) disable iff (RST) !TE |=> (ENCLK == $past(ENCLK))
    );

// If TE and EN differ, ENCLK changes on the next cycle.
    change_when_te_and_en_mismatch: assert property (
        @(posedge CLK) disable iff (RST) (TE && (EN != ENCLK)) |=> (ENCLK != $past(ENCLK))
    );

// If TE and EN match, ENCLK does not change on the next cycle.
    no_change_when_te_and_en_match: assert property (
        @(posedge CLK) disable iff (RST) (TE && (EN == ENCLK)) |=> (ENCLK == $past(ENCLK))
    );

// If TE is high and EN equals current ENCLK, ENCLK holds.
    hold_when_te_high_and_en_matches: assert property (
        @(posedge CLK) disable iff (RST) (TE && (EN == ENCLK)) |=> (ENCLK == $past(ENCLK))
    );

// If TE is high and EN differs from current ENCLK, ENCLK changes.
    change_when_te_high_and_en_differs: assert property (
        @(posedge CLK) disable iff (RST) (TE && (EN != ENCLK)) |=> (ENCLK != $past(ENCLK))
    );

// If TE is low and EN equals current ENCLK, ENCLK holds.
    hold_when_te_low_and_en_matches: assert property (
        @(posedge CLK) disable iff (RST) (!TE && (EN == ENCLK)) |=> (ENCLK == $past(ENCLK))
    );

// Y matches the implemented NOR-of-B1 and the A1/A2 AND term.
    check_functional_equivalence: assert property (
        @(posedge clk) Y == ~(B1 | (A1 & A2))
    );

// B1 high forces the NOR output low.
    check_b1_forces_y_low: assert property (
        @(posedge clk) B1 |-> !Y
    );

// Both A inputs high force the AND term high and drive Y low.
    check_a1_a2_force_y_low: assert property (
        @(posedge clk) (A1 && A2) |-> !Y
    );

// With B1 low, a low Y requires both A inputs high.
    check_y_low_requires_a1_a2: assert property (
        @(posedge clk) (!B1 && !Y) |-> (A1 && A2)
    );

// With B1 low, a high Y requires at least one A input low.
    check_y_high_requires_a1_or_a2_low: assert property (
        @(posedge clk) (!B1 && Y) |-> (!A1 || !A2)
    );

// Z must equal the AND of A, B, and C.
    check_and_function: assert property (
        @(posedge clk) Z == (A & B & C)
    );

// All inputs high must drive Z high.
    check_all_inputs_high_drive_z_high: assert property (
        @(posedge clk) (A && B && C) |-> Z
    );

// A low must force Z low.
    check_a_low_forces_z_low: assert property (
        @(posedge clk) !A |-> !Z
    );

// B low must force Z low.
    check_b_low_forces_z_low: assert property (
        @(posedge clk) !B |-> !Z
    );

// C low must force Z low.
    check_c_low_forces_z_low: assert property (
        @(posedge clk) !C |-> !Z
    );

// Z high requires all inputs high.
    check_z_high_requires_all_inputs_high: assert property (
        @(posedge clk) Z |-> (A && B && C)
    );

// Load captures the input into the register on the next cycle.
    check_load_captures_input: assert property (
        @(posedge clk) load |=> (out == $past(in))
    );

// When not loading, the register rotates left by one bit.
    check_rotate_when_not_loading: assert property (
        @(posedge clk) !load |=> (out == {$past(out[2:0]), $past(out[3])})
    );

// The serial output reflects the previous register MSB.
    check_serial_output_tracks_msb: assert property (
        @(posedge clk) 1'b1 |=> (ser_out == $past(out[3]))
    );

// X must match the implemented combinational equation.
    check_x_matches_boolean_function: assert property (
        @(posedge clk) X == ((A1 & A2 & ~B1 & ~B2) | (~A1 & ~A2 & B1 & B2))
    );

// When both A inputs are high and both B inputs are low, X must be high.
    check_x_high_when_a_and_not_b: assert property (
        @(posedge clk) (A1 & A2 & ~B1 & ~B2) |-> X
    );

// When both A inputs are low and both B inputs are high, X must be high.
    check_x_high_when_not_a_and_b: assert property (
        @(posedge clk) (~A1 & ~A2 & B1 & B2) |-> X
    );

// When both A and B are high, X must be low.
    check_x_low_when_both_high: assert property (
        @(posedge clk) (A1 & A2 & B1 & B2) |-> !X
    );

// When both A and B are low, X must be low.
    check_x_low_when_both_low: assert property (
        @(posedge clk) (~A1 & ~A2 & ~B1 & ~B2) |-> !X
    );

// SEL=00 routes A to Y.
    check_sel_00_routes_a: assert property (
        @(posedge clk) (SEL == 2'b00) |-> (Y == A)
    );

// SEL=01 routes B to Y.
    check_sel_01_routes_b: assert property (
        @(posedge clk) (SEL == 2'b01) |-> (Y == B)
    );

// SEL=10 routes C to Y.
    check_sel_10_routes_c: assert property (
        @(posedge clk) (SEL == 2'b10) |-> (Y == C)
    );

// SEL=11 routes D to Y.
    check_sel_11_routes_d: assert property (
        @(posedge clk) (SEL == 2'b11) |-> (Y == D)
    );

// Q updates to SE on the next clock when EN is HIGH.
    check_update_on_en: assert property (
        @(posedge CK) EN |=> (Q == $past(SE))
    );

// Q holds its value on the next clock when EN is LOW.
    check_hold_when_en_low: assert property (
        @(posedge CK) !EN |=> (Q == $past(Q))
    );

// If EN is HIGH and SE differs from the prior Q, Q must change to SE.
    check_update_to_se_when_en_and_se_differs_prev_q: assert property (
        @(posedge CK) (EN && (SE != $past(Q))) |=> (Q == $past(SE))
    );

// read_0 is the previous cycle's selected write or hold value of read_2.
    check_read0_from_read2: assert property (
        @(posedge CLK)
        1'b1 |=> read_0 == $past(EN_write_2 ? write_2 : read_2)
    );

// Reset forces count to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |-> (count == 8'h00)
    );

// Reset has priority over a previous count increment.
    check_reset_overrides_increment: assert property (
        @(posedge clk) (rst && $past(!rst)) |-> (count == 8'h00)
    );

// out_valid is a direct copy of en.
    check_out_valid_matches_en: assert property (
        @(posedge clk) out_valid == en
    );

// out is the AND of in1, in2, and en.
    check_out_matches_and_function: assert property (
        @(posedge clk) out == (in1 & in2 & en)
    );

// When en is low, out must be low.
    check_en_low_forces_out_low: assert property (
        @(posedge clk) !en |-> !out
    );

// When en is high, out equals the AND of in1 and in2.
    check_en_high_passes_and: assert property (
        @(posedge clk) en |-> (out == (in1 & in2))
    );

// A high out requires en and both inputs high.
    check_out_high_requires_en_and_inputs: assert property (
        @(posedge clk) out |-> (en && in1 && in2)
    );

// With en high and both inputs high, out must be high.
    check_en_and_inputs_high_drive_out_high: assert property (
        @(posedge clk) (en && in1 && in2) |-> out
    );

// X must match the implemented combinational equation.
    check_x_matches_equation: assert property (
        @(posedge clk) X == ((A1 | (A2 & ~A3)) & B1)
    );

// B1 low forces X low.
    check_b1_low_forces_x_low: assert property (
        @(posedge clk) !B1 |-> !X
    );

// With B1 high, X reduces to A1 or (A2 & ~A3).
    check_b1_high_reduces_to_or: assert property (
        @(posedge clk) B1 |-> (X == (A1 | (A2 & ~A3)))
    );

// With A1 low, X reduces to B1 & (A2 & ~A3).
    check_a1_low_reduces_to_and: assert property (
        @(posedge clk) !A1 |-> (X == (B1 & (A2 & ~A3)))
    );

// With A2 low, X reduces to B1 & A1.
    check_a2_low_reduces_to_and: assert property (
        @(posedge clk) !A2 |-> (X == (B1 & A1))
    );

// With A3 high, X reduces to B1 & A1.
    check_a3_high_reduces_to_and: assert property (
        @(posedge clk) A3 |-> (X == (B1 & A1))
    );

// O matches the implemented sum equation.
    check_sum_equation: assert property (
        @(posedge clk) O == ((S & DI) | (~S & CI))
    );

// With CIN high, CO reduces to the implemented carry term.
    check_cin_high_reduces_carry: assert property (
        @(posedge clk) CIN |-> (CO == ((CI & S) | (DI & (CI | S))))
    );

// With S low, O follows CI and CO reduces to DI gated by CI.
    check_select_low_behavior: assert property (
        @(posedge clk) !S |-> (O == CI && CO == (DI & CI))
    );

// With S low and DI high, both outputs follow CI.
    check_select_low_di_high: assert property (
        @(posedge clk) (!S && DI) |-> (O == CI && CO == CI)
    );

// During reset, ENCLK must be 0.
    reset_forces_enclk_low: assert property (
        @(posedge CLK) RESET |-> (ENCLK == 1'b0)
    );

// If EN is 0, ENCLK must be 0 on the next cycle.
    en_low_clears_enclk_next: assert property (
        @(posedge CLK) disable iff (RESET) (!EN) |=> (ENCLK == 1'b0)
    );

// If EN is 1 and TE is 1, ENCLK must be 0 on the next cycle.
    en_high_te_high_clears_enclk_next: assert property (
        @(posedge CLK) disable iff (RESET) (EN && TE) |=> (ENCLK == 1'b0)
    );

// If EN is 1 and TE is 0, ENCLK must be 1 on the next cycle.
    en_high_te_low_sets_enclk_next: assert property (
        @(posedge CLK) disable iff (RESET) (EN && !TE) |=> (ENCLK == 1'b1)
    );

// If EN and TE are stable and EN is 0, ENCLK must not change on the next cycle.
    en_low_te_stable_no_change_next: assert property (
        @(posedge CLK) disable iff (RESET) (!EN && $stable(EN) && $stable(TE)) |=> !$changed(ENCLK)
    );

// C must equal the bitwise AND of A and B.
    check_output_matches_and: assert property (
        @(posedge clk) C == (A & B)
    );

// If A is all zeros, C must be all zeros.
    check_zero_a_forces_zero_c: assert property (
        @(posedge clk) (A == 8'h00) |-> (C == 8'h00)
    );

// If B is all zeros, C must be all zeros.
    check_zero_b_forces_zero_c: assert property (
        @(posedge clk) (B == 8'h00) |-> (C == 8'h00)
    );

// If A is all ones, C must equal B.
    check_all_ones_a_passes_b: assert property (
        @(posedge clk) (A == 8'hFF) |-> (C == B)
    );

// If B is all ones, C must equal A.
    check_all_ones_b_passes_a: assert property (
        @(posedge clk) (B == 8'hFF) |-> (C == A)
    );

// If A and B are equal, C must equal that value.
    check_equal_inputs_pass_through: assert property (
        @(posedge clk) (A == B) |-> (C == A)
    );

// If C is all ones, both inputs must be all ones.
    check_all_ones_output_requires_all_ones_inputs: assert property (
        @(posedge clk) (C == 8'hFF) |-> ((A == 8'hFF) && (B == 8'hFF))
    );

// X must be high when any three A inputs are high.
    check_x_high_when_three_a_high: assert property (
        @(posedge clk)
        ((A1 & A2 & A3) |
         (A1 & A2 & A4) |
         (A1 & A3 & A4) |
         (A2 & A3 & A4))
        |-> X
    );

// X must be low when all A inputs are low.
    check_x_low_when_all_a_low: assert property (
        @(posedge clk)
        !(A1 | A2 | A3 | A4) |-> !X
    );

// Reset clears q on the following clock.
    check_reset_clears_q: assert property (
        @(posedge clk) rst |=> (q == 64'h0000_0000_0000_0000)
    );

// Reset has priority over load when both are asserted.
    check_reset_priority_over_load: assert property (
        @(posedge clk) (rst && ld) |=> (q == 64'h0000_0000_0000_0000)
    );

// Load captures d into q on the following clock.
    check_load_captures_d: assert property (
        @(posedge clk) disable iff (rst) ld |=> (q == $past(d))
    );

// With neither reset nor load asserted, q holds its value.
    check_hold_when_idle: assert property (
        @(posedge clk) disable iff (rst) (!ld && !rst) |=> (q == $past(q))
    );

// Reset drives Q to zero on the next clock.
    check_reset_clears_q: assert property (
        @(posedge CK) RST |=> (Q == 4'b0000)
    );

// When not in reset, Q increments by one on the next clock.
    check_count_increments: assert property (
        @(posedge CK) disable iff (RST) 1'b1 |=> (Q == ($past(Q) + 4'd1))
    );

// The 4-bit counter wraps from 15 back to 0.
    check_count_wraps: assert property (
        @(posedge CK) disable iff (RST) (Q == 4'hF) |=> (Q == 4'h0)
    );

// Y matches the implemented NOT-OR function.
    check_function_equivalence: assert property (
        @(posedge clk) Y == (A_N | ~B)
    );

// A_N high forces the OR term high and drives Y high.
    check_a_n_high_forces_y_high: assert property (
        @(posedge clk) A_N |-> Y
    );

// B low forces the inverted B term high and drives Y high.
    check_b_low_forces_y_high: assert property (
        @(posedge clk) !B |-> Y
    );

// With both inputs inactive, Y must be low.
    check_both_inputs_inactive_drive_y_low: assert property (
        @(posedge clk) (!A_N && B) |-> !Y
    );

// A low Y can only occur when A_N is low and B is high.
    check_y_low_has_valid_cause: assert property (
        @(posedge clk) !Y |-> (!A_N && B)
    );

// Reset forces the DONE state and deasserts ack.
    check_reset_state: assert property (
        @(posedge clk) !rst_n |-> (ack == 1'b0)
    );

// AND opcode drives the bitwise AND result.
    check_and_opcode: assert property (
        @(posedge clk) (aluc == 4'b0001) |-> (result == (a & b))
    );

// OR opcode drives the bitwise OR result.
    check_or_opcode: assert property (
        @(posedge clk) (aluc == 4'b0101) |-> (result == (a | b))
    );

// XOR opcode drives the bitwise XOR result.
    check_xor_opcode: assert property (
        @(posedge clk) (aluc == 4'b1010) |-> (result == (a ^ b))
    );

// ADD opcode drives the addition result.
    check_add_opcode: assert property (
        @(posedge clk) (aluc == 4'b0000) |-> (result == (a + b))
    );

// SUB opcode drives the subtraction result.
    check_sub_opcode: assert property (
        @(posedge clk) (aluc == 4'b0100) |-> (result == (a - b))
    );

// SLL opcode drives the logical left shift result.
    check_sll_opcode: assert property (
        @(posedge clk) (aluc == 4'b0011) |-> (result == (b << a))
    );

// SRL opcode drives the logical right shift result.
    check_srl_opcode: assert property (
        @(posedge clk) (aluc == 4'b0111) |-> (result == (b >> a))
    );

// LUI opcode drives the upper-immediate result.
    check_lui_opcode: assert property (
        @(posedge clk) (aluc == 4'b0110) |-> (result == {16'b0, b[15:0]})
    );

// Y is always the logical inverse of A.
    check_inverter_function: assert property (
        @(posedge clk) Y == ~A
    );

// A low input produces a high output.
    check_low_input_high_output: assert property (
        @(posedge clk) (A == 1'b0) |-> (Y == 1'b1)
    );

// A high input produces a low output.
    check_high_input_low_output: assert property (
        @(posedge clk) (A == 1'b1) |-> (Y == 1'b0)
    );

// If A and B are both high, Z[1] must be low.
    check_z1_low_when_ab_high: assert property (
        @(posedge clk) (A & B) |-> (Z[1] == 1'b0)
    );

// Reset forces count to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |-> (count == 4'b0000)
    );

// Reset has priority over enable.
    check_reset_priority_over_enable: assert property (
        @(posedge clk) (reset && enable) |-> (count == 4'b0000)
    );

// shifted_data[0] captures data[7] from the previous clock.
    check_shifted_bit0_captures_data7: assert property (
        @(posedge clk) 1'b1 |=> (shifted_data[0] == $past(data[7]))
    );

// shifted_data[1] shifts in the previous shifted_data[0].
    check_shifted_bit1_shifts_from_bit0: assert property (
        @(posedge clk) 1'b1 |=> (shifted_data[1] == $past(shifted_data[0]))
    );

// shifted_data[2] shifts in the previous shifted_data[1].
    check_shifted_bit2_shifts_from_bit1: assert property (
        @(posedge clk) 1'b1 |=> (shifted_data[2] == $past(shifted_data[1]))
    );

// shifted_data[3] shifts in the previous shifted_data[2].
    check_shifted_bit3_shifts_from_bit2: assert property (
        @(posedge clk) 1'b1 |=> (shifted_data[3] == $past(shifted_data[2]))
    );

// shifted_data[4] shifts in the previous shifted_data[3].
    check_shifted_bit4_shifts_from_bit3: assert property (
        @(posedge clk) 1'b1 |=> (shifted_data[4] == $past(shifted_data[3]))
    );

// shifted_data[5] shifts in the previous shifted_data[4].
    check_shifted_bit5_shifts_from_bit4: assert property (
        @(posedge clk) 1'b1 |=> (shifted_data[5] == $past(shifted_data[4]))
    );

// shifted_data[6] shifts in the previous shifted_data[5].
    check_shifted_bit6_shifts_from_bit5: assert property (
        @(posedge clk) 1'b1 |=> (shifted_data[6] == $past(shifted_data[5]))
    );

// shifted_data[7] shifts in the previous shifted_data[6].
    check_shifted_bit7_shifts_from_bit6: assert property (
        @(posedge clk) 1'b1 |=> (shifted_data[7] == $past(shifted_data[6]))
    );

// Y matches the NAND of B1 and the OR of A1/A2/A3.
    check_function_equivalence: assert property (
        @(posedge clk) Y == ~(B1 & (A1 | A2 | A3))
    );

// B1 low forces the NAND output high.
    check_b1_low_forces_y_high: assert property (
        @(posedge clk) !B1 |-> Y
    );

// All A inputs low force the OR term low and Y high.
    check_all_a_low_forces_y_high: assert property (
        @(posedge clk) !(A1 | A2 | A3) |-> Y
    );

// B1 high with any A input high forces Y low.
    check_active_inputs_force_y_low: assert property (
        @(posedge clk) (B1 & (A1 | A2 | A3)) |-> !Y
    );

// A low Y requires B1 high and at least one A input high.
    check_y_low_requires_active_inputs: assert property (
        @(posedge clk) !Y |-> (B1 & (A1 | A2 | A3))
    );

// A high Y requires B1 low or all A inputs low.
    check_y_high_requires_inactive_inputs: assert property (
        @(posedge clk) Y |-> (!B1 | !(A1 | A2 | A3))
    );

// When select is 000, only out0 reflects the input.
    check_sel000_passthrough: assert property (
        @(posedge clk) ((sel2 == 1'b0) && (sel1 == 1'b0) && (sel0 == 1'b0)) |-> (out0 == in)
    );

// When select is 001, only out1 reflects the input.
    check_sel001_passthrough: assert property (
        @(posedge clk) ((sel2 == 1'b0) && (sel1 == 1'b0) && (sel0 == 1'b1)) |-> (out1 == in)
    );

// When select is 010, only out2 reflects the input.
    check_sel010_passthrough: assert property (
        @(posedge clk) ((sel2 == 1'b0) && (sel1 == 1'b1) && (sel0 == 1'b0)) |-> (out2 == in)
    );

// When select is 011, only out3 reflects the input.
    check_sel011_passthrough: assert property (
        @(posedge clk) ((sel2 == 1'b0) && (sel1 == 1'b1) && (sel0 == 1'b1)) |-> (out3 == in)
    );

// When select is 100, only out4 reflects the input.
    check_sel100_passthrough: assert property (
        @(posedge clk) ((sel2 == 1'b1) && (sel1 == 1'b0) && (sel0 == 1'b0)) |-> (out4 == in)
    );

// When select is 101, only out5 reflects the input.
    check_sel101_passthrough: assert property (
        @(posedge clk) ((sel2 == 1'b1) && (sel1 == 1'b0) && (sel0 == 1'b1)) |-> (out5 == in)
    );

// When select is 110, only out6 reflects the input.
    check_sel110_passthrough: assert property (
        @(posedge clk) ((sel2 == 1'b1) && (sel1 == 1'b1) && (sel0 == 1'b0)) |-> (out6 == in)
    );

// When select is 111, only out7 reflects the input.
    check_sel111_passthrough: assert property (
        @(posedge clk) ((sel2 == 1'b1) && (sel1 == 1'b1) && (sel0 == 1'b1)) |-> (out7 == in)
    );

// When A and B are both 0, O0 must be high and all other outputs must be low.
    check_decode_00: assert property (
        @(posedge clk) ({A, B} == 2'b00) |-> (O == 16'h0001)
    );

// When A is 0 and B is 1, O1 must be high and all other outputs must be low.
    check_decode_01: assert property (
        @(posedge clk) ({A, B} == 2'b01) |-> (O == 16'h0002)
    );

// When A is 1 and B is 0, O2 must be high and all other outputs must be low.
    check_decode_10: assert property (
        @(posedge clk) ({A, B} == 2'b10) |-> (O == 16'h0004)
    );

// When A and B are both 1, O3 must be high and all other outputs must be low.
    check_decode_11: assert property (
        @(posedge clk) ({A, B} == 2'b11) |-> (O == 16'h0008)
    );

// For all other input combinations, O must be zero.
    check_default_zero: assert property (
        @(posedge clk) !(({A, B} inside {2'b00, 2'b01, 2'b10, 2'b11})) |-> (O == 16'h0000)
    );

// The upper 12 bits of O must always be zero.
    check_upper_bits_zero: assert property (
        @(posedge clk) (O[15:4] == 12'h000)
    );

// O must always be one of the four valid decoder outputs.
    check_output_valid_set: assert property (
        @(posedge clk) (O inside {16'h0001, 16'h0002, 16'h0004, 16'h0008})
    );

// All other states map to gray code 0.
    check_default_state_maps_to_gray_0: assert property (
        @(posedge clk) disable iff (rst)
        ((out != 1'b0) && (out != 1'b1) && (out != 3'b11) && (out != 3'b10) &&
         (out != 3'b110) && (out != 3'b111) && (out != 3'b101) && (out != 3'b100))
        |-> ($past(out) == 1'b0)
    );

// Active-low reset forces q low.
    check_reset_clears_q: assert property (
        @(posedge clk) !areset |-> (q == 4'b0000)
    );

// Reset has priority over load.
    check_reset_priority_over_load: assert property (
        @(posedge clk) (!areset && load) |-> (q == 4'b0000)
    );

// Reset has priority over enable.
    check_reset_priority_over_enable: assert property (
        @(posedge clk) (!areset && ena) |-> (q == 4'b0000)
    );

// Load captures data into q.
    check_load_captures_data: assert property (
        @(posedge clk) disable iff (!areset) load |=> (q == $past(data))
    );

// Enable rotates q left when load is low.
    check_enable_rotates_q: assert property (
        @(posedge clk) disable iff (!areset) (!load && ena) |=> (q == {$past(q[2:0]), $past(q[3])})
    );

// With no load or enable, q holds its value.
    check_hold_when_idle: assert property (
        @(posedge clk) disable iff (!areset) (!load && !ena) |=> (q == $past(q))
    );

// Output must match the mux select expression.
    check_mux_function: assert property (
        @(posedge clk) out == ((sel == 1'b1) ? b : a)
    );

// When select is low, output must follow input a.
    check_select_low_routes_a: assert property (
        @(posedge clk) (sel == 1'b0) |-> (out == a)
    );

// When select is high, output must follow input b.
    check_select_high_routes_b: assert property (
        @(posedge clk) (sel == 1'b1) |-> (out == b)
    );

// If both inputs are equal, output must match that common value.
    check_equal_inputs_passthrough: assert property (
        @(posedge clk) (a == b) |-> (out == a)
    );

// X must match the implemented mux equation.
    check_mux_equation: assert property (
        @(posedge clk)
        X == ((A0 & ~S0 & ~S1) | (A1 & S0 & ~S1) | (A2 & ~S0 & S1) | (A3 & S0 & S1))
    );

// When S1 is low, X must select between A0 and A1.
    check_select_low_path: assert property (
        @(posedge clk)
        !S1 |-> (X == ((A0 & ~S0) | (A1 & S0)))
    );

// When S1 is high, X must select between A2 and A3.
    check_select_high_path: assert property (
        @(posedge clk)
        S1 |-> (X == ((A2 & ~S0) | (A3 & S0)))
    );

// With S1 low and S0 low, X must follow A0.
    check_select_low_low: assert property (
        @(posedge clk)
        (!S1 && !S0) |-> (X == A0)
    );

// With S1 low and S0 high, X must follow A1.
    check_select_low_high: assert property (
        @(posedge clk)
        (!S1 && S0) |-> (X == A1)
    );

// With S1 high and S0 low, X must follow A2.
    check_select_high_low: assert property (
        @(posedge clk)
        (S1 && !S0) |-> (X == A2)
    );

// With S1 high and S0 high, X must follow A3.
    check_select_high_high: assert property (
        @(posedge clk)
        (S1 && S0) |-> (X == A3)
    );

// Q captures D on the next rising edge when E is HIGH.
    check_capture_when_enabled: assert property (
        @(posedge C) E |=> (Q == $past(D))
    );

// Q holds its value on the next rising edge when E is LOW.
    check_hold_when_disabled: assert property (
        @(posedge C) !E |=> (Q == $past(Q))
    );

// If E is HIGH and D equals the current Q, Q must not change on the next rising edge.
    check_no_change_when_enabled_and_equal: assert property (
        @(posedge C) (E && (D == Q)) |=> (Q == $past(Q))
    );

// If E is HIGH and D differs from the current Q, Q must change on the next rising edge.
    check_change_when_enabled_and_diff: assert property (
        @(posedge C) (E && (D != Q)) |=> (Q != $past(Q))
    );

// If E is LOW and D differs from the current Q, Q must not change on the next rising edge.
    check_no_change_when_disabled_and_diff: assert property (
        @(posedge C) (!E && (D != Q)) |=> (Q == $past(Q))
    );

// If E is HIGH and D differs from the current Q, Q must equal D on the next rising edge.
    check_next_value_when_enabled_and_diff: assert property (
        @(posedge C) (E && (D != Q)) |=> (Q == $past(D))
    );

// If E is LOW and D differs from the current Q, Q must equal the previous Q on the next rising edge.
    check_next_value_when_disabled_and_diff: assert property (
        @(posedge C) (!E && (D != Q)) |=> (Q == $past(Q))
    );

// If E is HIGH and D equals the current Q, Q must equal D on the next rising edge.
    check_next_value_when_enabled_and_equal: assert property (
        @(posedge C) (E && (D == Q)) |=> (Q == $past(D))
    );

// Reset clears the register chain by the next clock.
    check_reset_clears_chain: assert property (
        @(posedge CLK) RST |=> (OUT == 4'b0000)
    );

// Without load, the register chain shifts by one bit.
    check_shift_updates_chain: assert property (
        @(posedge CLK) disable iff (RST)
        !LD |=> (OUT == $past(OUT))
    );

// Reset has priority over load when both are asserted.
    check_reset_priority_over_load: assert property (
        @(posedge CLK) RST && LD |=> (OUT == 4'b0000)
    );

// Load has priority over shift when both are asserted without reset.
    check_load_priority_over_shift: assert property (
        @(posedge CLK) disable iff (RST)
        !RST && LD && !LD |=> (OUT == $past(D))
    );

// Left shift mode must produce the left-shifted value.
    check_left_shift_result: assert property (
        @(posedge clk) shift_left |-> (out == (in << shift_amt))
    );

// Right shift mode must produce the right-shifted value.
    check_right_shift_result: assert property (
        @(posedge clk) !shift_left |-> (out == (in >> shift_amt))
    );

// A zero shift amount must pass the input through unchanged.
    check_zero_shift_passthrough: assert property (
        @(posedge clk) (shift_amt == 4'd0) |-> (out == in)
    );

// COUT is the AND of A and B.
    check_cout_is_and: assert property (
        @(posedge clk) COUT == (A & B)
    );

// SUM is the XOR of A and B.
    check_sum_is_xor: assert property (
        @(posedge clk) SUM == (A ^ B)
    );

// The outputs match the two-input half-adder equations.
    check_half_adder_equations: assert property (
        @(posedge clk) {COUT, SUM} == ({1'b0, A} + {1'b0, B})
    );

// Both low inputs produce both low outputs.
    check_zero_inputs: assert property (
        @(posedge clk) (!A && !B) |-> (!COUT && !SUM)
    );

// Different inputs produce different outputs.
    check_different_inputs: assert property (
        @(posedge clk) (A ^ B) |-> (COUT ^ SUM)
    );

// X must equal the XOR of A and B.
    check_xor_function: assert property (
        @(posedge clk) X == (A ^ B)
    );

// When A and B are equal, X must be low.
    check_equal_inputs_drive_low: assert property (
        @(posedge clk) (A == B) |-> (X == 1'b0)
    );

// When A and B differ, X must be high.
    check_different_inputs_drive_high: assert property (
        @(posedge clk) (A != B) |-> (X == 1'b1)
    );

// X must always match the mux select expression.
    check_mux_function: assert property (
        @(posedge clk) X == (S ? A1 : A0)
    );

// When S is low, X must select A0.
    check_select_low_routes_a0: assert property (
        @(posedge clk) !S |-> (X == A0)
    );

// When S is high, X must select A1.
    check_select_high_routes_a1: assert property (
        @(posedge clk) S |-> (X == A1)
    );

// If both data inputs are equal, X must equal that common value.
    check_equal_inputs_passthrough: assert property (
        @(posedge clk) (A0 == A1) |-> (X == A0)
    );

// Bit 2 sum must use the ripple carry from bits 0 and 1.
    check_sum_bit2: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^
            ((A[1] & B[1]) | (A[1] & (A[0] & B[0])) | (B[1] & (A[0] & B[0]))))
    );

// Bit 3 sum must use the ripple carry from bits 0 through 2.
    check_sum_bit3: assert property (
        @(posedge clk) S[3] == (A[3] ^ B[3] ^
            ((A[2] & B[2]) |
             (A[2] & ((A[1] & B[1]) | (A[1] & (A[0] & B[0])) | (B[1] & (A[0] & B[0])))) |
             (B[2] & ((A[1] & B[1]) | (A[1] & (A[0] & B[0])) | (B[1] & (A[0] & B[0]))))))
    );

// 4'hF plus 4'h1 must wrap to zero with carry-out set.
    check_max_plus_one: assert property (
        @(posedge clk) ((A == 4'hF) && (B == 4'h1)) |-> ({COUT, S} == 5'b10000)
    );

// Y matches the implemented combinational function.
    check_y_function: assert property (
        @(posedge clk) Y == ~((A1 & A2 & B1) | (A1 & B1))
    );

// With B1 low and A1 low, Y must be high.
    check_b1_low_a1_low_forces_y_high: assert property (
        @(posedge clk) (!B1 & !A1) |-> Y
    );

// With B1 low and A2 low, Y must be high.
    check_b1_low_a2_low_forces_y_high: assert property (
        @(posedge clk) (!B1 & !A2) |-> Y
    );

// clkout is always the bitwise inversion of clkin.
    check_inversion: assert property (
        @(posedge clkin) clkout == ~clkin
    );

// If clkin is 0, clkout must be 1.
    check_map_0_to_1: assert property (
        @(posedge clkin) (clkin == 1'b0) |-> (clkout == 1'b1)
    );

// If clkin is 1, clkout must be 0.
    check_map_1_to_0: assert property (
        @(posedge clkin) (clkin == 1'b1) |-> (clkout == 1'b0)
    );

// clkout can never equal clkin.
    check_never_equal: assert property (
        @(posedge clkin) clkout != clkin
    );

// clkout is never X/Z when clkin is known (0/1).
    check_known_when_clkin_known: assert property (
        @(posedge clkin) !$isunknown(clkin) |-> !$isunknown(clkout)
    );

// clkout and clkin are never both 0 at the same sampled edge.
    check_no_both_zero: assert property (
        @(posedge clkin) !(clkout == 1'b0 && clkin == 1'b0)
    );

// clkout and clkin are never both 1 at the same sampled edge.
    check_no_both_one: assert property (
        @(posedge clkin) !(clkout == 1'b1 && clkin == 1'b1)
    );

// Reset forces the internal register low.
    check_reset_clears_data_sync: assert property (
        @(posedge clk) rst |-> (data_sync == 2'b00)
    );

// Reset forces the output low.
    check_reset_clears_data_out: assert property (
        @(posedge clk) rst |-> (data_out == 1'b0)
    );

// The output reflects the previous cycle's reset state.
    check_reset_propagates_to_output: assert property (
        @(posedge clk) $past(rst) |-> (data_out == 1'b0)
    );

// Reset forces the state machine into S0.
    check_reset_state: assert property (
        @(posedge clk_i) !reset_n |-> (state == 2'b00)
    );

// Reset forces the selected output to 000.
    check_reset_sel: assert property (
        @(posedge clk_i) !reset_n |-> (sel == 3'b000)
    );

// Invalid states drive the next state to S0.
    check_invalid_next_state: assert property (
        @(posedge clk_i) disable iff (!reset_n) (state != 2'b00 && state != 2'b01 && state != 2'b10 && state != 2'b11) |-> (state_next == 2'b00)
    );

// X must equal the OR of all pairwise AND terms.
    check_x_matches_pairwise_or: assert property (
        @(posedge clk) X == ((A & B) | (A & C) | (B & C))
    );

// If A and B are high, X must be high.
    check_ab_sets_x: assert property (
        @(posedge clk) (A & B) |-> X
    );

// If A and C are high, X must be high.
    check_ac_sets_x: assert property (
        @(posedge clk) (A & C) |-> X
    );

// If B and C are high, X must be high.
    check_bc_sets_x: assert property (
        @(posedge clk) (B & C) |-> X
    );

// X high requires at least one pair to be high.
    check_x_high_requires_pair: assert property (
        @(posedge clk) X |-> (A & B) | (A & C) | (B & C)
    );

// X low means no pair is high.
    check_x_low_means_no_pair: assert property (
        @(posedge clk) !X |-> !(A & B & C)
    );

// VGND is tied low.
    check_vgnd_tied_low: assert property (
        @(posedge clk) VGND == 1'b0
    );

// VPWR is tied high.
    check_vpwr_tied_high: assert property (
        @(posedge clk) VPWR == 1'b1
    );

// VPB is tied high.
    check_vpb_tied_high: assert property (
        @(posedge clk) VPB == 1'b1
    );

// VNB is tied low.
    check_vnb_tied_low: assert property (
        @(posedge clk) VNB == 1'b0
    );

// Q follows the RTL next-state function.
    check_next_state_function: assert property (
        @(posedge CLK) disable iff (1'b0)
        1'b1 |=> (Q == ($past(DE) ? $past(D) : ($past(SCE) ? $past(SCD) : $past(Q))))
    );

// DE has highest priority and loads D on the next cycle.
    check_de_loads_d: assert property (
        @(posedge CLK) disable iff (1'b0)
        DE |=> (Q == $past(D))
    );

// With DE low, SCE loads SCD on the next cycle.
    check_sce_loads_scd_when_de_low: assert property (
        @(posedge CLK) disable iff (1'b0)
        (!DE && SCE) |=> (Q == $past(SCD))
    );

// With DE and SCE low, Q holds its previous value.
    check_hold_when_both_controls_low: assert property (
        @(posedge CLK) disable iff (1'b0)
        (!DE && !SCE) |=> (Q == $past(Q))
    );

// Active-low reset clears the register.
    check_reset_clears_q: assert property (
        @(posedge CLK) !AR |-> (Q == {N{1'b0}})
    );

// Reset overrides an enabled add.
    check_reset_priority_over_add: assert property (
        @(posedge CLK) (!AR && E) |-> (Q == {N{1'b0}})
    );

// Y matches the implemented NAND-AND function.
    check_function_equivalence: assert property (
        @(posedge clk) Y == ((~(A2 & A1 & A3)) & (~(B2 & B1)))
    );

// All three A inputs high force Y low.
    check_all_a_high_forces_low: assert property (
        @(posedge clk) (A1 & A2 & A3) |-> !Y
    );

// All two B inputs high force Y low.
    check_all_b_high_forces_low: assert property (
        @(posedge clk) (B1 & B2) |-> !Y
    );

// With no A-side block and no B-side block, Y is high.
    check_no_block_on_a_or_b_sets_high: assert property (
        @(posedge clk) ((~(A2 & A1 & A3)) & (~(B2 & B1))) |-> Y
    );

// A high Y means neither NAND term is blocked.
    check_y_high_requires_no_a_block_and_no_b_block: assert property (
        @(posedge clk) Y |-> ((~(A2 & A1 & A3)) & (~(B2 & B1)))
    );

// A low Y means at least one NAND term is blocked.
    check_y_low_requires_a_block_or_b_block: assert property (
        @(posedge clk) !Y |-> ((A2 & A1 & A3) | (B2 & B1))
    );

// SUM is the XOR of A, B, and CI.
    check_sum_xor: assert property (
        @(posedge clk) SUM == (A ^ B ^ CI)
    );

// COUT is high when at least two inputs are high.
    check_cout_majority: assert property (
        @(posedge clk) COUT == ((A & B) | (A & CI) | (B & CI))
    );

// All-zero inputs produce zero sum and zero carry.
    check_all_zero_case: assert property (
        @(posedge clk) (!A && !B && !CI) |-> (!SUM && !COUT)
    );

// All-one inputs produce sum one and carry one.
    check_all_one_case: assert property (
        @(posedge clk) (A && B && CI) |-> (SUM && COUT)
    );

// Exactly one high input produces sum one and carry zero.
    check_one_hot_case: assert property (
        @(posedge clk)
        ((A && !B && !CI) || (!A && B && !CI) || (!A && !B && CI))
        |-> (SUM && !COUT)
    );

// Exactly two high inputs produce sum zero and carry one.
    check_two_hot_case: assert property (
        @(posedge clk)
        ((A && B && !CI) || (A && !B && CI) || (!A && B && CI))
        |-> (!SUM && COUT)
    );

// Reset forces the counter to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |-> (count == 4'b0000)
    );

// A non-maximum count increments by one on the next clock.
    check_count_increments: assert property (
        @(posedge clk) disable iff (reset)
        (count != 4'hF) |=> (count == ($past(count) + 4'h1))
    );

// A maximum count wraps back to zero on the next clock.
    check_count_wraps: assert property (
        @(posedge clk) disable iff (reset)
        (count == 4'hF) |=> (count == 4'h0)
    );

// Y matches the implemented OR-AND-NOT function.
    check_y_function: assert property (
        @(posedge clk) Y == ~((A1 | A2) & B1 & C1)
    );

// If B1 is low, the AND term is low and Y must be high.
    check_y_high_when_b1_low: assert property (
        @(posedge clk) !B1 |-> Y
    );

// If C1 is low, the AND term is low and Y must be high.
    check_y_high_when_c1_low: assert property (
        @(posedge clk) !C1 |-> Y
    );

// If both A inputs are low, the OR term is low and Y must be high.
    check_y_high_when_a_inputs_low: assert property (
        @(posedge clk) !(A1 | A2) |-> Y
    );

// If B1, C1, and at least one A input are high, Y must be low.
    check_y_low_when_all_active: assert property (
        @(posedge clk) (B1 & C1 & (A1 | A2)) |-> !Y
    );

// A low Y requires B1, C1, and at least one A input to be high.
    check_y_low_implies_all_active: assert property (
        @(posedge clk) !Y |-> (B1 & C1 & (A1 | A2))
    );

// Reset forces the output to zero.
    check_reset_clears_output: assert property (
        @(posedge clk) rst |-> (out_send == '0)
    );

// The output reflects the input from the previous clock.
    check_output_tracks_previous_input: assert property (
        @(posedge clk) disable iff (rst)
        1'b1 |=> (out_send == $past(in_receive))
    );

// A zero input is preserved on the next clock.
    check_zero_input_preserved: assert property (
        @(posedge clk) disable iff (rst)
        (in_receive == '0) |=> (out_send == '0)
    );

// A zero output must come from a zero input on the previous clock.
    check_zero_output_requires_zero_input: assert property (
        @(posedge clk) disable iff (rst)
        1'b1 |=> ((out_send == '0) |-> ($past(in_receive) == '0))
    );

// Y matches the implemented OR-OR-NAND function.
    check_y_matches_logic_function: assert property (
        @(posedge clk) Y == ~((A1 | A2) & (B1 | B2) & C1)
    );

// C1 low forces the NAND output high.
    check_c1_low_forces_y_high: assert property (
        @(posedge clk) !C1 |-> Y
    );

// Both A inputs low force the NAND output high.
    check_a_inputs_low_force_y_high: assert property (
        @(posedge clk) !(A1 | A2) |-> Y
    );

// Both B inputs low force the NAND output high.
    check_b_inputs_low_force_y_high: assert property (
        @(posedge clk) !(B1 | B2) |-> Y
    );

// All three active terms force the NAND output low.
    check_all_terms_active_force_y_low: assert property (
        @(posedge clk) (C1 && (A1 | A2) && (B1 | B2)) |-> !Y
    );

// A low Y requires all three active terms to be present.
    check_y_low_requires_all_terms_active: assert property (
        @(posedge clk) !Y |-> (C1 && (A1 | A2) && (B1 | B2))
    );

// With C1 and both A inputs high, Y reduces to the inverted OR of B inputs.
    check_c1_and_a_high_reduces_to_not_b_or: assert property (
        @(posedge clk) (C1 && A1 && A2) |-> (Y == ~(B1 | B2))
    );

// With C1 and both B inputs high, Y reduces to the inverted OR of A inputs.
    check_c1_and_b_high_reduces_to_not_a_or: assert property (
        @(posedge clk) (C1 && B1 && B2) |-> (Y == ~(A1 | A2))
    );

// Output must match the mux select expression.
    check_mux_function: assert property (
        @(posedge clk)
        out == ((sel1 & sel0) ? in3 :
                (sel1 & ~sel0) ? in2 :
                (~sel1 & sel0) ? in1 :
                in0)
    );

// When both select bits are high, output must come from in3.
    check_select_11: assert property (
        @(posedge clk)
        (sel1 && sel0) |-> (out == in3)
    );

// When both select bits are low, output must come from in0.
    check_select_00: assert property (
        @(posedge clk)
        (!sel1 && !sel0) |-> (out == in0)
    );

// Output must match the implemented mux equation.
    check_mux_equation: assert property (
        @(posedge clk) out == ((in0 & ~sel) | (in1 & sel))
    );

// When select is low, the output must follow in0.
    check_select_low_routes_in0: assert property (
        @(posedge clk) !sel |-> (out == in0)
    );

// When select is high, the output must follow in1.
    check_select_high_routes_in1: assert property (
        @(posedge clk) sel |-> (out == in1)
    );

// With select low and both inputs equal, the output must match that value.
    check_equal_inputs_select_low: assert property (
        @(posedge clk) (!sel && (in0 == in1)) |-> (out == in0)
    );

// With select high and both inputs equal, the output must match that value.
    check_equal_inputs_select_high: assert property (
        @(posedge clk) (sel && (in0 == in1)) |-> (out == in0)
    );

// X must match the implemented combinational equation.
    check_x_matches_logic: assert property (
        @(posedge clk) X == ((A & B) || (C | D) || !(E & F) || !(G | H))
    );

// A and B high must force X high.
    check_ab_term_sets_x: assert property (
        @(posedge clk) (A & B) |-> X
    );

// C or D high must force X high.
    check_cd_term_sets_x: assert property (
        @(posedge clk) (C | D) |-> X
    );

// E and F low must force X high.
    check_ef_term_sets_x: assert property (
        @(posedge clk) !(E & F) |-> X
    );

// G or H low must force X high.
    check_gh_term_sets_x: assert property (
        @(posedge clk) !(G | H) |-> X
    );

// If all four product terms are false, X must be low.
    check_all_terms_false_clears_x: assert property (
        @(posedge clk) !((A & B) || (C | D) || !(E & F) || !(G | H)) |-> !X
    );

// X low means every product term must be false.
    check_x_low_requires_all_terms_false: assert property (
        @(posedge clk) !X |-> !((A & B) || (C | D) || !(E & F) || !(G | H))
    );

// X high means at least one product term must be true.
    check_x_high_requires_some_term_true: assert property (
        @(posedge clk) X |-> ((A & B) || (C | D) || !(E & F) || !(G | H))
    );

// Y must always equal the NAND of A and B.
    check_nand_function: assert property (
        @(posedge clk) Y == ~(A & B)
    );

// Both high inputs must drive Y low.
    check_both_high_drive_low: assert property (
        @(posedge clk) (A && B) |-> !Y
    );

// A low must force Y high.
    check_a_low_forces_high: assert property (
        @(posedge clk) !A |-> Y
    );

// B low must force Y high.
    check_b_low_forces_high: assert property (
        @(posedge clk) !B |-> Y
    );

// A low output requires both inputs high.
    check_low_output_requires_both_high: assert property (
        @(posedge clk) !Y |-> (A && B)
    );

// y must match the XOR of a and b.
    check_xor_function: assert property (
        @(posedge clk) y == (a ^ b)
    );

// When a is low, y must follow b.
    check_a_low_passes_b: assert property (
        @(posedge clk) !a |-> (y == b)
    );

// When a is high, y must be the inverse of b.
    check_a_high_inverts_b: assert property (
        @(posedge clk) a |-> (y == !b)
    );

// When b is low, y must follow a.
    check_b_low_passes_a: assert property (
        @(posedge clk) !b |-> (y == a)
    );

// When b is high, y must be the inverse of a.
    check_b_high_inverts_a: assert property (
        @(posedge clk) b |-> (y == !a)
    );

// Equal inputs must produce a low output.
    check_equal_inputs_drive_low: assert property (
        @(posedge clk) (a == b) |-> !y
    );

// Different inputs must produce a high output.
    check_different_inputs_drive_high: assert property (
        @(posedge clk) (a != b) |-> y
    );

// Clock: clk (posedge). Reset: reset (synchronous, active-high). Sequential 4-bit counter with enable.

    // Reset drives count to zero on the next cycle.
    reset_clears_count_next: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

// When enabled without reset, count increments by 1 on the next cycle.
    increment_when_enabled: assert property (
        @(posedge clk) disable iff (reset) enable |=> (count == $past(count) + 4'd1)
    );

// When not enabled without reset, count holds its value on the next cycle.
    hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset) !enable |=> (count == $past(count))
    );

// Wrap from 15 to 0 when enabled without reset.
    wrap_from_max: assert property (
        @(posedge clk) disable iff (reset) (enable && (count == 4'hF)) |=> (count == 4'h0)
    );

// With reset held high across cycles, count remains zero.
    reset_hold_keeps_zero: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (count == 4'h0)
    );

// With reset held high across cycles, any change in count must be due to enable.
    reset_hold_change_requires_enable: assert property (
        @(posedge clk) (reset && $past(reset) && (count != $past(count))) |-> $past(enable)
    );

// With reset held high across cycles, count cannot increment by more than 1 per cycle.
    reset_hold_increment_bound: assert property (
        @(posedge clk) (reset && $past(reset) && (count != $past(count))) |-> (count <= $past(count) + 4'd1)
    );

// With reset held high across cycles, count cannot decrement.
    reset_hold_no_decrement: assert property (
        @(posedge clk) (reset && $past(reset) && (count != $past(count))) |-> (count >= $past(count))
    );

// With reset held high across cycles, count cannot hold its value.
    reset_hold_no_hold: assert property (
        @(posedge clk) (reset && $past(reset) && (count == $past(count))) |-> 1'b0
    );

// Y matches the implemented NOR of B1 and the A1/A2 AND term.
    check_functional_equivalence: assert property (
        @(posedge clk) Y == ~(B1 | (A1 & A2))
    );

// B1 high forces the NOR output low.
    check_b1_forces_y_low: assert property (
        @(posedge clk) B1 |-> !Y
    );

// Both A inputs high force the AND term high and drive Y low.
    check_a_inputs_force_y_low: assert property (
        @(posedge clk) (A1 && A2) |-> !Y
    );

// With B1 low, a low Y requires both A inputs high.
    check_y_low_requires_a_inputs: assert property (
        @(posedge clk) (!B1 && !Y) |-> (A1 && A2)
    );

// With B1 low, a high Y requires at least one A input low.
    check_y_high_requires_a_low: assert property (
        @(posedge clk) (!B1 && Y) |-> (!A1 || !A2)
    );

// out_final matches the XOR of a and b ANDed with the XOR of c and d.
    check_out_final_function: assert property (
        @(posedge clk) out_final == ((a ^ b) & (c ^ d))
    );

// If a equals b, the first XOR term is zero and out_final must be zero.
    check_a_eq_b_forces_zero: assert property (
        @(posedge clk) (a == b) |-> (out_final == 1'b0)
    );

// If c equals d, the second XOR term is zero and out_final must be zero.
    check_c_eq_d_forces_zero: assert property (
        @(posedge clk) (c == d) |-> (out_final == 1'b0)
    );

// If both XOR terms are one, out_final must be one.
    check_both_xor_terms_one_sets_out: assert property (
        @(posedge clk) ((a ^ b) && (c ^ d)) |-> (out_final == 1'b1)
    );

// If out_final is one, both XOR terms must be one.
    check_out_one_requires_both_xor_terms_one: assert property (
        @(posedge clk) out_final |-> ((a ^ b) && (c ^ d))
    );

// If out_final is zero, at least one XOR term must be zero.
    check_out_zero_requires_some_xor_term_zero: assert property (
        @(posedge clk) !out_final |-> (!(a ^ b) || !(c ^ d))
    );

// sum must equal the 32-bit addition of a and b.
    check_sum_matches_addition: assert property (
        @(posedge clk) sum == (a + b)
    );

// Adding zero on b must pass a through unchanged.
    check_add_zero_on_b: assert property (
        @(posedge clk) (b == 32'h0000_0000) |-> (sum == a)
    );

// Adding zero on a must pass b through unchanged.
    check_add_zero_on_a: assert property (
        @(posedge clk) (a == 32'h0000_0000) |-> (sum == b)
    );

// The least-significant bit of sum must be the XOR of the LSBs of a and b.
    check_lsb_xor: assert property (
        @(posedge clk) sum[0] == (a[0] ^ b[0])
    );

// Y matches the implemented OR-then-NAND function.
    check_functional_equivalence: assert property (
        @(posedge clk) Y == ~(B1 & (A1 | A2 | A3))
    );

// B1 low forces the NAND output high.
    check_b1_low_forces_y_high: assert property (
        @(posedge clk) !B1 |-> Y
    );

// All A inputs low force the OR term low and Y high.
    check_all_a_low_forces_y_high: assert property (
        @(posedge clk) !(A1 | A2 | A3) |-> Y
    );

// B1 high with any A input high forces Y low.
    check_b1_and_any_a_high_forces_y_low: assert property (
        @(posedge clk) (B1 & (A1 | A2 | A3)) |-> !Y
    );

// A low Y requires B1 high and at least one A input high.
    check_y_low_requires_active_nand_input: assert property (
        @(posedge clk) !Y |-> (B1 & (A1 | A2 | A3))
    );

// A high Y requires B1 low or all A inputs low.
    check_y_high_requires_inactive_nand_input: assert property (
        @(posedge clk) Y |-> (!B1 | !(A1 | A2 | A3))
    );

// Reset clears the registered output on the next clock.
    check_reset_clears_output: assert property (
        @(posedge clk) reset |=> (out == 16'sd0)
    );

// X must equal the AND of A and SLEEP_B.
    check_x_matches_and: assert property (
        @(posedge clk) X == (A & SLEEP_B)
    );

// When SLEEP_B is low, X must be low.
    check_sleep_low_forces_x_low: assert property (
        @(posedge clk) !SLEEP_B |-> !X
    );

// When SLEEP_B is high, X must follow A.
    check_sleep_high_passes_a: assert property (
        @(posedge clk) SLEEP_B |-> (X == A)
    );

// When A is low, X must be low.
    check_a_low_forces_x_low: assert property (
        @(posedge clk) !A |-> !X
    );

// When A is high, X must follow SLEEP_B.
    check_a_high_passes_sleep: assert property (
        @(posedge clk) A |-> (X == SLEEP_B)
    );

// X high requires both A and SLEEP_B high.
    check_x_high_requires_both_inputs: assert property (
        @(posedge clk) X |-> (A && SLEEP_B)
    );

// Output matches the implemented mux tree.
    check_mux_tree_function: assert property (
        @(posedge clk)
        out == (sel1 ? (sel0 ? in3 : in2) : (sel0 ? in1 : in0))
    );

// When sel1 is low, the output selects between in0 and in1.
    check_sel1_low_selects_low_pair: assert property (
        @(posedge clk)
        !sel1 |-> (out == (sel0 ? in1 : in0))
    );

// When sel1 is high, the output selects between in2 and in3.
    check_sel1_high_selects_high_pair: assert property (
        @(posedge clk)
        sel1 |-> (out == (sel0 ? in3 : in2))
    );

// When sel0 is low, the output selects between in0 and in2.
    check_sel0_low_selects_even_inputs: assert property (
        @(posedge clk)
        !sel0 |-> (out == (sel1 ? in2 : (sel1 ? in3 : in0)))
    );

// With sel1 low and sel0 low, the output is in0.
    check_sel10_selects_in0: assert property (
        @(posedge clk)
        (!sel1 && !sel0) |-> (out == in0)
    );

// With sel1 low and sel0 high, the output is in1.
    check_sel10_selects_in1: assert property (
        @(posedge clk)
        (!sel1 && sel0) |-> (out == in1)
    );

// With sel1 high and sel0 low, the output is in2.
    check_sel11_selects_in2: assert property (
        @(posedge clk)
        (sel1 && !sel0) |-> (out == in2)
    );

// With sel1 high and sel0 high, the output is in3.
    check_sel11_selects_in3: assert property (
        @(posedge clk)
        (sel1 && sel0) |-> (out == in3)
    );

// Clock: clk (posedge). Reset: rst (active-low, asynchronous). Sequential counter with enable.

    // When reset is asserted low, count must be 0.
    reset_forces_zero: assert property (
        @(posedge clk) (rst == 1'b0) |-> (count == 2'b00)
    );

// When enabled and not at max, count increments by 1.
    count_increments_when_enabled: assert property (
        @(posedge clk) disable iff (!rst) (en && (count != 2'b11)) |=> (count == $past(count) + 2'b01)
    );

// When enabled and at max, count wraps to 0.
    count_wraps_when_enabled_at_max: assert property (
        @(posedge clk) disable iff (!rst) (en && (count == 2'b11)) |=> (count == 2'b00)
    );

// When disabled, count holds its value.
    count_holds_when_disabled: assert property (
        @(posedge clk) disable iff (!rst) (!en) |=> (count == $past(count))
    );

// Any change in count must be caused by reset or an enabled cycle.
    count_change_requires_enable_or_reset: assert property (
        @(posedge clk) disable iff (!rst) (count != $past(count)) |-> ($past(rst) == 1'b0 || $past(en) == 1'b1)
    );

// If reset was low on the previous cycle, count must be 0 now.
    prev_reset_low_implies_count_zero: assert property (
        @(posedge clk) $past(rst) == 1'b0 |-> (count == 2'b00)
    );

// If reset was high and enabled last cycle, count must change now.
    prev_reset_high_and_enabled_implies_change: assert property (
        @(posedge clk) disable iff (!rst) ($past(rst) && $past(en)) |-> (count != $past(count))
    );

// If reset was high and disabled last cycle, count must hold now.
    prev_reset_high_and_disabled_implies_hold: assert property (
        @(posedge clk) disable iff (!rst) ($past(rst) && !$past(en)) |-> (count == $past(count))
    );

// If count is 0 now, it must have come from 1 or wrapped from 3 last cycle.
    zero_now_has_valid_prev: assert property (
        @(posedge clk) disable iff (!rst) (count == 2'b00) |-> (($past(count) == 2'b01) || ($past(count) == 2'b11))
    );

// If count is 1 now, it must have come from 0 or incremented from 2 last cycle.
    one_now_has_valid_prev: assert property (
        @(posedge clk) disable iff (!rst) (count == 2'b01) |-> (($past(count) == 2'b00) || ($past(count) == 2'b10))
    );

// If count is 2 now, it must have come from 1 last cycle.
    two_now_has_valid_prev: assert property (
        @(posedge clk) disable iff (!rst) (count == 2'b10) |-> ($past(count) == 2'b01)
    );

// If count is 3 now, it must have come from 2 last cycle.
    three_now_has_valid_prev: assert property (
        @(posedge clk) disable iff (!rst) (count == 2'b11) |-> ($past(count) == 2'b10)
    );

// Y must equal the AND of A, B, and C.
    check_y_matches_and: assert property (
        @(posedge clk) Y == (A & B & C)
    );

// If Y is high, all inputs must be high.
    check_y_high_requires_all_inputs_high: assert property (
        @(posedge clk) Y |-> (A && B && C)
    );

// If any input is low, Y must be low.
    check_any_input_low_forces_y_low: assert property (
        @(posedge clk) (!A || !B || !C) |-> !Y
    );

// If all inputs are high, Y must be high.
    check_all_inputs_high_forces_y_high: assert property (
        @(posedge clk) (A && B && C) |-> Y
    );

// Y must equal the AND of A, B, and C.
    check_y_matches_and: assert property (
        @(posedge clk) Y == (A & B & C)
    );

// If Y is high, all inputs must be high.
    check_y_high_requires_all_inputs_high: assert property (
        @(posedge clk) Y |-> (A && B && C)
    );

// If A is low, Y must be low.
    check_a_low_forces_y_low: assert property (
        @(posedge clk) !A |-> !Y
    );

// If B is low, Y must be low.
    check_b_low_forces_y_low: assert property (
        @(posedge clk) !B |-> !Y
    );

// If C is low, Y must be low.
    check_c_low_forces_y_low: assert property (
        @(posedge clk) !C |-> !Y
    );

// If all inputs are high, Y must be high.
    check_all_inputs_high_sets_y: assert property (
        @(posedge clk) (A && B && C) |-> Y
    );

// X matches the implemented OR-then-AND function.
    check_functional_equivalence: assert property (
        @(posedge clk) X == ((A1 | A2) & B1 & C1)
    );

// B1 low forces the AND stage low and X low.
    check_b1_low_forces_x_low: assert property (
        @(posedge clk) !B1 |-> !X
    );

// C1 low forces the AND stage low and X low.
    check_c1_low_forces_x_low: assert property (
        @(posedge clk) !C1 |-> !X
    );

// Both A inputs low force the OR stage low and X low.
    check_a_inputs_low_force_x_low: assert property (
        @(posedge clk) (!A1 && !A2) |-> !X
    );

// X high requires B1, C1, and at least one A input high.
    check_x_high_requires_all_enables: assert property (
        @(posedge clk) X |-> (B1 && C1 && (A1 || A2))
    );

// With B1 and C1 high, X reduces to the OR of the A inputs.
    check_b1_c1_high_reduces_to_or: assert property (
        @(posedge clk) (B1 && C1) |-> (X == (A1 | A2))
    );

// With B1 and C1 high, X high requires at least one A input high.
    check_b1_c1_high_x_high_requires_a_or: assert property (
        @(posedge clk) (B1 && C1 && X) |-> (A1 || A2)
    );

// With B1 and C1 high, both A inputs high force X high.
    check_b1_c1_high_a_or_forces_x_high: assert property (
        @(posedge clk) (B1 && C1 && (A1 || A2)) |-> X
    );

// When S selects C, Y must equal C.
    check_select_c: assert property (
        @(posedge clk) (S == 2'b00) |-> (Y == C)
    );

// When S selects D, Y must equal D.
    check_select_d: assert property (
        @(posedge clk) (S == 2'b01) |-> (Y == D)
    );

// When S selects A, Y must equal A.
    check_select_a: assert property (
        @(posedge clk) (S == 2'b10) |-> (Y == A)
    );

// When S selects B, Y must equal B.
    check_select_b: assert property (
        @(posedge clk) (S == 2'b11) |-> (Y == B)
    );

// O is high for input 000000000001.
    check_output_high_for_000000000001: assert property (
        @(posedge clk)
        (I == 12'b000000000001) |-> O
    );

// O is high for input 000000000100.
    check_output_high_for_000000000100: assert property (
        @(posedge clk)
        (I == 12'b000000000100) |-> O
    );

// O is high for input 000000010000.
    check_output_high_for_000000010000: assert property (
        @(posedge clk)
        (I == 12'b000000010000) |-> O
    );

// O is high for input 000001000000.
    check_output_high_for_000001000000: assert property (
        @(posedge clk)
        (I == 12'b000001000000) |-> O
    );

// O is high for input 000100000000.
    check_output_high_for_000100000000: assert property (
        @(posedge clk)
        (I == 12'b000100000000) |-> O
    );

// O is high for input 010000000000.
    check_output_high_for_010000000000: assert property (
        @(posedge clk)
        (I == 12'b010000000000) |-> O
    );

// X must equal the OR of the two AND terms.
    check_x_matches_or_of_ands: assert property (
        @(posedge clk) X == ((A1 & A2 & A3) | (B1 & B2))
    );

// A high X must come from at least one asserted AND term.
    check_x_high_has_active_term: assert property (
        @(posedge clk) X |-> ((A1 & A2 & A3) | (B1 & B2))
    );

// If both AND terms are low, X must be low.
    check_x_low_when_both_terms_low: assert property (
        @(posedge clk) !(A1 & A2 & A3) && !(B1 & B2) |-> !X
    );

// If A1, A2, and A3 are all high, X must be high.
    check_x_high_when_a_term_active: assert property (
        @(posedge clk) A1 & A2 & A3 |-> X
    );

// If B1 and B2 are both high, X must be high.
    check_x_high_when_b_term_active: assert property (
        @(posedge clk) B1 & B2 |-> X
    );

// If X is low, both AND terms must be low.
    check_x_low_implies_both_terms_low: assert property (
        @(posedge clk) !X |-> !(A1 & A2 & A3) && !(B1 & B2)
    );

// Reset forces all outputs low.
    check_reset_clears_outputs: assert property (
        @(posedge reset) reset |-> (EQ == 1'b0 && GT == 1'b0 && LT == 1'b0)
    );

// When disabled, all outputs are low.
    check_disable_clears_outputs: assert property (
        @(posedge enable) !enable |-> (EQ == 1'b0 && GT == 1'b0 && LT == 1'b0)
    );

// When enabled without loads, outputs remain unchanged.
    check_hold_when_enabled_without_loads: assert property (
        @(posedge enable) enable && !load_A && !load_B |-> $stable({EQ, GT, LT})
    );

// Equal data makes EQ high and GT/LT low.
    check_equal_sets_eq: assert property (
        @(posedge enable) enable && (A == B) |-> (EQ == 1'b1 && GT == 1'b0 && LT == 1'b0)
    );

// Greater data makes GT high and EQ/LT low.
    check_greater_sets_gt: assert property (
        @(posedge enable) enable && (A > B) |-> (EQ == 1'b0 && GT == 1'b1 && LT == 1'b0)
    );

// Less data makes LT high and EQ/GT low.
    check_less_sets_lt: assert property (
        @(posedge enable) enable && (A < B) |-> (EQ == 1'b0 && GT == 1'b0 && LT == 1'b1)
    );

// EQ and GT are never asserted together.
    check_eq_gt_mutex: assert property (
        @(posedge enable) !(EQ && GT)
    );

// EQ and LT are never asserted together.
    check_eq_lt_mutex: assert property (
        @(posedge enable) !(EQ && LT)
    );

// GT and LT are never asserted together.
    check_gt_lt_mutex: assert property (
        @(posedge enable) !(GT && LT)
    );

// Output matches the implemented NAND-of-NANDs function.
    check_output_function: assert property (
        @(posedge clk) out == ~(~a & ~b)
    );

// Both inputs high drive the output high.
    check_both_inputs_high_drive_output_high: assert property (
        @(posedge clk) (a && b) |-> out
    );

// Both inputs low drive the output low.
    check_both_inputs_low_drive_output_low: assert property (
        @(posedge clk) (!a && !b) |-> !out
    );

// A low output requires at least one input low.
    check_output_low_requires_some_input_low: assert property (
        @(posedge clk) !out |-> (!a || !b)
    );

// X must equal the AND of all four inputs.
    check_and_function: assert property (
        @(posedge clk) X == (A & B & C & D)
    );

// All inputs high must drive X high.
    check_all_inputs_high_drive_x_high: assert property (
        @(posedge clk) (A & B & C & D) |-> X
    );

// X high requires all inputs high.
    check_x_high_requires_all_inputs_high: assert property (
        @(posedge clk) X |-> (A & B & C & D)
    );

// Any low input must force X low.
    check_any_input_low_forces_x_low: assert property (
        @(posedge clk) !(A & B & C & D) |-> !X
    );

// With B, C, and D high, X must follow A.
    check_x_follows_a_when_others_high: assert property (
        @(posedge clk) (B & C & D) |-> (X == A)
    );

// With A, C, and D high, X must follow B.
    check_x_follows_b_when_others_high: assert property (
        @(posedge clk) (A & C & D) |-> (X == B)
    );

// With A, B, and D high, X must follow C.
    check_x_follows_c_when_others_high: assert property (
        @(posedge clk) (A & B & D) |-> (X == C)
    );

// With A, B, and C high, X must follow D.
    check_x_follows_d_when_others_high: assert property (
        @(posedge clk) (A & B & C) |-> (X == D)
    );

// min is less than or equal to each input.
    check_min_le_inputs: assert property (
        @(posedge a[0]) (min <= a) && (min <= b) && (min <= c) && (min <= d)
    );

// If a is less than all others, min equals a.
    check_select_a_when_min: assert property (
        @(posedge a[0]) ((a < b) && (a < c) && (a < d)) |-> (min == a)
    );

// If b is less than all others, min equals b.
    check_select_b_when_min: assert property (
        @(posedge a[0]) ((b < a) && (b < c) && (b < d)) |-> (min == b)
    );

// If c is less than all others, min equals c.
    check_select_c_when_min: assert property (
        @(posedge a[0]) ((c < a) && (c < b) && (c < d)) |-> (min == c)
    );

// If d is less than all others, min equals d.
    check_select_d_when_min: assert property (
        @(posedge a[0]) ((d < a) && (d < b) && (d < c)) |-> (min == d)
    );

// If a equals b and is less than c,d, min equals a.
    check_select_a_when_a_eq_b: assert property (
        @(posedge a[0]) ((a == b) && (a < c) && (a < d)) |-> (min == a)
    );

// If c equals d and is less than a,b, min equals c.
    check_select_c_when_c_eq_d: assert property (
        @(posedge a[0]) ((c == d) && (c < a) && (c < b)) |-> (min == c)
    );

// If a equals b and c equals d, min equals the smaller of a and c.
    check_select_min_of_pairs: assert property (
        @(posedge a[0]) ((a == b) && (c == d)) |-> (min == ((a < c) ? a : c))
    );

// If a equals b and c equals d and a equals c, min equals a.
    check_select_a_when_all_equal: assert property (
        @(posedge a[0]) ((a == b) && (c == d) && (a == c)) |-> (min == a)
    );

// free3 with tm_count 3 returns 0011.
    check_free3_tm3: assert property (
        @(posedge clk) (free3 && (tm_count == 2'b11)) |-> (fifowp_inc == 4'b0011)
    );

// free2 with tm_count 2 returns 0010.
    check_free2_tm2: assert property (
        @(posedge clk) (free2 && (tm_count == 2'b10)) |-> (fifowp_inc == 4'b0010)
    );

// free2 with tm_count 1 returns 0001.
    check_free2_tm1: assert property (
        @(posedge clk) (free2 && (tm_count == 2'b01)) |-> (fifowp_inc == 4'b0001)
    );

// tm_count 0 returns 0000.
    check_tm0: assert property (
        @(posedge clk) (tm_count == 2'b00) |-> (fifowp_inc == 4'b0000)
    );

// tm_count 1 returns 0001.
    check_tm1: assert property (
        @(posedge clk) (tm_count == 2'b01) |-> (fifowp_inc == 4'b0001)
    );

// free3 has priority over free2 when both are asserted.
    check_free3_priority: assert property (
        @(posedge clk) (free3 && free2 && (tm_count == 2'b11)) |-> (fifowp_inc == 4'b0011)
    );

// tm_count 1 has priority over tm_count 0 when free2 and free3 are low.
    check_tm1_priority: assert property (
        @(posedge clk) ((tm_count == 2'b01) && !free2 && !free3) |-> (fifowp_inc == 4'b0001)
    );

// SUM matches the XOR of A, B, and inverted CIN.
    check_sum_function: assert property (
        @(posedge clk) SUM == (A ^ B ^ ~CIN)
    );

// COUT matches the majority function of A, B, and inverted CIN.
    check_cout_function: assert property (
        @(posedge clk) COUT == ((A & B) | (A & ~CIN) | (B & ~CIN))
    );

// With CIN low, COUT reduces to A OR B.
    check_cout_when_cin_low: assert property (
        @(posedge clk) !CIN |-> (COUT == (A | B))
    );

// With CIN high, COUT reduces to A AND B.
    check_cout_when_cin_high: assert property (
        @(posedge clk) CIN |-> (COUT == (A & B))
    );

// Reset clears the counter on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 2'b00)
    );

// Reset overrides enable when both are asserted.
    check_reset_priority_over_enable: assert property (
        @(posedge clk) (reset && enable) |=> (count == 2'b00)
    );

// When enabled without reset, the counter increments by one.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (reset) enable |=> (count == ($past(count) + 2'b01))
    );

// When not enabled without reset, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset) !enable |=> (count == $past(count))
    );

// The 2-bit counter wraps from 3 back to 0.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (reset) (enable && (count == 2'b11)) |=> (count == 2'b00)
    );

// EQ must equal (A==B) && (B==C) && (C==D).
    check_eq_definition: assert property (
        @(posedge A[0]) EQ == ((A == B) && (B == C) && (C == D))
    );

// GT must equal (A>B) || ((A==B) && (C>D)).
    check_gt_definition: assert property (
        @(posedge A[0]) GT == ((A > B) || ((A == B) && (C > D)))
    );

// If A>B then GT must be 1.
    check_gt_when_a_gt_b: assert property (
        @(posedge A[0]) (A > B) |-> (GT == 1'b1)
    );

// If A==B and C>D then GT must be 1.
    check_gt_when_a_eq_b_and_c_gt_d: assert property (
        @(posedge A[0]) ((A == B) && (C > D)) |-> (GT == 1'b1)
    );

// If A<B and C<=D then GT must be 0.
    check_gt_zero_when_a_lt_b_and_c_le_d: assert property (
        @(posedge A[0]) ((A < B) && (C <= D)) |-> (GT == 1'b0)
    );

// If A==B and C==D then GT must equal (A>B).
    check_gt_when_a_eq_b_and_c_eq_d: assert property (
        @(posedge A[0]) ((A == B) && (C == D)) |-> (GT == (A > B))
    );

// If A==B and C==D and A>B then GT must be 1.
    check_gt_when_all_equal_and_a_gt_b: assert property (
        @(posedge A[0]) ((A == B) && (C == D) && (A > B)) |-> (GT == 1'b1)
    );

// If A==B and C==D and A<B then GT must be 0.
    check_gt_when_all_equal_and_a_lt_b: assert property (
        @(posedge A[0]) ((A == B) && (C == D) && (A < B)) |-> (GT == 1'b0)
    );

// If A==B and C==D and A==B then GT must be 0.
    check_gt_when_all_equal_and_a_eq_b: assert property (
        @(posedge A[0]) ((A == B) && (C == D) && (A == B)) |-> (GT == 1'b0)
    );

// If A>B then EQ must be 0.
    check_eq_zero_when_a_gt_b: assert property (
        @(posedge A[0]) (A > B) |-> (EQ == 1'b0)
    );

// If A<B then EQ must be 0.
    check_eq_zero_when_a_lt_b: assert property (
        @(posedge A[0]) (A < B) |-> (EQ == 1'b0)
    );

// If A==B and B==C and C==D then EQ must be 1.
    check_eq_when_all_equal: assert property (
        @(posedge A[0]) ((A == B) && (B == C) && (C == D)) |-> (EQ == 1'b1)
    );

// If A!=B then EQ must be 0.
    check_eq_zero_when_a_ne_b: assert property (
        @(posedge A[0]) (A != B) |-> (EQ == 1'b0)
    );

// If A==B and C!=D then EQ must be 0.
    check_eq_zero_when_a_eq_b_c_ne_d: assert property (
        @(posedge A[0]) ((A == B) && (C != D)) |-> (EQ == 1'b0)
    );

// If A==B and C==D and A!=B then EQ must be 0.
    check_eq_zero_when_all_equal_but_a_ne_b: assert property (
        @(posedge A[0]) ((A == B) && (C == D) && (A != B)) |-> (EQ == 1'b0)
    );

// When bsr is HIGH, bsr is LOW on the next lpf_int edge.
    check_bsr_low_next_when_bsr_high: assert property (
        @(posedge lpf_int) bsr |-> ##1 (bsr == 1'b0)
    );

// When pr is HIGH, pr is LOW on the next lpf_int edge.
    check_pr_low_next_when_pr_high: assert property (
        @(posedge lpf_int) pr |-> ##1 (pr == 1'b0)
    );

// S is zero when the enable is low.
    check_s_zero_when_disabled: assert property (
        @(posedge clk) !En |-> (S == 4'b0000)
    );

// S is the 4-bit sum when the enable is high.
    check_s_sum_when_enabled: assert property (
        @(posedge clk) En |-> (S == (A + B + Cin))
    );

// Cout is always low in this RTL.
    check_cout_always_low: assert property (
        @(posedge clk) Cout == 1'b0
    );

// The full output vector matches the enabled sum and zero carry.
    check_full_output_when_enabled: assert property (
        @(posedge clk) En |-> ({Cout, S} == {1'b0, (A + B + Cin)})
    );

// The disabled output vector is zero.
    check_full_output_when_disabled: assert property (
        @(posedge clk) !En |-> ({Cout, S} == 5'b00000)
    );

// During active-low reset, count must be 0.
    reset_forces_zero: assert property (
        @(posedge clk) !rst |-> (count == 4'd0)
    );

// On reset deassertion, count becomes 1 in the same cycle.
    count_one_on_reset_release: assert property (
        @(posedge clk) $rose(rst) |-> (count == 4'd1)
    );

// When not in reset, count increments by 1 each cycle (mod 16).
    count_increments_when_not_reset: assert property (
        @(posedge clk) disable iff (!rst) count == $past(count) + 4'd1
    );

// When not in reset, count never holds its value (must change).
    count_changes_each_cycle: assert property (
        @(posedge clk) disable iff (!rst) count != $past(count)
    );

// When not in reset, count wraps from 15 to 0.
    count_wraps_from_max: assert property (
        @(posedge clk) disable iff (!rst) ($past(count) == 4'hF) |-> (count == 4'h0)
    );

// If count is 0 while not in reset, the previous value was 15.
    zero_implies_prev_max: assert property (
        @(posedge clk) disable iff (!rst) (count == 4'h0) |-> ($past(count) == 4'hF)
    );

// If count is 1 while not in reset, the previous value was 0.
    one_implies_prev_zero: assert property (
        @(posedge clk) disable iff (!rst) (count == 4'h1) |-> ($past(count) == 4'h0)
    );

// If count is 2 while not in reset, the previous value was 1.
    two_implies_prev_one: assert property (
        @(posedge clk) disable iff (!rst) (count == 4'h2) |-> ($past(count) == 4'h1)
    );

// If count is 15 while not in reset, the previous value was 14.
    max_implies_prev_min: assert property (
        @(posedge clk) disable iff (!rst) (count == 4'hF) |-> ($past(count) == 4'he)
    );

// If count is 14 while not in reset, the next value is 15.
    min_implies_next_max: assert property (
        @(posedge clk) disable iff (!rst) (count == 4'he) |-> ##1 (count == 4'hF)
    );

// X must equal the XOR of A and B.
    check_xor_function: assert property (
        @(posedge clk) X == (A ^ B)
    );

// When both inputs are low, X must be low.
    check_both_low: assert property (
        @(posedge clk) (!A && !B) |-> !X
    );

// When both inputs are high, X must be low.
    check_both_high: assert property (
        @(posedge clk) (A && B) |-> !X
    );

// When A is low and B is high, X must be high.
    check_a_low_b_high: assert property (
        @(posedge clk) (!A && B) |-> X
    );

// When A is high and B is low, X must be high.
    check_a_high_b_low: assert property (
        @(posedge clk) (A && !B) |-> X
    );

// X can be high only when the inputs differ.
    check_x_high_requires_mismatch: assert property (
        @(posedge clk) X |-> (A ^ B)
    );

// X can be low only when the inputs are equal.
    check_x_low_requires_match: assert property (
        @(posedge clk) !X |-> !(A ^ B)
    );

// X must equal the inverted AND of all four inputs.
    check_output_matches_inverted_and: assert property (
        @(posedge clk) X == ~(A & B & C & D)
    );

// All inputs high must drive X low.
    check_all_inputs_high_drive_x_low: assert property (
        @(posedge clk) (A & B & C & D) |-> (X == 1'b0)
    );

// A low must force X high.
    check_a_low_forces_x_high: assert property (
        @(posedge clk) !A |-> (X == 1'b1)
    );

// B low must force X high.
    check_b_low_forces_x_high: assert property (
        @(posedge clk) !B |-> (X == 1'b1)
    );

// C low must force X high.
    check_c_low_forces_x_high: assert property (
        @(posedge clk) !C |-> (X == 1'b1)
    );

// D low must force X high.
    check_d_low_forces_x_high: assert property (
        @(posedge clk) !D |-> (X == 1'b1)
    );

// X low implies all inputs are high.
    check_x_low_implies_all_inputs_high: assert property (
        @(posedge clk) (X == 1'b0) |-> (A & B & C & D)
    );

// X high implies at least one input is low.
    check_x_high_implies_some_input_low: assert property (
        @(posedge clk) (X == 1'b1) |-> (!A || !B || !C || !D)
    );

// and_out must equal the bitwise AND of a and b.
    check_and_function: assert property (
        @(posedge clk) and_out == (a & b)
    );

// or_out must equal the bitwise OR of a and b.
    check_or_function: assert property (
        @(posedge clk) or_out == (a | b)
    );

// xor_out must equal the bitwise XOR of a and b.
    check_xor_function: assert property (
        @(posedge clk) xor_out == (a ^ b)
    );

// not_out must equal the bitwise NOT of a.
    check_not_function: assert property (
        @(posedge clk) not_out == (~a)
    );

// sel=00 routes x_axis to data.
    check_sel_00_routes_x_axis: assert property (
        @(posedge clk) (sel == 2'b00) |-> (data == x_axis)
    );

// sel=01 routes y_axis to data.
    check_sel_01_routes_y_axis: assert property (
        @(posedge clk) (sel == 2'b01) |-> (data == y_axis)
    );

// sel=10 routes z_axis to data.
    check_sel_10_routes_z_axis: assert property (
        @(posedge clk) (sel == 2'b10) |-> (data == z_axis)
    );

// sel=11 routes zero-extended temp_data to data.
    check_sel_11_routes_zero_extended_temp: assert property (
        @(posedge clk) (sel == 2'b11) |-> (data == {8'h00, temp_data})
    );

// On reset, result is cleared to zero on the next cycle.
    reset_clears_result_next: assert property (
        @(posedge clk) reset |=> (result == 32'd0)
    );

// Reset forces count to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |-> (count == 4'd0)
    );

// Reset has priority over load.
    check_reset_priority_over_load: assert property (
        @(posedge clk) (rst && load) |-> (count == 4'd0)
    );

// Load captures data into count.
    check_load_captures_data: assert property (
        @(posedge clk) disable iff (rst) load |=> (count == $past(data))
    );

// Without load, count increments by one.
    check_increment_when_not_load: assert property (
        @(posedge clk) disable iff (rst) !load |=> (count == ($past(count) + 4'd1))
    );

// Count wraps from 15 back to 0.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (rst) (!load && (count == 4'hF)) |=> (count == 4'h0)
    );

// out equals in1 + in2 (4-bit wraparound).
    check_out_sum: assert property (
        @(posedge in1[0]) out == (in1 + in2)
    );

// Output must equal the bitwise AND of A and B.
    check_vector_and: assert property (
        @(posedge clk) out == (A & B)
    );

// Output bit 0 must equal A[0] AND B[0].
    check_bit0_and: assert property (
        @(posedge clk) out[0] == (A[0] & B[0])
    );

// Output bit 1 must equal A[1] AND B[1].
    check_bit1_and: assert property (
        @(posedge clk) out[1] == (A[1] & B[1])
    );

// Output bit 2 must equal A[2] AND B[2].
    check_bit2_and: assert property (
        @(posedge clk) out[2] == (A[2] & B[2])
    );

// Output bit 3 must equal A[3] AND B[3].
    check_bit3_and: assert property (
        @(posedge clk) out[3] == (A[3] & B[3])
    );

// Output bit 4 must equal A[4] AND B[4].
    check_bit4_and: assert property (
        @(posedge clk) out[4] == (A[4] & B[4])
    );

// Output bit 5 must equal A[5] AND B[5].
    check_bit5_and: assert property (
        @(posedge clk) out[5] == (A[5] & B[5])
    );

// Output bit 6 must equal A[6] AND B[6].
    check_bit6_and: assert property (
        @(posedge clk) out[6] == (A[6] & B[6])
    );

// Output bit 7 must equal A[7] AND B[7].
    check_bit7_and: assert property (
