    );

// Output bit 29 must equal A[29] AND B[29].
    check_bit29_and: assert property (
        @(posedge clk) out[29] == (A[29] & B[29])
    );

// Output bit 30 must equal A[30] AND B[30].
    check_bit30_and: assert property (
        @(posedge clk) out[30] == (A[30] & B[30])
    );

// Output bit 31 must equal A[31] AND B[31].
    check_bit31_and: assert property (
        @(posedge clk) out[31] == (A[31] & B[31])
    );

// Y matches the implemented NAND-AND function.
    check_function_equivalence: assert property (
        @(posedge clk) Y == ((~(A2 & A1)) & (~(B2 & B1)))
    );

// Both A inputs high force Y low.
    check_a_pair_high_forces_low: assert property (
        @(posedge clk) (A1 & A2) |-> !Y
    );

// Both B inputs high force Y low.
    check_b_pair_high_forces_low: assert property (
        @(posedge clk) (B1 & B2) |-> !Y
    );

// With both input pairs inactive, Y is high.
    check_both_pairs_inactive_drive_high: assert property (
        @(posedge clk) (!(A1 & A2) && !(B1 & B2)) |-> Y
    );

// A low Y requires at least one input pair to be high.
    check_low_output_has_active_pair: assert property (
        @(posedge clk) !Y |-> ((A1 & A2) || (B1 & B2))
    );

// Reset clears the counter on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

// Reset has priority over load when both are asserted.
    check_reset_priority_over_load: assert property (
        @(posedge clk) (reset && load) |=> (count == 4'b0000)
    );

// Load captures data_in when reset is low.
    check_load_captures_data: assert property (
        @(posedge clk) disable iff (reset) load |=> (count == $past(data_in))
    );

// Count increments by one when neither reset nor load is asserted.
    check_increment_when_idle: assert property (
        @(posedge clk) disable iff (reset) (!load) |=> (count == ($past(count) + 4'd1))
    );

// The counter wraps from 15 back to 0 when incrementing.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (reset) (!load && (count == 4'hF)) |=> (count == 4'h0)
    );

// Reset clears all stages on the next clock.
    check_reset_clears_all: assert property (
        @(posedge shift_clk) reset |=> (q0 == 4'b0000 && q1 == 4'b0000 && q2 == 4'b0000 && q3 == 4'b0000)
    );

// q0 captures data_in on the next clock when reset is low.
    check_q0_captures_data_in: assert property (
        @(posedge shift_clk) disable iff (reset) 1'b1 |=> (q0 == $past(data_in))
    );

// q1 captures the previous q0 value when reset is low.
    check_q1_captures_q0: assert property (
        @(posedge shift_clk) disable iff (reset) 1'b1 |=> (q1 == $past(q0))
    );

// q2 captures the previous q1 value when reset is low.
    check_q2_captures_q1: assert property (
        @(posedge shift_clk) disable iff (reset) 1'b1 |=> (q2 == $past(q1))
    );

// q3 captures the previous q2 value when reset is low.
    check_q3_captures_q2: assert property (
        @(posedge shift_clk) disable iff (reset) 1'b1 |=> (q3 == $past(q2))
    );

// The full register shifts on each clock when reset is low.
    check_register_shifts: assert property (
        @(posedge shift_clk) disable iff (reset) 1'b1 |=> (q3 == $past(q2) && q2 == $past(q1) && q1 == $past(q0) && q0 == $past(data_in))
    );

// When SEL is 0, Y must equal A.
    check_sel0_routes_a: assert property (
        @(posedge clk) (SEL === 1'b0) |-> (Y === A)
    );

// When SEL is 1, Y must equal B.
    check_sel1_routes_b: assert property (
        @(posedge clk) (SEL === 1'b1) |-> (Y === B)
    );

// When SEL is unknown, Y must be unknown.
    check_unknown_sel_gives_unknown_y: assert property (
        @(posedge clk) (SEL !== 1'b0 && SEL !== 1'b1) |-> (Y === 1'bx)
    );

// Bit 2 sum must use the ripple carry generated through bit 1.
    check_sum_bit2: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^
            (
                (A[1] & B[1]) |
                (A[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin))) |
                (B[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin)))
            )
        )
    );

// X must be high when A1, A2, and A3 are all high.
    check_x_high_when_all_a_high: assert property (
        @(posedge clk)
        (A1 & A2 & A3) |-> X
    );

// X must be high when A1, A2, and C1 are all high.
    check_x_high_when_a1_a2_c1_high: assert property (
        @(posedge clk)
        (A1 & A2 & C1) |-> X
    );

// X must be high when A1, A3, and C1 are all high.
    check_x_high_when_a1_a3_c1_high: assert property (
        @(posedge clk)
        (A1 & A3 & C1) |-> X
    );

// X must be high when A2, A3, and C1 are all high.
    check_x_high_when_a2_a3_c1_high: assert property (
        @(posedge clk)
        (A2 & A3 & C1) |-> X
    );

// Clock: clk
    // Reset: reset_n active-low, asynchronous
    // Logic: mixed sequential/combinational; reset_n_sync is a registered output

    // reset_n_sync is low whenever reset_n is low.
    check_reset_low_forces_sync_low: assert property (
        @(posedge clk) !reset_n |-> (reset_n_sync == {NUM_RESET_OUTPUT{1'b0}})
    );

// A sampled reset assertion must be reflected on reset_n_sync by the next clock.
    check_reset_assert_propagates: assert property (
        @(posedge clk) $fell(reset_n) |-> ##1 (reset_n_sync == {NUM_RESET_OUTPUT{1'b0}})
    );

// If reset_n is low, reset_n_sync must be low on the next clock.
    check_sync_low_when_reset_low: assert property (
        @(posedge clk) !reset_n |-> ##1 (reset_n_sync == {NUM_RESET_OUTPUT{1'b0}})
    );

// A sampled reset assertion must be reflected on reset_n_sync by the next clock.
    check_reset_assert_propagates_2: assert property (
        @(posedge clk) $fell(reset_n) |-> ##1 (reset_n_sync == {NUM_RESET_OUTPUT{1'b0}})
    );

// Reset drives count to zero on the next clock.
    reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

// Load captures data_in on the next clock when not in reset.
    load_captures_data: assert property (
        @(posedge clk) disable iff (reset) load |=> (count == $past(data_in))
    );

// When not loading and up_down=1, count increments by 1 on the next clock.
    increment_when_up: assert property (
        @(posedge clk) disable iff (reset) (!load && up_down) |=> (count == $past(count) + 4'd1)
    );

// When not loading and up_down=0, count decrements by 1 on the next clock.
    decrement_when_down: assert property (
        @(posedge clk) disable iff (reset) (!load && !up_down) |=> (count == $past(count) - 4'd1)
    );

// With no load and both directions asserted (both 1), count holds its value.
    hold_when_both_high: assert property (
        @(posedge clk) disable iff (reset) (!load && up_down && !up_down) |=> (count == $past(count))
    );

// Incrementing from 4'hF wraps to 4'h0 on the next clock.
    increment_wraparound: assert property (
        @(posedge clk) disable iff (reset) (!load && up_down && (count == 4'hF)) |=> (count == 4'h0)
    );

// Decrementing from 4'h0 wraps to 4'hF on the next clock.
    decrement_wraparound: assert property (
        @(posedge clk) disable iff (reset) (!load && !up_down && (count == 4'h0)) |=> (count == 4'hF)
    );

// Load has priority over direction when both are asserted.
    load_priority_over_direction: assert property (
        @(posedge clk) disable iff (reset) (load && up_down && !up_down) |=> (count == $past(data_in))
    );

// Y must always be the logical inverse of A.
    check_inverter_function: assert property (
        @(posedge clk) Y == ~A
    );

// A low input must produce a high output.
    check_low_input_high_output: assert property (
        @(posedge clk) (A == 1'b0) |-> (Y == 1'b1)
    );

// A high input must produce a low output.
    check_high_input_low_output: assert property (
        @(posedge clk) (A == 1'b1) |-> (Y == 1'b0)
    );

// A high output must come from a low input.
    check_high_output_low_input: assert property (
        @(posedge clk) (Y == 1'b1) |-> (A == 1'b0)
    );

// A low output must come from a high input.
    check_low_output_high_input: assert property (
        @(posedge clk) (Y == 1'b0) |-> (A == 1'b1)
    );

// blank forces all segments on.
    check_blank_forces_all_segments: assert property (
        @(posedge clk) blank |-> (s7 == ~7'b0000000)
    );

// minus forces only the decimal point on.
    check_minus_forces_decimal_point: assert property (
        @(posedge clk) (!blank && minus) |-> (s7 == ~7'b1000000)
    );

// value 0 maps to 0111111.
    check_value_0_mapping: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'h0)) |-> (s7 == ~7'b0111111)
    );

// value 1 maps to 0000110.
    check_value_1_mapping: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'h1)) |-> (s7 == ~7'b0000110)
    );

// value 2 maps to 1011011.
    check_value_2_mapping: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'h2)) |-> (s7 == ~7'b1011011)
    );

// value 3 maps to 1001111.
    check_value_3_mapping: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'h3)) |-> (s7 == ~7'b1001111)
    );

// value 4 maps to 1100110.
    check_value_4_mapping: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'h4)) |-> (s7 == ~7'b1100110)
    );

// value 5 maps to 1101101.
    check_value_5_mapping: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'h5)) |-> (s7 == ~7'b1101101)
    );

// value 6 maps to 1111101.
    check_value_6_mapping: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'h6)) |-> (s7 == ~7'b1111101)
    );

// value 7 maps to 0000111.
    check_value_7_mapping: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'h7)) |-> (s7 == ~7'b0000111)
    );

// value 8 maps to 1111111.
    check_value_8_mapping: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'h8)) |-> (s7 == ~7'b1111111)
    );

// value 9 maps to 1101111.
    check_value_9_mapping: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'h9)) |-> (s7 == ~7'b1101111)
    );

// value A maps to 1110111.
    check_value_a_mapping: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'hA)) |-> (s7 == ~7'b1110111)
    );

// value B maps to 1111100.
    check_value_b_mapping: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'hB)) |-> (s7 == ~7'b1111100)
    );

// value C maps to 0111001.
    check_value_c_mapping: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'hC)) |-> (s7 == ~7'b0111001)
    );

// value D maps to 1011110.
    check_value_d_mapping: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'hD)) |-> (s7 == ~7'b1011110)
    );

// value E maps to 1111001.
    check_value_e_mapping: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'hE)) |-> (s7 == ~7'b1111001)
    );

// value F maps to 1110001.
    check_value_f_mapping: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'hF)) |-> (s7 == ~7'b1110001)
    );

// Y matches the implemented NAND/OR/NAND/BUF function.
    check_y_function: assert property (
        @(posedge clk) Y == ~((~(A2_N & A1_N)) & (B2 | B1))
    );

// All NAND inputs high force Y high.
    check_all_nand_inputs_high_drive_y_high: assert property (
        @(posedge clk) (A1_N & A2_N & ~B1 & ~B2) |-> Y
    );

// Both B inputs low force Y high.
    check_b_inputs_low_drive_y_high: assert property (
        @(posedge clk) (~B1 & ~B2) |-> Y
    );

// RTL is combinational and has no reset; clk is a sampling clock.

    // Output matches the implemented two-stage barrel-shifter behavior.
    check_output_matches_two_stage_shift: assert property (
        @(posedge clk)
        out == ((dir == 1'b0) ? ((in << shift) << shift) : ((in >> shift) >> shift))
    );

// A zero shift amount passes the input through unchanged.
    check_zero_shift_passthrough: assert property (
        @(posedge clk)
        (shift == 4'd0) |-> (out == in)
    );

// A zero direction value uses left shift in both stages.
    check_left_direction_two_stage: assert property (
        @(posedge clk)
        (dir == 1'b0) |-> (out == ((in << shift) << shift))
    );

// A one direction value uses right shift in both stages.
    check_right_direction_two_stage: assert property (
        @(posedge clk)
        (dir == 1'b1) |-> (out == ((in >> shift) >> shift))
    );

// A zero direction value with a zero shift amount passes the input through unchanged.
    check_left_zero_shift_passthrough: assert property (
        @(posedge clk)
        (dir == 1'b0 && shift == 4'd0) |-> (out == in)
    );

// A one direction value with a zero shift amount passes the input through unchanged.
    check_right_zero_shift_passthrough: assert property (
        @(posedge clk)
        (dir == 1'b1 && shift == 4'd0) |-> (out == in)
    );

// Clock: s_aclk (posedge). Reset: AR (synchronous, active-high). Sequential counter with wrap at 15.

    // AR high forces Q to 0 on the next cycle.
    reset_sets_zero_next: assert property (
        @(posedge s_aclk) AR |=> (Q == 4'b0000)
    );

// When E is high and Q is not 15, Q increments by 1 on the next cycle.
    increment_when_enabled_not_max: assert property (
        @(posedge s_aclk) disable iff (AR) (E && (Q != 4'hF)) |=> (Q == $past(Q) + 4'd1)
    );

// When E is high and Q is 15, Q wraps to 0 on the next cycle.
    wrap_when_enabled_at_max: assert property (
        @(posedge s_aclk) disable iff (AR) (E && (Q == 4'hF)) |=> (Q == 4'h0)
    );

// When E is low, Q holds its value on the next cycle.
    hold_when_disabled: assert property (
        @(posedge s_aclk) disable iff (AR) (!E) |=> (Q == $past(Q))
    );

// If E and Q are not 15 in the same cycle, Q must change on the next cycle.
    enable_changes_when_not_max: assert property (
        @(posedge s_aclk) disable iff (AR) (E && (Q != 4'hF)) |=> (Q != $past(Q))
    );

// If E and Q are 15 in the same cycle, Q must wrap to 0 on the next cycle.
    enable_wraps_when_max: assert property (
        @(posedge s_aclk) disable iff (AR) (E && (Q == 4'hF)) |=> (Q == 4'h0)
    );

// If AR and E are both high in the same cycle, AR has priority and Q becomes 0 on the next cycle.
    reset_priority_over_enable: assert property (
        @(posedge s_aclk) (AR && E) |=> (Q == 4'h0)
    );

// If E is high and Q is not 15, Q must change on the next cycle.
    increment_changes_when_not_max: assert property (
        @(posedge s_aclk) disable iff (AR) (E && (Q != 4'hF)) |=> (Q != $past(Q))
    );

// If E is high and Q is 15, Q must change on the next cycle (wrap to 0).
    wrap_changes_when_max: assert property (
        @(posedge s_aclk) disable iff (AR) (E && (Q == 4'hF)) |=> (Q != $past(Q))
    );

// Reset drives out to zero on the next clock.
    reset_clears_out_next: assert property (
        @(posedge clk) reset |=> (out == 4'b0000)
    );

// With load asserted, out captures data[3:0] on the next clock.
    load_captures_data: assert property (
        @(posedge clk) disable iff (reset) load |=> (out == $past(data[3:0]))
    );

// With select asserted and load deasserted, out captures {in[2:0], in[3]}.
    select_captures_rotated_in: assert property (
        @(posedge clk) disable iff (reset) (!load && select) |=> (out == { $past(in[2:0]), $past(in[3]) })
    );

// With neither load nor select asserted, out captures {in[0], in[3:1]}.
    rotate_left_captures_in: assert property (
        @(posedge clk) disable iff (reset) (!load && !select) |=> (out == { $past(in[0]), $past(in[3:1]) })
    );

// With both load and select asserted, load has priority and data[3:0] is captured.
    load_priority_over_select: assert property (
        @(posedge clk) disable iff (reset) (load && select) |=> (out == $past(data[3:0]))
    );

// 0 maps to 0.
    check_map_0000000000: assert property (
        @(posedge clk) (input_val == 10'b0000000000) |-> (binary_val == 4'b0000)
    );

// 1 maps to 1.
    check_map_0000000001: assert property (
        @(posedge clk) (input_val == 10'b0000000001) |-> (binary_val == 4'b0001)
    );

// 2 maps to 2.
    check_map_0000000010: assert property (
        @(posedge clk) (input_val == 10'b0000000010) |-> (binary_val == 4'b0010)
    );

// 3 maps to 3.
    check_map_0000000011: assert property (
        @(posedge clk) (input_val == 10'b0000000011) |-> (binary_val == 4'b0011)
    );

// 4 maps to 4.
    check_map_0000000100: assert property (
        @(posedge clk) (input_val == 10'b0000000100) |-> (binary_val == 4'b0100)
    );

// 5 maps to 5.
    check_map_0000000101: assert property (
        @(posedge clk) (input_val == 10'b0000000101) |-> (binary_val == 4'b0101)
    );

// 6 maps to 6.
    check_map_0000000110: assert property (
        @(posedge clk) (input_val == 10'b0000000110) |-> (binary_val == 4'b0110)
    );

// 7 maps to 7.
    check_map_0000000111: assert property (
        @(posedge clk) (input_val == 10'b0000000111) |-> (binary_val == 4'b0111)
    );

// 8 maps to 8.
    check_map_0000001000: assert property (
        @(posedge clk) (input_val == 10'b0000001000) |-> (binary_val == 4'b1000)
    );

// 9 maps to 9.
    check_map_0000001001: assert property (
        @(posedge clk) (input_val == 10'b0000001001) |-> (binary_val == 4'b1001)
    );

// All other input values map to 0.
    check_default_map: assert property (
        @(posedge clk) (input_val >= 10'b0000001010) |-> (binary_val == 4'b0000)
    );

// A low A1 forces X low.
    check_a1_low_forces_x_low: assert property (
        @(posedge clk) !A1 |-> !X
    );

// A low A2 forces X low.
    check_a2_low_forces_x_low: assert property (
        @(posedge clk) !A2 |-> !X
    );

// A high B1_N forces X low.
    check_b1n_high_forces_x_low: assert property (
        @(posedge clk) B1_N |-> !X
    );

// With A1 and A2 low, X must be low regardless of B1_N.
    check_a1_a2_low_force_x_low: assert property (
        @(posedge clk) (!A1 && !A2) |-> !X
    );

// With B1_N high, X must be low regardless of A1 and A2.
    check_b1n_high_force_x_low: assert property (
        @(posedge clk) B1_N |-> !X
    );

// Reset forces count to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |-> (count == 4'b0000)
    );

// Count increments by one when not at 9.
    check_count_increments: assert property (
        @(posedge clk) disable iff (rst)
        (count != 4'b1001) |=> (count == ($past(count) + 4'b0001))
    );

// Count wraps from 9 back to 0.
    check_count_wraps: assert property (
        @(posedge clk) disable iff (rst)
        (count == 4'b1001) |=> (count == 4'b0000)
    );

// Count never takes the invalid value 10.
    check_count_valid_range: assert property (
        @(posedge clk) disable iff (rst)
        (count != 4'b1010)
    );

// X must equal the inverted OR of all inputs.
    check_functional_equivalence: assert property (
        @(posedge clk) X == ~(A_N | B | C | D)
    );

// All inputs low must drive X high.
    check_all_inputs_low_drives_x_high: assert property (
        @(posedge clk) (!A_N && !B && !C && !D) |-> X
    );

// A_N high must force X low.
    check_a_n_high_forces_x_low: assert property (
        @(posedge clk) A_N |-> !X
    );

// B high must force X low.
    check_b_high_forces_x_low: assert property (
        @(posedge clk) B |-> !X
    );

// C high must force X low.
    check_c_high_forces_x_low: assert property (
        @(posedge clk) C |-> !X
    );

// D high must force X low.
    check_d_high_forces_x_low: assert property (
        @(posedge clk) D |-> !X
    );

// X high implies all inputs are low.
    check_x_high_implies_all_inputs_low: assert property (
        @(posedge clk) X |-> (!A_N && !B && !C && !D)
    );

// X low implies at least one input is high.
    check_x_low_implies_some_input_high: assert property (
        @(posedge clk) !X |-> (A_N || B || C || D)
    );

// Load captures data_in into data_out on the next clock.
    check_load_captures_data: assert property (
        @(posedge clk) load |=> (data_out == $past(data_in))
    );

// When not loading, data_out rotates left by one bit.
    check_rotate_when_not_loading: assert property (
        @(posedge clk) !load |=> (data_out == {$past(data_out[2:0]), $past(data_out[3])})
    );

// The LSB takes the previous MSB when rotating.
    check_rotate_lsb_from_msb: assert property (
        @(posedge clk) !load |=> (data_out[0] == $past(data_out[3]))
    );

// The next three bits take the previous three lower bits when rotating.
    check_rotate_upper_bits_from_lower: assert property (
        @(posedge clk) !load |=> (data_out[3:1] == $past(data_out[2:0]))
    );

// Four consecutive rotates return data_out to its original value.
    check_four_rotate_cycle_identity: assert property (
        @(posedge clk) (!load)[*4] |=> (data_out == $past(data_out, 4))
    );

// Y must match the implemented AND-with-inverted-C function.
    check_y_matches_function: assert property (
        @(posedge clk) Y == (A & B & ~C)
    );

// Y can be high only when A, B, and inverted C are all high.
    check_y_high_requires_inputs: assert property (
        @(posedge clk) Y |-> (A && B && !C)
    );

// With A and B high, Y must equal inverted C.
    check_y_equals_not_c_when_ab_high: assert property (
        @(posedge clk) (A && B) |-> (Y == ~C)
    );

// With inverted C low, Y must equal A AND B.
    check_y_equals_ab_when_c_not_inverted: assert property (
        @(posedge clk) !C |-> (Y == (A & B))
    );

// With inverted C high and B high, Y must equal A.
    check_y_equals_a_when_c_inverted_and_b_high: assert property (
        @(posedge clk) (!C && B) |-> (Y == A)
    );

// With inverted C high and A high, Y must equal B.
    check_y_equals_b_when_c_inverted_and_a_high: assert property (
        @(posedge clk) (!C && A) |-> (Y == B)
    );

// With inverted C low and B low, Y must be low.
    check_y_low_when_c_not_inverted_and_b_low: assert property (
        @(posedge clk) (!C && !B) |-> !Y
    );

// With inverted C low and A low, Y must be low.
    check_y_low_when_c_not_inverted_and_a_low: assert property (
        @(posedge clk) (!C && !A) |-> !Y
    );

// X must match the implemented OR-of-terms function.
    check_x_matches_or_function: assert property (
        @(posedge clk) X == (A1 & A2) | B1 | C1
    );

// B1 high must force X high.
    check_b1_forces_x_high: assert property (
        @(posedge clk) B1 |-> X
    );

// C1 high must force X high.
    check_c1_forces_x_high: assert property (
        @(posedge clk) C1 |-> X
    );

// A1 and A2 high together must force X high.
    check_a1_a2_force_x_high: assert property (
        @(posedge clk) (A1 & A2) |-> X
    );

// With B1 and C1 low, X reduces to the A1&A2 term.
    check_no_b1_c1_reduces_to_and_term: assert property (
        @(posedge clk) (!B1 && !C1) |-> (X == (A1 & A2))
    );

// With A1 and A2 low, X reduces to the OR of B1 and C1.
    check_no_a1_a2_reduces_to_b1_or_c1: assert property (
        @(posedge clk) (!A1 && !A2) |-> (X == (B1 | C1))
    );

// If X is low, both B1 and C1 must be low and not both A1 and A2 can be high.
    check_x_low_requires_no_b1_c1_and_not_both_a1_a2: assert property (
        @(posedge clk) !X |-> (!B1 && !C1 && !(A1 && A2))
    );

// If X is high, at least one OR input term must be true.
    check_x_high_requires_some_input_term: assert property (
        @(posedge clk) X |-> (B1 || C1 || (A1 && A2))
    );

// CLR_B forces Q to zero on the next clock.
    check_clear_sets_zero: assert property (
        @(posedge CLK) disable iff (1'b0)
        CLR_B |=> (Q == 5'd0)
    );

// LOAD captures DATA_IN when CLR_B is low.
    check_load_captures_data: assert property (
        @(posedge CLK) disable iff (1'b0)
        (!CLR_B && LOAD) |=> (Q == $past(DATA_IN))
    );

// Q increments by one when CLR_B and LOAD are low and Q is not at MAX_VALUE.
    check_increment_when_not_max: assert property (
        @(posedge CLK) disable iff (1'b0)
        (!CLR_B && !LOAD && (Q != MAX_VALUE)) |=> (Q == ($past(Q) + 5'd1))
    );

// Q wraps to zero when CLR_B and LOAD are low and Q is at MAX_VALUE.
    check_wrap_when_max: assert property (
        @(posedge CLK) disable iff (1'b0)
        (!CLR_B && !LOAD && (Q == MAX_VALUE)) |=> (Q == 5'd0)
    );

// LOAD has priority over the increment/wrap behavior.
    check_load_priority_over_increment: assert property (
        @(posedge CLK) disable iff (1'b0)
        (!CLR_B && LOAD && (Q == MAX_VALUE)) |=> (Q == $past(DATA_IN))
    );

// Y must always equal the XNOR of A and B.
    check_xnor_function: assert property (
        @(posedge clk) Y == ~(A ^ B)
    );

// When both inputs are low, Y must be high.
    check_xnor_00: assert property (
        @(posedge clk) (!A && !B) |-> Y
    );

// When both inputs are high, Y must be high.
    check_xnor_11: assert property (
        @(posedge clk) (A && B) |-> Y
    );

// When the inputs differ, Y must be low.
    check_xnor_mismatch: assert property (
        @(posedge clk) (A ^ B) |-> !Y
    );

// A high Y means the inputs must match.
    check_xnor_high_matches: assert property (
        @(posedge clk) Y |-> !(A ^ B)
    );

// A low Y means the inputs must differ.
    check_xnor_low_mismatch: assert property (
        @(posedge clk) !Y |-> (A ^ B)
    );

// A high gated_clk requires previous clk_en was high.
    check_gated_high_requires_prev_en: assert property (
        @(posedge src_clk) gated_clk |-> $past(clk_en)
    );

// A high gated_clk requires current src_clk is high.
    check_gated_high_requires_src_high: assert property (
        @(posedge src_clk) gated_clk |-> src_clk
    );

// If previous clk_en was low, gated_clk must be low now.
    check_prev_en_low_forces_gated_low: assert property (
        @(posedge src_clk) !$past(clk_en) |-> !gated_clk
    );

// If current src_clk is low, gated_clk must be low now.
    check_src_low_forces_gated_low: assert property (
        @(posedge src_clk) !src_clk |-> !gated_clk
    );

// If previous clk_en was high, gated_clk equals current src_clk.
    check_prev_en_high_implies_gated_eq_src: assert property (
        @(posedge src_clk) $past(clk_en) |-> (gated_clk == src_clk)
    );

// If current src_clk is high, gated_clk equals previous clk_en.
    check_src_high_implies_gated_eq_prev_en: assert property (
        @(posedge src_clk) src_clk |-> (gated_clk == $past(clk_en))
    );

// If previous clk_en was high and current src_clk is high, gated_clk is high.
    check_prev_en_high_and_src_high_implies_gated_high: assert property (
        @(posedge src_clk) ($past(clk_en) && src_clk) |-> gated_clk
    );

// If previous clk_en was low and current src_clk is high, gated_clk is low.
    check_prev_en_low_and_src_high_implies_gated_low: assert property (
        @(posedge src_clk) (!$past(clk_en) && src_clk) |-> !gated_clk
    );

// If previous clk_en was high and current src_clk is low, gated_clk is low.
    check_prev_en_high_and_src_low_implies_gated_low: assert property (
        @(posedge src_clk) ($past(clk_en) && !src_clk) |-> !gated_clk
    );

// Y must always match the mux select equation.
    check_mux_equation: assert property (
        @(posedge clk) Y == (SEL ? B : A)
    );

// When SEL is low, Y must follow A.
    check_select_low_routes_a: assert property (
        @(posedge clk) !SEL |-> (Y == A)
    );

// When SEL is high, Y must follow B.
    check_select_high_routes_b: assert property (
        @(posedge clk) SEL |-> (Y == B)
    );

// MO must always match the mux select expression.
    check_mux_function: assert property (
        @(posedge clk) MO === ((S == 1'b1) ? B : A)
    );

// When S is low, MO must select A.
    check_select_low_routes_a: assert property (
        @(posedge clk) (S === 1'b0) |-> (MO === A)
    );

// When S is high, MO must select B.
    check_select_high_routes_b: assert property (
        @(posedge clk) (S === 1'b1) |-> (MO === B)
    );

// If both inputs are equal, MO must equal that common value.
    check_equal_inputs_passthrough: assert property (
        @(posedge clk) (A === B) |-> (MO === A)
    );
